// CLI and the Rust host read the `std/` dir directly).

/** Module key (`std:NAME`) → that std module's source. */
export const STD_SOURCES: Record<string, string> = {
  "std:args": "// `std:args` — the program's command-line arguments, and the last piece of VL's\n// I/O tier. ADMITTED BY `docs/internals/std-design.md` D2's inventory clause —\n// \"what the LANGUAGE story needs to be complete without third parties … fs/io/args\n// once WASI lands\", which names it outright — and NOT by \"a consumer in the tree\",\n// because there is none yet; converting `fuzzgen.vl`'s sed-rewritten flags is the\n// FOLLOW-UP, not the warrant. ONE EXPORT, `programArgs()`, is the whole surface.\n//\n// INDEX 0 IS THE FIRST USER ARGUMENT. There is no program name in the list and\n// no export returns one — that is the FLOOR's shape, not a re-indexing applied\n// here, so `x.slice(1)` is the habit to unlearn rather than a step to keep.\n//\n// NAMED `programArgs` AND NOT `args`: VL has no namespace import, and a module\n// that both imports and declares a name is a HARD PARSE ERROR, so an export\n// `args` would make `const args = args()` refuse to compile; `argv` promises the\n// C layout this floor lacks. NOT `self`-FIRST — argv has no receiver.\n//\n// A LIST, NOT `argCount()` + `argAt(i)`: `string[]` reaches the generic surface\n// where an index protocol composes with nothing, and `.length` plus VL's ordinary\n// bounds-checked `[i]` dissolves out-of-range instead of answering it.\n//\n// FALLIBLE, AND THE FAILURE ARM IS CURRENTLY UNREACHABLE: the floor hands over\n// `u8[]` and a POSIX argument is any NUL-free byte string, but both Rust hosts\n// read `std::env::args()`, which panics before VL is instantiated. It ships\n// anyway because widening a return type later is the breaking change std has no\n// deprecation story for. THE FAILURE IS `Utf8Error`, BORROWED not invented: one\n// failure domain, and a new `ArgError = { code: i32, msg: string }` would be\n// structurally identical to `std:fs`'s `IoError`. ALL OR NOTHING — one argument\n// that is not UTF-8 fails the WHOLE call; dropping it would RENUMBER the rest.\n//\n// THE ERRNO STAYS INSIDE — the empty-plus-errno protocol is read once in the\n// loop, so this API has no ambient state and no order-dependent call. The ONE\n// `__trap__` fires only if the floor refuses an index below its own count.\n//\n// NOT HERE, EACH FOR A REASON. NO FLAG PARSING: clustering, `--name=value`, `--`,\n// repeated flags and typed defaults are each a policy a half-parser would settle\n// silently, and none needs a new floor intrinsic. NO BYTES ACCESSOR and NO LOSSY\n// VARIANT: every `std:fs` entry takes `path: string`, so non-text argument bytes\n// could not open the file they name. NO ENVIRONMENT, EXIT CODE, NAME or STDIN.\n\nimport { Utf8Error, decodeUtf8 } from \"std:utf8\"\n// `toString` is `std:fmt`'s export as of 2026-09-01, not the ambient builtin it was\n// (owner ruling, DECISIONS.md). One index rendering here needs it. `std:utf8` above\n// already pulls `std:fmt` in for the same reason, so this import adds a NAME and no\n// bytes; the price and why a private renderer was refused are in `std:utf8`'s header.\nimport { toString } from \"std:fmt\"\n\n// RE-EXPORTED so a caller of the fallible export can spell its own error arm from\n// the module it imported: `import { Utf8Error, programArgs } from \"std:args\"`.\n// Without this the caller needs a second import from `std:utf8` to write the `is`\n// branch, which is a tax this module otherwise works hard to avoid. It is not a\n// second `Utf8Error` — a re-export records a NAME, so there is exactly one type;\n// and it costs nothing, measured: the import section stays at three host imports,\n// all of them called. `compiler/emit_base.vl` republishes seven type names from\n// `typecheck.vl` on the same mechanism.\nexport { Utf8Error } from \"std:utf8\"\n\n// `programArgs()` — every argument the program was given, in order, as text. Index 0\n// is the FIRST USER ARGUMENT and there is no program name in the list (see the\n// header). No arguments is an EMPTY ARRAY, never an error and never null: being given\n// nothing is not a failure, it is the answer. The failure is a single argument that is\n// not UTF-8, reported as `std:utf8`'s `Utf8Error` with `at` and `byte` keeping that\n// module's meanings. WHICH argument is named in `msg` only — a fourth field would fork\n// the error vocabulary for a fact no caller can act on.\n//\n// ONE HOST WART, INVISIBLE FROM IN HERE: `vl run p.vl -v x` delivers ONE argument,\n// because the host discards unknown dash-led tokens with no diagnostic, while\n// `vl run p.vl -- -v x` delivers both — and nothing here can tell a dropped argument\n// from an un-passed one. `tests/vl_std_args_test.ts` pins it (#1818).\nexport function programArgs(): string[] | Utf8Error {\n  const n = __args_count__()\n  const out: string[] = []\n  let i = 0\n  while i < n {\n    const raw = __args_get__(i)\n    // EMPTY is the floor's failure signal AND a legitimate argument — `\"\"` is a\n    // real thing to pass — so the errno is what separates them, exactly as\n    // `std:fs` separates a failed read from an empty file. Inside\n    // `0 .. __args_count__()` the floor answers by contract, so a non-zero errno\n    // is a HOST contradicting its own count: a BUG no caller can cause or\n    // recover from, hence a trap. Not checking is what would put a blank\n    // argument in a real position, since `decodeUtf8` of an empty array is `\"\"`.\n    // The trap is unreachable at both Rust hosts only because `__args_get__`\n    // ZEROES THE SHARED ERRNO CELL on success, so it rests on a `std:fs` FLOOR\n    // INVARIANT and not on anything local — `PROGRAM_ARGS` being immutable does\n    // NOT guard it, because the adversarial case is a dirty cell left by an\n    // unrelated failed `std:fs` call followed by a legitimately empty argument.\n    if raw.length == 0 {\n      if __fs_errno__() != 0 {\n        __trap__(\"std:args: the floor refused an index below __args_count__()\")\n      }\n    }\n    const s = decodeUtf8(raw)\n    if s is Utf8Error {\n      // Re-spelled as a literal rather than forwarded, so the message names the\n      // argument; a struct produced by a CALL and flowing into a union position\n      // does not lower at this head (`std:fs`'s header records the same\n      // constraint), so every error out of this module is written where it is\n      // returned.\n      return {\n        at: s.at,\n        byte: s.byte,\n        msg: \"args.programArgs: argument \" +\n          toString(i) +\n          \" is not UTF-8: \" +\n          s.msg,\n      }\n    }\n    out.push(s)\n    i = i + 1\n  }\n  out\n}\n",
  "std:array": "// `std:array` — pure-VL array/list helpers over the intrinsic floor (the emitter\n// provides `.push` / `.length` / indexing / `map` / `filter`; these are written in\n// VL on top, the array dual of `std:fmt`). Each takes a `self` first parameter so it\n// reads as a UFCS method (`xs.indexOf(3)`), and all are GENERIC in the element type\n// `T`, with `==` resolving per element type. Three families: SEARCH (an i32 or a\n// boolean, building nothing), BUILDING (`reverse`, `concat`, `mapIndexed`, `sorted`,\n// each returning a NEW list), and the ORDERING pair `sort`/`sorted`.\n//\n// EXACTLY ONE EXPORT MUTATES ITS RECEIVER — `sort` — and what that buys is that\n// mutation is VISIBLE IN THE NAME: VL lists are REFERENCE types with no ownership\n// discipline, so a mutating helper reorders every other binding that aliases the\n// same list, and the only one that does it is named with the bare imperative verb.\n//\n// HOW FAR THE GENERIC SURFACE REACHES, per EXPORT and per ARGUMENT SHAPE rather than\n// \"X works\". ADMITTED at every position — element, `needle`, `reduce` accumulator,\n// callback result: `i32`, `i64`, `f64`, `boolean`, `string`, nested lists, and STRING\n// or NUMERIC LITERAL UNIONS. At `needle` ONLY: a nullable REF NICHE and the two\n// i32-sentinel nullables (`K | null` over a string literal union, `boolean | null`),\n// which stay LOUD at `sorted`/`sort`'s comparator and `mapIndexed`'s `U`. A MAP\n// ELEMENT is admitted at `mapIndexed` and `sorted` and refused at the four `needle`\n// exports, where the axis is equatability and a map has no compare core.\n//\n// THE LIVE CARVE-OUT IS LOUD, and it is one mechanism at two spellings: an ANONYMOUS\n// OBJECT SHAPE the generic boundary cannot name — a callback result with nothing\n// declared, at either container, and a receiver whose struct element has NO STRUCT\n// ROW. REMEDY: give the shape a NAME the boundary can see. A `type` declaration mints\n// a row and never has to be referenced, and so does ANY inline annotation of that\n// layout anywhere in the program — a binding, a parameter, a return type.\n//\n// A LITERAL UNION IS ADMITTED AT EVERY POSITION AND EVERY DELIVERY, the nullable ones\n// included. The one load-bearing spelling is a LAMBDA's return annotation: a bare\n// `\"y\"` in an unannotated lambda infers `string`, so the failure without it is an\n// HONEST check error rather than a surprise. ORDERING (`<` `>` `<=` `>=`) OVER A\n// STRING LITERAL UNION COMPARES MEMBER TEXT at every spelling of the operand; a\n// NUMERIC alias keeps the numeric compare, which is both correct for it and cheaper.\n//\n// `u8[]` IS OUTSIDE THE SURFACE AT EVERY SPELLING, direct and UFCS alike, and it is a\n// CHECKER ERROR: `T` ranges over value types and `u8` is storage, so a `u8[]` is not\n// an instantiation of `T[]`. `tests/cases/std/error-u8-array-generic.vl` runs the\n// pair side by side. Byte sequences belong to `std:utf8`, whose exports take `u8[]`.\n\n// The index of the FIRST element equal to `needle`, or -1 if absent. `==` is the\n// element type's equality (value for scalars and strings, reference for functions).\n// A BARE MEMBER LITERAL as the `needle` over a literal-union array (`xs.indexOf(\"b\")`\n// on a `(\"a\" | \"b\")[]`) is fine, at both scopes, here and on `lastIndexOf`, `includes`\n// and `count`. Pinned as `tests/cases/std/array-litunion-needle.vl`.\n//\n// A `needle: T` THE CHECKER WILL NOT `==` IS REFUSED AT `vl check`, IN THE DIRECT\n// SPELLING'S OWN WORDS — the message names the callee and then repeats what `a == b`\n// would say. THE AXIS IS EQUATABILITY OF `T`, NOT THE STRUCT: a list whose ELEMENT is\n// itself non-equatable fails the structural gate AND has no list core, so both sentences\n// fire on one call. `isEquatable` and `eqCmpKindOfTy` both ride the PIN rather than\n// answering about the bare `TyVar`, which is what makes every route agree.\nexport function indexOf<T>(self: T[], needle: T): i32 {\n  let i = 0\n  while i < self.length {\n    if self[i] == needle { return i }\n    i = i + 1\n  }\n  return -1\n}\n\n// The index of the LAST element equal to `needle`, or -1 if absent.\nexport function lastIndexOf<T>(self: T[], needle: T): i32 {\n  let i = self.length - 1\n  while i >= 0 {\n    if self[i] == needle { return i }\n    i = i - 1\n  }\n  return -1\n}\n\n// Whether any element equals `needle`.\nexport function includes<T>(self: T[], needle: T): boolean {\n  let i = 0\n  while i < self.length {\n    if self[i] == needle { return true }\n    i = i + 1\n  }\n  return false\n}\n\n// How many elements equal `needle`.\nexport function count<T>(self: T[], needle: T): i32 {\n  let c = 0\n  let i = 0\n  while i < self.length {\n    if self[i] == needle { c = c + 1 }\n    i = i + 1\n  }\n  return c\n}\n\n// Left fold: thread `acc` (seeded with `init`) through `f(acc, element)` for each\n// element in order, returning the final accumulator. The accumulator type `A` may\n// differ from the element type `T` (summing an `i32[]` to an `i32`, joining a\n// `string[]` to a `string`, summing an `f64[]` to an `f64`). The generic closure\n// parameter `f: (A, T) => A` is monomorphized per call shape.\n//\n// `A` IS THE ONLY DOOR ON THIS MODULE THAT ADMITS A DECLARED UNION AT ALL, and that is\n// what still bounds the surface: a `Shape[]` RECEIVER is loud at both scopes, a\n// `mapIndexed` union RESULT is loud, and a union-member struct as a map value is a loud\n// emit refusal. A union MEMBER is a different door from a declared union, and it is\n// admitted. Pinned under `tests/cases/std/` by `array-reduce-litunion-accumulator.vl`,\n// `array-reduce-narrowed-variant-init.vl` and `array-reduce-member-accum-layout-twin.vl`.\nexport function reduce<T, A>(self: T[], f: (A, T) => A, init: A): A {\n  let acc = init\n  let i = 0\n  while i < self.length {\n    acc = f(acc, self[i])\n    i = i + 1\n  }\n  return acc\n}\n\n// ── The BUILDING family — each returns a NEW list, leaving its inputs unmutated. ──\n// (`sorted` is a fourth member and lives with `sort` at the bottom of the file, so the\n// ordering pair reads together.)\n\n// `self`'s elements in reverse order. NOT IN PLACE, despite the bare imperative verb\n// the header's naming rule otherwise reserves for `sort`: JS's `Array.prototype.reverse()`\n// DOES mutate, so a JS-shaped reader writing `xs.reverse()` as a STATEMENT gets a silent\n// no-op — clean at every severity, `--severity info` included. The rule going forward is\n// that a BUILDING export whose verb also names a common in-place operation takes the\n// participle instead (`sorted`); `reverse` predates it and std has no rename story.\nexport function reverse<T>(self: T[]): T[] {\n  const out: T[] = []\n  let i = self.length - 1\n  while i >= 0 {\n    out.push(self[i])\n    i = i - 1\n  }\n  return out\n}\n\n// `self` followed by `other`. The element type `T` must match (`==`-comparable not\n// required — this only moves elements), so a mixed-type concat does not type-check.\n//\n// AND FOR SOME ELEMENT TYPES THIS IS THE ONLY WORKING CONCATENATION, which is worth saying\n// because the `+` operator reads as the obvious spelling and stopped being one on 2026-08-26.\n// `F[] + F[]` over `type F = 1.5 | 2.5` is a loud `vl check` reject (`silent-class-inventory`\n// D102 — it used to write invalid wasm); `xs.concat(ys)` over the same lists RUNS and reads\n// its elements back correctly, on that day's compiler and the one before it. The reason is\n// that `+` has exactly ONE lowering (`emitListConcatI`, hard-wired to the i32 backing) while\n// this function is an ordinary `push` loop over `T`, so it inherits the element's own storage\n// instead of assuming one. The same holds for `type G = 1.5`, `type BIG = 9999999999`,\n// `(1|2)|null` and `(1.5|2.5)|null`. Measured at each, both spellings.\nexport function concat<T>(self: T[], other: T[]): T[] {\n  const out: T[] = []\n  let i = 0\n  while i < self.length {\n    out.push(self[i])\n    i = i + 1\n  }\n  let j = 0\n  while j < other.length {\n    out.push(other[j])\n    j = j + 1\n  }\n  return out\n}\n\n// `map` with the element INDEX: `f(element, i)` for each element, collected in\n// order into a new list. The result element type `U` may differ from `T`. The\n// emitter's bare `.map` passes only the element; this is the indexed companion.\n//\n// A `U` THAT IS A STRING LITERAL UNION lowers in both the inline and the declared-ALIAS\n// spelling, and the DELIVERY of the callback is its own axis — a named function, a lambda\n// literal, a binding annotated or not, a list element, a struct field, a function result,\n// and a NULLABLE function value narrowed with `is` all work. That axis is called out\n// because a \"both spellings work\" claim once missed it: an alias `U` through a binding was\n// check-clean INVALID wasm while the by-name spelling ran, with no hint to signpost it.\n// Grids: `tests/cases/std/array-mapindexed-litunion-result.vl` for `T` x `U`, and\n// `array-mapindexed-litunion-callback-delivery.vl` for delivery x spelling.\nexport function mapIndexed<T, U>(self: T[], f: (T, i32) => U): U[] {\n  const out: U[] = []\n  let i = 0\n  while i < self.length {\n    out.push(f(self[i], i))\n    i = i + 1\n  }\n  return out\n}\n\n// ── The ORDERING pair — `sort` in place, `sorted` as a copy ────────────────────\n//   sort<T>(self: T[], less: (T, T) => boolean)          // reorders self, returns nothing\n//   sorted<T>(self: T[], less: (T, T) => boolean): T[]   // leaves self alone, returns a copy\n// CONTRACT, both: ascending under `less`, STABLE, and O(n log n) comparisons in the WORST\n// case — a bottom-up merge over runs an insertion sort has already ordered. They differ\n// only in ALLOCATION, and on both sides of the base case. `less` IS A BOOLEAN STRICT\n// LESS-THAN, not a three-way `(T, T) => i32`: there is no sign convention to get backwards,\n// and it keeps the generic closure parameter the shape `reduce`/`mapIndexed` already ship.\n// It may close over anything, which makes SORTING AN INDEX LIST first-class rather than a\n// workaround. An INCONSISTENT `less` is NOT undefined behaviour — the ORDER is unspecified\n// but the result is always a PERMUTATION, because both loops are bounded by INDICES. That\n// covers what `less` ANSWERS, never a comparator that MUTATES the receiver, which can trap.\n\n// Reorder `self` IN PLACE, ascending under `less`. STABLE; O(n log n) comparisons worst\n// case; allocates nothing up to n = 16 and one n-element buffer above that. Returns\n// nothing — the receiver IS the result. See the block above for the contract `less` must\n// satisfy and for what happens when it does not.\n//\n// NOT DONE, DELIBERATELY, and each is a name a version-locked std could never take back:\n// no `sortUnstable` (a second name doing almost the same thing, and the stable one is the\n// one `cli.vl` relies on); no `sortBy`/`sortedBy` (each is `sort` with a two-line\n// comparator); no default ordering `xs.sort()`, since `<` is defined for the scalars and\n// `string` but not for a struct or a union and VL has no overloading to express that; no\n// `binarySearch`/`lowerBound`, excluded by name in `perf-workstream.md` §6.2; and no\n// adaptivity — an already-sorted input is not detected and still pays every merge pass.\nexport function sort<T>(self: T[], less: (T, T) => boolean) {\n  // SORT_RUN lives INSIDE the function rather than beside the module header because a\n  // module-level const is emitted as a wasm global whether or not anything imports the\n  // export that reads it. The delta is small, but it is charged to callers who never\n  // sort, and the run length is not a knob anyone outside this function can reach.\n  // Absolute sizes are deliberately NOT quoted — they move with every unrelated std\n  // edit, and an earlier draft of this comment quoted three that no longer reproduce.\n  const SORT_RUN = 16\n  const n = self.length\n  // A 0- or 1-element list is already sorted, and saying so by NESTING rather than with\n  // an early `return` is forced: VL's emitter rejects a bare `return` in a void function\n  // (the same shape `std:buffer.fill` uses).\n  if n >= 2 {\n    // Base case: insertion-sort each block of SORT_RUN in place. `less(key, self[j])`\n    // and not `!less(self[j], key)` is what makes this half STABLE — an element stops as\n    // soon as its left neighbour is not strictly greater, so equals never cross.\n    let lo = 0\n    while lo < n {\n      let hi = lo + SORT_RUN\n      if hi > n { hi = n }\n      let k = lo + 1\n      while k < hi {\n        const key = self[k]\n        let j = k - 1\n        while j >= lo && less(key, self[j]) {\n          self[j + 1] = self[j]\n          j = j - 1\n        }\n        self[j + 1] = key\n        k = k + 1\n      }\n      lo = lo + SORT_RUN\n    }\n    // A list that fits in one run is done. Skipping here is what makes `sort` allocate\n    // NOTHING at the lengths this tree actually sorts — the whole n-vs-2n difference\n    // between `sort` and `sorted` is n-vs-0 below n = 17.\n    if n > SORT_RUN {\n      const aux: T[] = []\n      let z = 0\n      while z < n {\n        aux.push(self[z])\n        z = z + 1\n      }\n      // Bottom-up merge, ping-ponging between `self` and `aux` so no pass copies back.\n      // `srcIsSelf` is a parity BIT and not a comparison, because `==` on two lists is\n      // not reference identity in VL and would answer a different question.\n      let src = self\n      let dst = aux\n      let srcIsSelf = true\n      let width = SORT_RUN\n      while width < n {\n        let s = 0\n        while s < n {\n          let mid = s + width\n          if mid > n { mid = n }\n          let e = mid + width\n          if e > n { e = n }\n          let p = s\n          let q = mid\n          let o = s\n          // STABLE: the right half wins only when it is STRICTLY less, so on a tie the\n          // left (earlier) element goes first.\n          while p < mid && q < e {\n            if less(src[q], src[p]) {\n              dst[o] = src[q]\n              q = q + 1\n            } else {\n              dst[o] = src[p]\n              p = p + 1\n            }\n            o = o + 1\n          }\n          // Unconditional drains — index-bounded, so a comparator that lies still yields\n          // a permutation rather than a trap.\n          while p < mid {\n            dst[o] = src[p]\n            p = p + 1\n            o = o + 1\n          }\n          while q < e {\n            dst[o] = src[q]\n            q = q + 1\n            o = o + 1\n          }\n          s = e\n        }\n        const tmp = src\n        src = dst\n        dst = tmp\n        srcIsSelf = !srcIsSelf\n        width = width + width\n      }\n      // An ODD number of merge passes leaves the answer in `aux`; copy it home. This is\n      // the one cost `sort` pays that `sorted` does not, it is n writes against the\n      // merge's n log n, and it is skipped outright whenever the pass count is even.\n      if !srcIsSelf {\n        let i = 0\n        while i < n {\n          self[i] = src[i]\n          i = i + 1\n        }\n      }\n    }\n  }\n}\n\n// `self`'s elements in ascending order under `less`, as a NEW list, leaving `self`\n// untouched. STABLE; O(n log n) comparisons worst case; allocates the returned list\n// always and one auxiliary only above n = 16 — so n below the threshold and 2n above,\n// against `sort`'s 0 and n.\n//\n// THIS BODY IS `sort`'s, COPIED, and that is a COMPILER LIMITATION rather than a choice:\n// it should read `const out = …copy…; sort(out, less); return out` and cannot, because a\n// GENERIC FUNCTION CANNOT PASS ITS OWN GENERIC-TYPED FUNCTION PARAMETER TO ANOTHER\n// GENERIC FUNCTION — the direct call, the UFCS call, a forwarding local and a re-wrapping\n// lambda were all refused. `tests/cases/std/array-sort-agrees.vl` is the differential\n// fixture that keeps the two copies honest; the only intended differences are the leading\n// copy and the tail, where `sorted` returns whichever buffer holds the answer.\nexport function sorted<T>(self: T[], less: (T, T) => boolean): T[] {\n  const SORT_RUN = 16\n  const n = self.length\n  const out: T[] = []\n  let c = 0\n  while c < n {\n    out.push(self[c])\n    c = c + 1\n  }\n  if n < 2 { return out }\n\n  let lo = 0\n  while lo < n {\n    let hi = lo + SORT_RUN\n    if hi > n { hi = n }\n    let k = lo + 1\n    while k < hi {\n      const key = out[k]\n      let j = k - 1\n      while j >= lo && less(key, out[j]) {\n        out[j + 1] = out[j]\n        j = j - 1\n      }\n      out[j + 1] = key\n      k = k + 1\n    }\n    lo = lo + SORT_RUN\n  }\n  if n <= SORT_RUN { return out }\n\n  const aux: T[] = []\n  let z = 0\n  while z < n {\n    aux.push(out[z])\n    z = z + 1\n  }\n  let src = out\n  let dst = aux\n  let width = SORT_RUN\n  while width < n {\n    let s = 0\n    while s < n {\n      let mid = s + width\n      if mid > n { mid = n }\n      let e = mid + width\n      if e > n { e = n }\n      let p = s\n      let q = mid\n      let o = s\n      while p < mid && q < e {\n        if less(src[q], src[p]) {\n          dst[o] = src[q]\n          q = q + 1\n        } else {\n          dst[o] = src[p]\n          p = p + 1\n        }\n        o = o + 1\n      }\n      while p < mid {\n        dst[o] = src[p]\n        p = p + 1\n        o = o + 1\n      }\n      while q < e {\n        dst[o] = src[q]\n        q = q + 1\n        o = o + 1\n      }\n      s = e\n    }\n    const tmp = src\n    src = dst\n    dst = tmp\n    width = width + width\n  }\n  return src\n}\n",
  "std:base64": "// `std:base64` — RFC 4648 §4 base64, the standard alphabet with padding, in\n// pure VL. Bytes in, text out, and back; `docs/serde-design.md` names it as\n// the answer for `u8[]` in every text format VL reads or writes.\n//\n// THE DIRECTIONS READ BACKWARDS FROM `std:utf8` AND THAT IS DELIBERATE:\n// `encodeUtf8` goes text → bytes, `encodeBase64` goes bytes → text; in each\n// domain \"encode\" is the direction the format's own name describes, and the\n// receiver type disambiguates. ENCODE IS TOTAL, the ruling `std:utf8` makes\n// for the same reason: every `u8[]` has a base64 encoding, so a fallible\n// signature would infect callers for input that cannot exist; `[]` → `\"\"`.\n//\n// DECODE IS STRICT. Each refusal is one `kind` on `Base64Error`:\n//   • `\"character\"` — any byte outside `A-Za-z0-9+/=`, SPACES AND NEWLINES\n//     INCLUDED: base64's familiar wrapping is MIME's (RFC 2045 §6.8), a\n//     different format, and stripping it is the caller's decision.\n//   • `\"length\"` — not a multiple of four; padding is REQUIRED, so `\"QQ\"` is\n//     refused where `\"QQ==\"` decodes. THIS GATE RUNS FIRST, so wrapped MIME\n//     reports `\"length\"` at the input's size, not `\"character\"` at the break.\n//   • `\"padding\"` — `=` anywhere but the last one or two positions.\n//   • `\"bits\"` — non-canonical trailing bits: the bits of the final character\n//     past the end of the last byte must be zero (RFC 4648 §3.5 permits the\n//     refusal). It is what makes decode-then-encode an exact identity on every\n//     accepted string, which a lenient decoder cannot offer.\n//\n// WHAT IS NOT HERE: the URL-safe alphabet (RFC 4648 §5) and unpadded decoding.\n// When one arrives it gets its OWN NAME (`encodeBase64Url`), never a boolean\n// parameter — `f(bytes, true)` is the shape `std-api-review.md` §2 names.\n//\n// THE FAILURE CHANNEL IS `u8[] | Base64Error`, not `u8[] | null`: a blob is\n// machine-produced, so an offset locates a truncated transfer or a stray\n// newline, and the four kinds call for different fixes — the \"failure with\n// information the caller needs\" case `error-handling-design.md` spends `T | E`\n// on, where `parseF64` answers `f64 | null` because a float literal has one\n// way to be wrong. `kind` is a LITERAL UNION, not an i32 code, so `match` sees\n// the arms (`std-api-review.md` §3), and it keeps the type DISTINCT: VL\n// aliases are structural, so bare `{ at: i32, msg: string }` hits `ParseError`.\n//\n// `u8[]` IS OUTSIDE THE GENERIC SURFACE — not a `T[]`, so no `map`/`indexOf`/\n// `sorted`; the loops below are written out for that. `encodeBase64` fills ONE\n// code-point buffer and calls `fromCodePoints` once — `out = out + c` is O(n²).\n\n// Why a decode stopped, where, and in which of the four ways. `at` is a BYTE\n// offset into the string that was handed in — the same coordinate system\n// `slice` and `indexOf` use — and points at the offending character, except\n// for `\"length\"`, where the fault is the input's size and `at` is that size.\n//\n// `kind` DETERMINES THE BRANCH, `msg` DOES NOT: several `msg` strings share one\n// `kind` (three of them are `\"padding\"`, which distinguishes `=` in the wrong\n// position from `=` before the last group from `=` that does not run to the\n// end). Branch on `kind`; treat `msg` as prose for a human, the same split\n// `Utf8Error` and `IoError` make.\nexport type Base64Error = {\n  at: i32,\n  kind: \"character\" | \"length\" | \"padding\" | \"bits\",\n  msg: string,\n}\n\n// The RFC 4648 §4 alphabet, index → character. A ladder rather than a string\n// index because it inverts exactly, character → index, in `b64Val` below, and\n// two tables that must agree is one more thing to get wrong.\nfunction b64Char(v: i32): i32 {\n  if v < 26 { return 65 + v }\n  if v < 52 { return 97 + (v - 26) }\n  if v < 62 { return 48 + (v - 52) }\n  if v == 62 { return 43 }\n  47\n}\n\n// The alphabet's inverse: a character's 6-bit value, or -1 for anything that\n// is not in it. `=` is NOT accepted here — padding is positional and the\n// decoder handles it, so letting it through as a value would make `\"A=AA\"`\n// decode.\nfunction b64Val(c: i32): i32 {\n  if c >= 65 && c <= 90 { return c - 65 }\n  if c >= 97 && c <= 122 { return c - 97 + 26 }\n  if c >= 48 && c <= 57 { return c - 48 + 52 }\n  if c == 43 { return 62 }\n  if c == 47 { return 63 }\n  -1\n}\n\nfunction b64Err(\n  at: i32,\n  kind: \"character\" | \"length\" | \"padding\" | \"bits\",\n  msg: string,\n): Base64Error {\n  { at: at, kind: kind, msg: msg }\n}\n\n// `self` as base64 text: RFC 4648 §4, standard alphabet, always padded to a\n// multiple of four characters. Total — every byte sequence has an encoding.\nexport function encodeBase64(self: u8[]): string {\n  const out: i32[] = []\n  const n = self.length\n  let i = 0\n  while i + 3 <= n {\n    const a = self[i]\n    const b = self[i + 1]\n    const c = self[i + 2]\n    out.push(b64Char(a >> 2))\n    out.push(b64Char(((a & 3) << 4) | (b >> 4)))\n    out.push(b64Char(((b & 15) << 2) | (c >> 6)))\n    out.push(b64Char(c & 63))\n    i = i + 3\n  }\n  const rest = n - i\n  if rest == 1 {\n    const a = self[i]\n    out.push(b64Char(a >> 2))\n    out.push(b64Char((a & 3) << 4))\n    out.push(61)\n    out.push(61)\n  }\n  if rest == 2 {\n    const a = self[i]\n    const b = self[i + 1]\n    out.push(b64Char(a >> 2))\n    out.push(b64Char(((a & 3) << 4) | (b >> 4)))\n    out.push(b64Char((b & 15) << 2))\n    out.push(61)\n  }\n  fromCodePoints(out)\n}\n\n// The bytes `self` encodes, or the reason it is not canonical padded base64 —\n// see the module header for the exact refusals. `\"\"` decodes to the empty byte\n// list; it is not an error.\n//\n// Indexing a `string` yields a BYTE, so a multi-byte character arrives as\n// bytes >= 0x80, none of which is in the alphabet: non-ASCII input is refused\n// by the same test that refuses a space, with no separate check.\nexport function decodeBase64(self: string): u8[] | Base64Error {\n  const out: u8[] = []\n  const n = self.length\n  if n == 0 { return out }\n  if n % 4 != 0 {\n    return b64Err(n, \"length\", \"base64 length is not a multiple of 4\")\n  }\n  let i = 0\n  while i < n {\n    const last = i + 4 == n\n    const t0 = self[i]\n    const t1 = self[i + 1]\n    const t2 = self[i + 2]\n    const t3 = self[i + 3]\n    // `=` in either of the first two positions of a group is always wrong: a\n    // group encodes at least one byte, which needs two characters.\n    if t0 == 61 { return b64Err(i, \"padding\", \"misplaced '=' padding\") }\n    if t1 == 61 { return b64Err(i + 1, \"padding\", \"misplaced '=' padding\") }\n    const c0 = b64Val(t0)\n    if c0 < 0 { return b64Err(i, \"character\", \"not a base64 character\") }\n    const c1 = b64Val(t1)\n    if c1 < 0 { return b64Err(i + 1, \"character\", \"not a base64 character\") }\n    if t2 == 61 {\n      if !last { return b64Err(i + 2, \"padding\", \"'=' before the last group\") }\n      if t3 != 61 { return b64Err(i + 3, \"padding\", \"'=' must pad to the end\") }\n      // The low four bits of the second character lie past the one byte this\n      // group carries; a canonical encoder leaves them zero.\n      if (c1 & 15) != 0 {\n        return b64Err(i + 1, \"bits\", \"non-zero bits past the encoded byte\")\n      }\n      out.push((c0 << 2) | (c1 >> 4))\n      return out\n    }\n    const c2 = b64Val(t2)\n    if c2 < 0 { return b64Err(i + 2, \"character\", \"not a base64 character\") }\n    if t3 == 61 {\n      if !last { return b64Err(i + 3, \"padding\", \"'=' before the last group\") }\n      // Likewise the low two bits of the third character.\n      if (c2 & 3) != 0 {\n        return b64Err(i + 2, \"bits\", \"non-zero bits past the encoded byte\")\n      }\n      out.push((c0 << 2) | (c1 >> 4))\n      out.push(((c1 & 15) << 4) | (c2 >> 2))\n      return out\n    }\n    const c3 = b64Val(t3)\n    if c3 < 0 { return b64Err(i + 3, \"character\", \"not a base64 character\") }\n    out.push((c0 << 2) | (c1 >> 4))\n    out.push(((c1 & 15) << 4) | (c2 >> 2))\n    out.push(((c2 & 3) << 6) | c3)\n    i = i + 4\n  }\n  out\n}\n",
  "std:buffer": "// `std:buffer` — the linear-memory tier's allocator and access surface, in pure VL over the\n// `__load_*__` / `__store_*__` / `__memory_*__` intrinsic floor\n// (`docs/internals/buffer-design.md` §C, sequencing item S5). The compiler owns exactly what\n// an INSTRUCTION is; allocation POLICY is ordinary code and lives here (O1 = (c): `Buffer` is\n// std VL, not a compiler-known type).\n//\n// TWO HEAPS. A `Buf` VALUE is an ordinary WasmGC struct with ordinary VL value semantics; a\n// `Buf`'s CONTENTS live in linear memory, which the host can read directly through the\n// module's exported `memory`. `.length` is a plain field read — no call, no side table.\n//\n// BOUNDS: there are none here, by design (§A4). An access past the end of the memory traps in\n// the ENGINE — that trap is the memory-safety proof, and adding a VL-level check would only\n// make it quieter. An access past the end of a `Buf` but still inside the memory is NOT\n// caught: `Buf` describes an extent, it does not fence it. (The typed VIEWS further down are\n// the one exception, and that section says why.)\n//\n// HOST CONTRACT (O5 = lazy growth, no epoch export). `Buffer(n)` grows the memory when it\n// must, and a `memory.grow` DETACHES every host view of `exports.memory.buffer`. A host must\n// therefore re-take its typed-array views after any guest call that may allocate; a stale view\n// is detectable by `view.byteLength === 0` (a detached view yields `undefined` on an indexed\n// read rather than throwing). This is what Emscripten's `updateMemoryViews()`, wasm-bindgen's\n// `byteLength === 0` probe and Go's `wasm_exec.js` buffer-identity check all do; none of them\n// exports a growth counter, and neither does this module.\n//\n// RECLAMATION IS MARK/RELEASE, AND IT CAN DANGLE (O6). There is no per-object `free`;\n// `bufferMark()` / `bufferRelease(mark)` move the one bump pointer, so reclamation is LIFO and\n// costs nothing. The hazard is stated here rather than in a footnote because it is the FIRST\n// way a VL program can hold a dangling reference at all: a `Buf` held across a `bufferRelease`\n// that undoes its allocation still points at live, in-bounds, since-reused linear memory.\n// Reads through it return another buffer's bytes and writes through it corrupt them —\n// SILENTLY. No trap fires, because nothing is out of bounds. Treat a released mark as\n// invalidating every `Buf` allocated after it.\n//\n// PERFORMANCE. Every access below is a real wasm `call`, and every body is ONE instruction\n// plus its address arithmetic. `wasm-opt -O` (what `vl build -O` runs) does NOT inline these\n// wrappers; `-O3 --closed-world` does (§O1).\n\n// A `Buf` is a linear-memory extent: the byte address of its first byte, and\n// the number of bytes the caller ASKED for (the allocator may reserve a few\n// more for alignment; those are invisible here).\nexport type Buf = { base: i32, length: i32 }\n\n// A wasm page is 64 KiB; `__memory_size__` / `__memory_grow__` count pages.\nconst PAGE_SHIFT = 16\nconst PAGE_MASK = 65535\n\n// POLICY 1 — the reserved low region. Byte addresses below `HEAP_BASE` are\n// never handed out. Three reasons, none of them cosmetic:\n//   - address 0 stays outside every allocation, so `base == 0` cannot be a\n//     legitimate `Buf` and a zeroed/garbage descriptor is distinguishable;\n//   - a program may still poke raw addresses through the bare intrinsics\n//     (that is the §A3 \"two users collide\" hazard), and this leaves it a\n//     documented kilobyte that `std:buffer` promises never to touch;\n//   - the host's staging ABI probe (`ioMem`, `scripts/vl-host/src/main.rs`)\n//     wants a fixed low window it can own later without moving the heap.\n// 1 KiB, not one page: reserving a whole page would force a `memory.grow`\n// during init for programs that fit comfortably in the default one.\nconst HEAP_BASE = 1024\n\n// POLICY 2 — alignment. Every allocation's SIZE is rounded up to `ALIGN` and `HEAP_BASE` is a\n// multiple of it, so every `Buf` starts aligned and each width's natural alignment is\n// satisfied at offset 0 and at every multiple of `ALIGN`. This is a PERFORMANCE choice, not a\n// correctness one — wasm's alignment immediate is a hint and every load/store here is legal at\n// any address (pinned by the unaligned cases in `tests/cases/memory/`). The value is the\n// widest scalar VL can store (i64 / f64).\nconst ALIGN = 8\n\n// The bump pointer: the address one past the last byte handed out. Module-level\n// mutable state, which is exactly what makes the allocator's policy ordinary\n// VL code (§C4).\nlet bumpPtr = HEAP_BASE\n\n// `n` rounded up to the next multiple of `ALIGN`.\nfunction alignUp(n: i32): i32 {\n  const slack = n & (ALIGN - 1)\n  if slack == 0 { return n }\n  return n + (ALIGN - slack)\n}\n\n// Grow the memory until byte `end` (exclusive) is addressable. Page arithmetic\n// throughout — computing `pages * 65536` would itself overflow i32 at 2 GiB,\n// which is inside the range this can be asked about.\nfunction ensureCapacity(end: i32) {\n  let needPages = end >> PAGE_SHIFT\n  if (end & PAGE_MASK) != 0 { needPages = needPages + 1 }\n  const havePages = __memory_size__()\n  if needPages > havePages {\n    // `memory.grow` answers with the size BEFORE the growth, or -1 on failure.\n    // A refused allocation cannot be papered over — the caller is about to write\n    // through a `Buf` that has no memory behind it.\n    //\n    // MEASURED, this branch is defensive rather than routine: `Buffer`'s i32\n    // overflow guard caps `end` at 2^31, i.e. at most 32768 pages, and wasm32's\n    // own ceiling is 65536 — so the SPEC limit is unreachable from here and only\n    // host resource exhaustion can produce the -1. Both hosts grow a 2 GiB\n    // request without complaint (wasmtime 47 and V8 alike, measured), which is\n    // why no corpus fixture pins this line: there is no request that fails\n    // deterministically on every host.\n    if __memory_grow__(needPages - havePages) < 0 { __trap__() }\n  }\n}\n\n// `Buffer(n)` — reserve `n` zero-filled bytes and describe them.\n//\n// ZERO-FILL: a wasm memory starts zeroed and freshly grown pages are zeroed, so\n// bytes that have never been handed out before are zero for free — no fill loop\n// runs here. That guarantee ends at the first `bufferRelease`: addresses handed\n// out a SECOND time carry whatever the previous owner wrote. Call\n// `buf.fill(0, buf.length, 0)` when reusing a released region and zeros matter.\n//\n// Traps on a negative length and on an allocation that would carry the bump\n// pointer past 2 GiB (where an i32 byte address stops being orderable), because\n// either would silently corrupt every later allocation.\nexport function Buffer(byteLength: i32): Buf {\n  if byteLength < 0 { __trap__() }\n  const base = bumpPtr\n  const next = base + alignUp(byteLength)\n  if next < base { __trap__() }\n  ensureCapacity(next)\n  bumpPtr = next\n  return { base: base, length: byteLength }\n}\n\n// `bufferMark()` — the current bump pointer, to hand back to `bufferRelease`.\nexport function bufferMark(): i32 { return bumpPtr }\n\n// `bufferRelease(mark)` — reclaim everything allocated since `mark` in one\n// move. LIFO, no free list, no fragmentation, and NO liveness check: see this\n// module's header for the dangling-`Buf` hazard this opens, which is silent\n// corruption rather than a trap.\n//\n// Traps on a mark outside `[HEAP_BASE, bumpPtr]` — below the base it would let\n// allocations walk into the reserved region, above the pointer it re-reserves\n// bytes that are already free. Both are bugs at the call site, not recoverable\n// states.\nexport function bufferRelease(mark: i32) {\n  if mark < HEAP_BASE { __trap__() }\n  if mark > bumpPtr { __trap__() }\n  bumpPtr = mark\n}\n\n// ── Loads: eight widths, four of them signed/unsigned pairs. ──\n//\n// The signed/unsigned split is REAL here and is kept: `i32.load8_s` and\n// `i32.load8_u` are two different instructions, and of the byte 0xFF the first\n// answers -1 while the second answers 255. (The stores below have no such\n// split — see `store8`.)\n\n// The byte at `off`, sign-extended into an i32 (0xFF → -1).\nexport function loadI8(self: Buf, off: i32): i32 {\n  return __load_i8__(self.base + off)\n}\n\n// The byte at `off`, zero-extended into an i32 (0xFF → 255).\nexport function loadU8(self: Buf, off: i32): i32 {\n  return __load_u8__(self.base + off)\n}\n\n// The 16-bit halfword at `off`, sign-extended (0xFFFF → -1).\nexport function loadI16(self: Buf, off: i32): i32 {\n  return __load_i16__(self.base + off)\n}\n\n// The 16-bit halfword at `off`, zero-extended (0xFFFF → 65535).\nexport function loadU16(self: Buf, off: i32): i32 {\n  return __load_u16__(self.base + off)\n}\n\n// The 32-bit word at `off`.\nexport function loadI32(self: Buf, off: i32): i32 {\n  return __load_i32__(self.base + off)\n}\n\n// The 64-bit word at `off`.\nexport function loadI64(self: Buf, off: i32): i64 {\n  return __load_i64__(self.base + off)\n}\n\n// The 32-bit float at `off`.\nexport function loadF32(self: Buf, off: i32): f32 {\n  return __load_f32__(self.base + off)\n}\n\n// The 64-bit float at `off`.\nexport function loadF64(self: Buf, off: i32): f64 {\n  return __load_f64__(self.base + off)\n}\n\n// ── Stores: six widths, and no signed/unsigned split (O2). ──\n//\n// A store is sign-AGNOSTIC. There is exactly one instruction per width and it\n// TRUNCATES — `i32.store8` cannot tell a signed byte from an unsigned one — so\n// naming these `storeU8`/`storeI8` would falsely imply a signed twin exists.\n// Hence `store8` / `store16` against the loads' `loadI8` / `loadU8`: the\n// asymmetry is the instruction set's, and it is deliberate.\n\n// The 32-bit word at `off`.\nexport function storeI32(self: Buf, off: i32, v: i32) {\n  __store_i32__(self.base + off, v)\n}\n\n// The 64-bit word at `off`.\nexport function storeI64(self: Buf, off: i32, v: i64) {\n  __store_i64__(self.base + off, v)\n}\n\n// The 32-bit float at `off`.\nexport function storeF32(self: Buf, off: i32, v: f32) {\n  __store_f32__(self.base + off, v)\n}\n\n// The 64-bit float at `off`.\nexport function storeF64(self: Buf, off: i32, v: f64) {\n  __store_f64__(self.base + off, v)\n}\n\n// The low 8 bits of `v` at `off`. Higher bits are discarded, exactly as `i32.store8` discards\n// them — because this IS `i32.store8` (0x3a).\n//\n// It must stay ONE instruction rather than a read-modify-write over the containing word: a\n// wider access is unobservable from VL (no threads, no shared memory) but NOT from the host,\n// and `tests/vl_exported_memory_test.ts` reads the untouched neighbours through the exported\n// memory.\nexport function store8(self: Buf, off: i32, v: i32) {\n  __store_i8__(self.base + off, v)\n}\n\n// The low 16 bits of `v` at `off`, little-endian — `i32.store16` (0x3b).\n//\n// This was two byte-wide read-modify-writes rather than one word-level one,\n// because a halfword at an address congruent to 3 mod 4 STRADDLES two words. The\n// instruction has no such difficulty: wasm's alignment immediate is a hint, and\n// a 16-bit store is legal and correct at every address, straddle included.\nexport function store16(self: Buf, off: i32, v: i32) {\n  __store_i16__(self.base + off, v)\n}\n\n// ── Bulk ops: one instruction each. ──\n//\n// THE ONE PLACE THIS MODULE DOES NOT PASS ITS ARGUMENT STRAIGHT THROUGH. Both instructions\n// take an UNSIGNED byte count and VL has no unsigned i32, so a negative `len` is ~4 GiB and\n// traps in the engine. The byte loops these bodies replaced treated a non-positive `len` as\n// \"write nothing\", and that behaviour is pinned (`tests/cases/std/buffer-bulk.vl`), so the\n// guard stays — which is the right layering anyway: the intrinsic IS the instruction\n// (`__memory_fill__` traps on -5, per `tests/cases/memory/bulk-negative-length-traps.vl`),\n// and softening it is POLICY, which is std's job (O1 = (c)).\n//\n// Nothing else is guarded. There is still no per-access bounds check, exactly as for every\n// load and store above: `Buf` describes an extent, it does not fence it.\n\n// Set `len` bytes starting at `off` to the low 8 bits of `byte` — `memory.fill`\n// (0xfc 11). A non-positive `len` writes nothing.\n// (Spelled as a positive `if` rather than an early `return`: a BARE `return` in a\n// void function type-checks and then fails at emit — `emitProgram: bare return is\n// not supported`. Worth knowing before reaching for a guard clause here.)\nexport function fill(self: Buf, off: i32, len: i32, byte: i32) {\n  if len > 0 { __memory_fill__(self.base + off, byte, len) }\n}\n\n// Copy `len` bytes from `src` at `srcOff` into `self` at `dstOff` — the DESTINATION is the\n// receiver (O3), matching `dst.fill(...)` and the self-first UFCS shape `std:array` /\n// `std:fmt` already establish. (`Buffer.copy` is not spellable: VL has no static methods.)\n//\n// OVERLAP IS HANDLED, by the INSTRUCTION. `memory.copy` (0xfc 10) is defined to behave as if\n// the bytes went through a temporary — memmove semantics, not memcpy — so an overlapping copy\n// never reads a byte it has already overwritten, in either direction. `self` and `src` may be\n// the same `Buf`, and may overlap partially either way. The direction-choosing loop this\n// replaced is gone rather than merely optimized, and both directions stay pinned by value in\n// `tests/cases/std/buffer-bulk.vl`.\nexport function copyFrom(\n  self: Buf,\n  dstOff: i32,\n  src: Buf,\n  srcOff: i32,\n  len: i32,\n) {\n  if len > 0 { __memory_copy__(self.base + dstOff, src.base + srcOff, len) }\n}\n\n// ── Typed views (webcraft P1.1) ──────────────────────────────────────────────\n//\n// A VIEW re-describes a `Buf` sub-range in ELEMENTS rather than bytes: a byte address, an\n// element COUNT (`.length`, a plain struct field), and the element WIDTH IN THE TYPE, so a\n// further width is one more `new` rather than one more name hack. That `new` is load-bearing\n// (`docs/internals/newtype-design.md`): VL is STRUCTURALLY typed, so spelled plainly the two\n// views would be ONE type, and `iv.getF32(0)` would silently reinterpret integer bytes as a\n// float. Erasure makes the brand free; `docs/internals/buffer-design.md` §M has the rulings.\n//\n// BOUNDS ARE CHECKED HERE — the one place in `std:buffer` that checks, because an out-of-range\n// ELEMENT index usually stays inside the memory, so §A4's engine trap never fires and the read\n// returns a NEIGHBOUR'S BYTES. Each accessor traps on an index outside `[0, length)`.\n\n// The largest element count whose byte size fits in a positive i32, per width.\n// `count << 2` at 2^29 is already negative, so the count must be rejected BEFORE\n// the shift rather than after it.\nconst MAX_COUNT_4 = 536870911\n\n// A view of 4-byte floats. `base` is the byte address of element 0; `length` is\n// the element count. `new` is what keeps this distinct from `I32View`, which has\n// the identical shape — see this section's header.\nexport type F32View = new { base: i32, length: i32 }\n\n// A view of 4-byte signed integers.\nexport type I32View = new { base: i32, length: i32 }\n\n// THE BASE ADDRESS OF A VIEW, BRANDED BY WIDTH — the handle the `*At` accessors below take,\n// minted by `f32base` / `i32base`.\n//\n// Same reason `F32View` and `I32View` are `new`: the two are structurally identical (both an\n// address) and nothing but a nominal brand tells them apart. Unbranded,\n// `getF32At(iv.byteAddrI32(0), iv.length, 0)` would type-check and reinterpret integer bytes\n// as a float, silently — the same hazard the view section's header spends its `new` on.\n//\n// IT IS A SEPARATE MINTER, NOT `byteAddrF32`'s RETURN TYPE. Branding that one was tried and is\n// wrong: it exists for raw address ARITHMETIC, and a brand makes `a + (i << 2)` a type error\n// (`operator '+' mixes F32Base and i32`) at every use in this tree. A raw accessor answers a\n// raw address; the brand belongs on the handle whose only purpose is a fenced accessor call.\nexport type F32Base = new i32\n\n// The i32 twin. Distinct from `F32Base` only nominally — that is the whole job.\nexport type I32Base = new i32\n\n// Shared construction check for a 4-byte-element view over `self`: `off` is a\n// BYTE offset into the `Buf` and `count` is an ELEMENT count. Traps unless the\n// whole range `[off, off + count*4)` lies inside the `Buf`.\n//\n// This is the ALLOCATION-TIME check §J3 puts in std's hands, taken once per view\n// rather than once per access. It is what makes the per-access check able to be\n// just `0 <= i < length`: if the extent was validated when the view was made,\n// an in-range index cannot leave the `Buf`.\n//\n// A view may be EMPTY (`count == 0`), which is in-range for every offset up to\n// `length` and satisfies no index at all — the natural base case for a loop over\n// a column that happens to have no rows.\nfunction view4Base(self: Buf, off: i32, count: i32): i32 {\n  if off < 0 { __trap__() }\n  if count < 0 { __trap__() }\n  if count > MAX_COUNT_4 { __trap__() }\n  const bytes = count << 2\n  const end = off + bytes\n  if end < off { __trap__() }\n  if end > self.length { __trap__() }\n  return self.base + off\n}\n\n// `buf.f32view(off, count)` — `count` f32 elements starting at byte `off`.\nexport function f32view(self: Buf, off: i32, count: i32): F32View {\n  const b = view4Base(self, off, count)\n  return { base: b, length: count }\n}\n\n// `buf.i32view(off, count)` — `count` i32 elements starting at byte `off`.\nexport function i32view(self: Buf, off: i32, count: i32): I32View {\n  const b = view4Base(self, off, count)\n  return { base: b, length: count }\n}\n\n// Element `i` of an f32 view. Traps on an index outside `[0, length)`.\nexport function getF32(self: F32View, i: i32): f32 {\n  if i < 0 { __trap__() }\n  if i >= self.length { __trap__() }\n  return __load_f32__(self.base + (i << 2))\n}\n\n// Write element `i` of an f32 view. Traps on an index outside `[0, length)`.\nexport function setF32(self: F32View, i: i32, v: f32) {\n  if i < 0 { __trap__() }\n  if i >= self.length { __trap__() }\n  __store_f32__(self.base + (i << 2), v)\n}\n\n// Element `i` of an i32 view. Traps on an index outside `[0, length)`.\nexport function getI32(self: I32View, i: i32): i32 {\n  if i < 0 { __trap__() }\n  if i >= self.length { __trap__() }\n  return __load_i32__(self.base + (i << 2))\n}\n\n// Write element `i` of an i32 view. Traps on an index outside `[0, length)`.\nexport function setI32(self: I32View, i: i32, v: i32) {\n  if i < 0 { __trap__() }\n  if i >= self.length { __trap__() }\n  __store_i32__(self.base + (i << 2), v)\n}\n\n// ── the bracket (webcraft P1.1's spelling) ───────────────────────────────────\n// `x[i]` / `x[i] = v` over a view, as free INDEX-OPERATOR functions (B14). Each is a one-line\n// forward to the accessor above: same bounds check, same single load/store, so the bracket is\n// SPELLING, not a second access path, and the two spellings mix freely in one loop.\n//\n// THE FORWARD IS A REAL FRAME AT THE UNOPTIMIZED RUNG — `x[i]` emits a call to this function,\n// which then calls `getF32`, where `x.getF32(i)` emits one call. Both `-O` and `-O3` inline\n// the forward away and the two spellings converge, so it is a `vl build`-with-no-flags effect\n// only; `docs/internals/buffer-design.md` §M2 has the number.\n//\n// Two `\"[]\"` declarations coexist because an index operator dispatches on its `self`\n// parameter's TYPE, and the two views are distinct nominal brands.\n\nexport function \"[]\"(self: F32View, i: i32): f32 { return getF32(self, i) }\n\nexport function \"[]=\"(self: F32View, i: i32, v: f32) { setF32(self, i, v) }\n\nexport function \"[]\"(self: I32View, i: i32): i32 { return getI32(self, i) }\n\nexport function \"[]=\"(self: I32View, i: i32, v: i32) { setI32(self, i, v) }\n\n// The byte offset of element `i` RELATIVE TO the `Buf` the view was cut from is\n// not recoverable from the view alone (a view knows an absolute address, not its\n// parent). These two return the ABSOLUTE byte address of element `i`, which is\n// what a caller mixing view access with the bare intrinsics or with a host-side\n// typed array needs. No bounds check: this computes an address, it does not\n// dereference one, and `byteAddrF32(v, v.length)` — the one-past-the-end address\n// — is the useful answer for a range, not an error.\nexport function byteAddrF32(self: F32View, i: i32): i32 {\n  return self.base + (i << 2)\n}\n\nexport function byteAddrI32(self: I32View, i: i32): i32 {\n  return self.base + (i << 2)\n}\n\n// ── hoisted accessors: the same fence, without the per-access descriptor read ─\n//\n// The view accessors take the VIEW, so each access re-reads that struct's `base` and `length`,\n// and nothing hoists those reads out of a loop; the compiler-side repairs were measured and\n// REFUTED, so this is a library answer (`docs/internals/buffer-design.md` §M8). These four\n// take base and length as SCALARS — the caller hoists them once, the loop body holds no\n// reference, and the traps, loads and stores are identical. TWO THINGS ARE GIVEN UP, which is\n// why `v[i]` stays the default and these are an opt-in: the pair can be MISMATCHED across two\n// same-width columns (take both from one view, on adjacent lines), and `view4Base`'s\n// construction-time extent check does NOT transfer, so these fence against a CLAIMED extent —\n// a base from `f32base` carries the guarantee, one you computed does not.\n\n// SELF-FIRST IS NOMINAL HERE, and that is the one place this module leaves the convention:\n// `base` leads to match `setF32(self, i, v)`, but the convention's PURPOSE is out of reach —\n// an `F32Base` is an i32 newtype, an i32 is not a UFCS receiver, and `pb.getF32At(n, i)` is\n// `member access '.getF32At' on non-object F32Base`. Kept in the leading slot for uniformity\n// with the tier these mirror, the same call `bufferMark()` / `bufferRelease(mark)` makes. The\n// medial width in `getF32At` is deliberate: the VERB carries the unit, `At` says the caller\n// supplies the index.\n\n// `f32base(v)` — the branded base of an f32 view, for the accessors below. This is\n// the ONLY public way to mint an `F32Base`, which is what makes the brand carry\n// PROVENANCE as well as width: a base that came from here was validated by\n// `view4Base` when the view was constructed.\nexport function f32base(self: F32View): F32Base { return self.base as F32Base }\n\n// `i32base(v)` — the i32 twin.\nexport function i32base(self: I32View): I32Base { return self.base as I32Base }\n\n// Element `i` of the f32 extent `[base, base + length*4)`. Traps on an index\n// outside `[0, length)`. `base` comes from `f32base(v)`.\nexport function getF32At(base: F32Base, length: i32, i: i32): f32 {\n  if i < 0 { __trap__() }\n  if i >= length { __trap__() }\n  return __load_f32__((base as! i32) + (i << 2))\n}\n\n// Write element `i` of the f32 extent `[base, base + length*4)`. Traps on an\n// index outside `[0, length)`.\nexport function setF32At(base: F32Base, length: i32, i: i32, v: f32) {\n  if i < 0 { __trap__() }\n  if i >= length { __trap__() }\n  __store_f32__((base as! i32) + (i << 2), v)\n}\n\n// Element `i` of the i32 extent `[base, base + length*4)`. Traps on an index\n// outside `[0, length)`. `base` comes from `i32base(v)`.\nexport function getI32At(base: I32Base, length: i32, i: i32): i32 {\n  if i < 0 { __trap__() }\n  if i >= length { __trap__() }\n  return __load_i32__((base as! i32) + (i << 2))\n}\n\n// Write element `i` of the i32 extent `[base, base + length*4)`. Traps on an\n// index outside `[0, length)`.\nexport function setI32At(base: I32Base, length: i32, i: i32, v: i32) {\n  if i < 0 { __trap__() }\n  if i >= length { __trap__() }\n  __store_i32__((base as! i32) + (i << 2), v)\n}\n",
  "std:fmt": "// `std:fmt` — pure-VL number formatting AND number parsing over the intrinsic\n// floor (docs/internals/std-design.md D4 item 1). The exported helpers take a\n// `self` first parameter, so they read as UFCS methods on the receiver\n// (`n.toString()`, `\"1.5\".parseF64()`, `parts.join(sep)`).\n//\n// `toString` IS THIS MODULE'S EXPORT, NOT AN AMBIENT BUILTIN: the compiler once\n// carried a builtin of that name over `i32 | boolean`, and the owner retired it\n// so this export could take it (DECISIONS.md). No capability was lost — this\n// domain is a strict superset — and it bought the UFCS spelling, since builtins\n// are not `self`-first. THE ONE BREAK, shipped deliberately: `toString(42)` needs\n// `import { toString } from \"std:fmt\"` now, and because std has no deprecation\n// story the compiler pays for it with `typecheck.stdFmtMovedNote`, which appends\n// the import line to both refusals, for `toString` and the old `toStr` alike.\n//\n// THE NAME IS BORROWED AND THE DOMAIN IS NOT. Elsewhere `toString` is defined on\n// every value; here it is exactly `i32 | i64 | boolean | f64`, so `\"abc\".toString()`\n// and `p.toString()` on a struct are refusals. A string identity arm is\n// deliberately absent: an arm that does nothing invites the name to grow into the\n// universal renderer VL has no overloading or traits to deliver (the derived\n// `show<T>` is that future, serde stage 2). The namespace being flat, a file that\n// declares its own `toString` cannot also import this one — `as` is the escape.\n//\n// WHAT IS NOT HERE: `f32`, in either direction — its shortest rendering is\n// shorter than its widened f64's, so it is Burger–Dybvig at 24-bit boundaries and\n// never a wrapper (`docs/serde-design.md` stage 0 owns it); any RADIX but ten;\n// and no unsigned, boolean or prefix parser. An `f32` widens losslessly INTO the\n// f64 arm, so `x.toString()` over one now passes the checker and floors at emit —\n// a COMPILER hole older than this module, pinned by\n// `scripts/capability-probes/f32-into-f64-union-arm.vl`.\n//\n// THE STRING SURFACE LIVES IN `std:str`; the names below are a re-export plus one\n// delegating call, and `padLeft` is the only one that did not move verbatim\n// (`std:str` spells it `padStart`). The move was not tidiness: VL has no\n// namespace import, so two modules each carrying a `split` would let a file\n// import `toString` and `split`, or `trim` and `split`, but never all three — and\n// whichever the caller reached for would silently decide whether their `join` was\n// O(n) or O(n²). It costs bytes, because there is no cross-module dead-code\n// elimination — but quote the OPTIMIZATION RUNG and what the program reaches: at\n// `-O3` an unused parser costs nothing measurable, and a constant-foldable probe\n// prices the FOLD, not the renderer.\n\nimport { padStart } from \"std:str\"\n\n// The string surface, re-exported from its owner. A re-export records a NAME,\n// so these are the SAME functions `std:str` exports and not second copies —\n// importing `split` from either module reaches one implementation. (The same\n// mechanism `std:args` uses to republish `Utf8Error`.)\nexport { join, repeat, split } from \"std:str\"\n\n// Decimal digit d in 0..=9 as its character. Takes i64 so both integer\n// widths share one renderer (i64 cannot narrow to i32, so a string-index\n// lookup is not expressible for the wide path).\nfunction digitChar(d: i64) {\n  if d == 0 { return \"0\" }\n  if d == 1 { return \"1\" }\n  if d == 2 { return \"2\" }\n  if d == 3 { return \"3\" }\n  if d == 4 { return \"4\" }\n  if d == 5 { return \"5\" }\n  if d == 6 { return \"6\" }\n  if d == 7 { return \"7\" }\n  if d == 8 { return \"8\" }\n  \"9\"\n}\n\n// Decimal rendering of any i64, including i64 min. The accumulator works in\n// the NEGATIVE range (positive inputs are negated first) because the negative\n// range covers i64 min, whose magnitude overflows when negated; `%` on a\n// negative operand yields a digit in -9..=0, negated back per digit.\nfunction renderI64(n: i64) {\n  if n == 0 { return \"0\" }\n  const zero: i64 = 0\n  let m = n\n  if m > 0 { m = zero - m }\n  let out = \"\"\n  while m < 0 {\n    out = digitChar(zero - (m % 10)) + out\n    m = m / 10\n  }\n  if n < 0 { out = \"-\" + out }\n  out\n}\n\n// Decimal rendering of a number via its receiver: `n.toString()` over an i32, an\n// i64 or an f64 binding. One union receiver covers every width (UFCS resolves\n// by `self`+arity; the value boxes in, `is`-narrows out); i32 widens\n// losslessly into the shared i64 renderer. The boolean arm renders true/false.\n//\n// The f64 arm is the whole `f64 ↔ TEXT` section below, and it is a SEPARATE\n// arm of this same union rather than a separate exported name because a flat\n// namespace has room for exactly one `toString` and a reader who has learned\n// `n.toString()` should not have to learn a second spelling to render a float.\n// Measured, so it is not an assumption: a four-arm receiver `is`-narrows and\n// monomorphizes per arm on this compiler — `f64bits` inside the `is f64`\n// branch reads the narrowed f64, no boxing artefact survives.\nexport function toString(self: i32 | i64 | boolean | f64) {\n  if self is boolean {\n    if self { return \"true\" }\n    return \"false\"\n  }\n  if self is i32 {\n    const wide: i64 = self\n    return renderI64(wide)\n  }\n  if self is f64 { return renderF64(self) }\n  return renderI64(self)\n}\n\n// `padLeft` is this module's historical spelling of `std:str`'s `padStart` and\n// is kept for its existing importers. Pads `self` on the left with `fill` up to\n// `width`: a multi-character fill is tiled and truncated so the result is\n// exactly `width` long, and `self` comes back unchanged when it is already wide\n// enough or when `fill` is empty. New code should reach for `padStart` (and its\n// `padEnd` twin, which has no name here).\nexport function padLeft(self: string, width: i32, fill: string) {\n  return padStart(self, width, fill)\n}\n\n// ── TEXT → INTEGER ──────────────────────────────────────────────────────────\n// `parseI64`/`parseI32` are the EXACT inverses of `toString` over the two integer\n// widths; the `parseF64` funnel cannot be wherever the integer is not a double.\n// THE GRAMMAR IS `\"-\"? digit+` and nothing else — a strict SUBSET of `parseF64`'s,\n// so choosing between them is a choice of TYPE and never of DIALECT, and no string\n// parses here and fails there. Leading zeros are in (`\"007\"` is seven); a leading\n// \"+\", whitespace, `\"1.0\"` and `\"1e3\"` are out, \"+\" deliberately, because a grammar\n// can be WIDENED later and never narrowed. `\"-0\"` is zero: an integer has no signed\n// zero. THE ACCUMULATOR WORKS IN THE NEGATIVE RANGE — the wider half, so i64 min is\n// reachable as an intermediate — and every guard runs BEFORE the operation it\n// protects, so nothing ever wraps. A wrapped SIGN must never be used as a detector:\n// a long enough digit string wraps twice and the sign comes back.\n\n// i64's bounds. i64 min is spelled as max-minus-one because it has no decimal\n// literal: `-9223372036854775808` lexes as a negation of a magnitude that\n// overflows a positive i64 before the minus applies — the same fact `SIGN_BIT`\n// records for f64 further down.\nconst I64_MAX: i64 = 9223372036854775807\nconst I64_MIN: i64 = -9223372036854775807 - 1\n// i64 min divided by ten, truncated toward zero: the largest magnitude the\n// accumulator may already hold and still survive a multiply by ten.\nconst I64_MIN_DIV10: i64 = -922337203685477580\n// i32's bounds, held WIDE. They are compared against an i64 accumulator, and\n// widening them here is exactly what lets `parseI32` reject before it truncates.\nconst I32_MAX_WIDE: i64 = 2147483647\nconst I32_MIN_WIDE: i64 = -2147483648\n\n// The integer `self` spells, as an i64 — or `null` when `self` is not an\n// integer in this section's grammar, or denotes one outside `lo`..=`hi`\n// (inclusive). Both exported parsers ARE this function; they differ only in the\n// bounds they pass and in the width they hand back.\n//\n// `lo <= 0 <= hi` IS A PRECONDITION, because each sign is checked against ONE\n// bound: `lo` on the negative path, `hi` on the positive one. A range that does\n// not contain zero is therefore NOT enforced — `parseBoundedInt(\"-3\", -10, -5)`\n// answers -3, not null. Both callers here straddle zero, so the check is exact\n// for them; a third caller that does not (a bounded `u8`-valued field reader,\n// say) has to add the other half. The symmetric version is not written because\n// it needs `0 - lo`, which overflows at `lo == i64 min`, and no caller wants it.\nfunction parseBoundedInt(self: string, lo: i64, hi: i64): i64 | null {\n  const n = self.length\n  if n == 0 { return null }\n  let i = 0\n  let neg = false\n  // Only \"-\": a leading \"+\" is not part of this grammar (see the header — the\n  // subset rule), and falls through to the digit loop, which refuses it.\n  if self[0] == 45 {\n    neg = true\n    i = 1\n  }\n  // A sign with no digits after it denotes nothing.\n  if i >= n { return null }\n\n  // `acc` holds the value NEGATED — see the header: the negative half reaches\n  // i64 min, so `\"-9223372036854775808\"` is an ordinary intermediate here while\n  // the magnitude 9223372036854775808 never has to exist.\n  let acc: i64 = 0\n  while i < n {\n    const c = self[i]\n    // Spelled inline rather than through `isDigitByte` (which the f64 parser\n    // uses further down) because this is the hot loop's first test and the\n    // negated form lets the refusal return directly. One predicate, two\n    // spellings — if a third appears, collapse them.\n    if c < 48 || c > 57 { return null }\n    const d: i64 = c - 48\n    // Guard, THEN multiply: below this floor the product leaves i64 entirely.\n    if acc < I64_MIN_DIV10 { return null }\n    acc = acc * 10\n    // Guard, THEN subtract. `I64_MIN + d` adds a value in 0..=9 to i64 min, so\n    // the comparison's own arithmetic is always in range.\n    if acc < I64_MIN + d { return null }\n    acc = acc - d\n    i = i + 1\n  }\n\n  if neg {\n    if acc < lo { return null }\n    return acc\n  }\n  // `0 - acc` is safe only after this test, because `acc` may be i64 min, whose\n  // magnitude is not an i64. `hi` is at most i64 max, so `0 - hi` is always in\n  // range and the whole comparison can stay in the negative half.\n  if acc < 0 - hi { return null }\n  0 - acc\n}\n\n// The i64 that the decimal integer `self` spells, or `null` when `self` is not\n// one or does not fit. See the `TEXT → INTEGER` header for the grammar.\n//\n// OUT OF RANGE IS `null`, the OPPOSITE of `parseF64`'s rule, because the two TYPES\n// differ: a float has values meaning \"larger than any of me\", an integer has none,\n// so wrapping is a silent WRONG VALUE and saturating is indistinguishable from the\n// honest parse of the string one smaller. That does not put two meanings on one\n// channel, because for an integer \"out of range\" and \"not a number of this type\"\n// are the SAME statement. `i64 | null` IS THE CHANNEL for `parseF64`'s reason:\n// there is no information to carry — the parse consumes the whole string or fails,\n// so no position is honest — and `i64 | ParseIntError` stays a WIDENING std can\n// still travel to. Exact by construction: no float exists at any step.\nexport function parseI64(self: string): i64 | null {\n  parseBoundedInt(self, I64_MIN, I64_MAX)\n}\n\n// The i32 that the decimal integer `self` spells, or `null` when `self` is not\n// one or does not fit in 32 bits. Same grammar as `parseI64`; `\"2147483648\"`\n// and `\"-2147483649\"` are `null` rather than wrapped.\n//\n// TWO NAMES, NOT ONE, and this is NOT `parseI64` followed by a narrow: it\n// range-checks in the WIDE type first and truncates only behind that check, where\n// the truncation is provably lossless. Three things forced the pair. The RETURN\n// TYPE is the point — handing every i32 caller an `i64 | null` hands them a cast.\n// VL has NO return-type overloading and no return-position generic, so a single\n// `parseInt<T>(self: string): T | null` cannot be CALLED (the refusal is at the\n// USE, not the definition). And it mirrors `toString`'s domain exactly, which is\n// the rubric's \"a width-suffixed family stays uniform\" read across both directions.\nexport function parseI32(self: string): i32 | null {\n  const v = parseBoundedInt(self, I32_MIN_WIDE, I32_MAX_WIDE)\n  if v is null { return null }\n  // The only narrowing cast in this module. It is correct TWICE OVER, and the\n  // second reason arrived after the first: the bounds above already refused\n  // everything outside i32, and since the 2026-09-02 numeric-`as` ruling\n  // (DECISIONS.md §\"Numeric `as` to an INTEGER target is exact-or-fail under the\n  // trio\") an `i64 -> i32` `as!` is exact-or-fail rather than a wrap, so an\n  // out-of-range value would TRAP here rather than silently wrap. Moving this\n  // line in front of the check would therefore turn the null channel's job into\n  // an abort — still wrong, and now loudly so.\n  //\n  // (Until that ruling landed this comment read \"`as i32` is an unchecked\n  // wrapping truncation on this compiler\". That was true of the compiler it was\n  // measured against and is false of every one since.)\n  v as! i32\n}\n\n// ── f64 ↔ TEXT ──────────────────────────────────────────────────────────────\n// Serde stage 0 (`docs/serde-design.md` §Recommendation). Until this landed VL\n// could not render or read a float at all: the shortest-round-trip printer\n// `print` uses lives in the HOST's sink, never available as a VL string value.\n// THE STYLE IS ECMAScript `Number::toString`, radix 10, and that is a SPEC rather\n// than a preference — both hosts' print sinks already claim to implement it, so\n// `print(x.toString())` and `print(x)` are meant to be indistinguishable. The\n// layout rule is at `layoutDec`, the digit generator and the Ryū decline at\n// `shortestDigits`, the round trip and the host's tie disagreement at `renderF64`,\n// and the parser's grammar, channel and range rule at `parseF64`. BOTH HALVES LIVE\n// HERE because a flat namespace has one `toString`, so the formatter cannot move,\n// and splitting the parser off would divide a symmetric pair for bytes DCE owes.\n\n// ── exact big naturals ──────────────────────────────────────────────────────\n//\n// Little-endian limbs of 32 bits each, held in an `i64[]` so that a limb×small\n// product has room: (2^32−1) × 10^9 is inside i64's range, which is why every\n// multiplier below is capped at 10^9 and no 128-bit multiply is needed here.\n//\n// HIGH ZERO LIMBS ARE LEFT IN PLACE rather than trimmed, because `.pop()` on an\n// `i64[]` does not lower on this compiler: an `i64[]` PARAMETER refuses loudly\n// and an `i64[]` LOCAL is check-clean invalid wasm, both pinned by\n// `scripts/capability-probes/i64-list-pop.vl`. `bnLen` is the consequence — every\n// operation reads to the highest non-zero limb, not to `.length`. Delete it the\n// day that probe runs; nothing else here depends on it.\n\nconst BN_MASK: i64 = 4294967295\n\n// The number of limbs that carry value — the index of the highest non-zero\n// limb, plus one. Zero is length 0.\nfunction bnLen(a: i64[]): i32 {\n  let i = a.length - 1\n  while i >= 0 && a[i] == 0 { i = i - 1 }\n  i + 1\n}\n\nfunction bnIsZero(a: i64[]): boolean { bnLen(a) == 0 }\n\n// A fresh big natural holding `v`, which must not be negative.\nfunction bnFromI64(v: i64): i64[] {\n  const out: i64[] = []\n  let x = v\n  while x > 0 {\n    out.push(x & BN_MASK)\n    x = x >>> 32\n  }\n  out\n}\n\nfunction bnCopy(a: i64[]): i64[] {\n  const out: i64[] = []\n  let i = 0\n  while i < a.length {\n    out.push(a[i])\n    i = i + 1\n  }\n  out\n}\n\n// -1, 0 or 1 as `a` is less than, equal to, or greater than `b`.\nfunction bnCmp(a: i64[], b: i64[]): i32 {\n  const la = bnLen(a)\n  const lb = bnLen(b)\n  if la != lb {\n    if la < lb { return -1 }\n    return 1\n  }\n  let i = la - 1\n  while i >= 0 {\n    if a[i] != b[i] {\n      if a[i] < b[i] { return -1 }\n      return 1\n    }\n    i = i - 1\n  }\n  0\n}\n\n// `a += b`, in place.\nfunction bnAddInto(a: i64[], b: i64[]) {\n  let carry: i64 = 0\n  let i = 0\n  while i < b.length || carry != 0 {\n    if i >= a.length { a.push(0) }\n    let s = a[i] + carry\n    if i < b.length { s = s + b[i] }\n    a[i] = s & BN_MASK\n    carry = s >>> 32\n    i = i + 1\n  }\n}\n\n// `a -= b`, in place. The caller guarantees `a >= b`; a smaller `a` would\n// borrow off the top and produce a garbage value rather than trapping, so\n// every call site here is preceded by a `bnCmp`.\nfunction bnSubInto(a: i64[], b: i64[]) {\n  let borrow: i64 = 0\n  let i = 0\n  while i < a.length {\n    let d = a[i] - borrow\n    if i < b.length { d = d - b[i] }\n    if d < 0 {\n      d = d + 4294967296\n      borrow = 1\n    } else {\n      borrow = 0\n    }\n    a[i] = d\n    i = i + 1\n  }\n}\n\n// `a *= m`, in place. `m` must be at most 10^9 — see the limb-width note above.\nfunction bnMulSmall(a: i64[], m: i64) {\n  let carry: i64 = 0\n  let i = 0\n  while i < a.length {\n    const p = a[i] * m + carry\n    a[i] = p & BN_MASK\n    carry = p >>> 32\n    i = i + 1\n  }\n  while carry != 0 {\n    a.push(carry & BN_MASK)\n    carry = carry >>> 32\n  }\n}\n\n// 10^n for n in 0..=18, which is every n this file asks for.\nfunction pow10i64(n: i32): i64 {\n  let p: i64 = 1\n  let i = 0\n  while i < n {\n    p = p * 10\n    i = i + 1\n  }\n  p\n}\n\n// `a *= 10^k`, in place, in 10^9 chunks so the per-limb product stays in range.\nfunction bnMulPow10(a: i64[], k: i32) {\n  if bnIsZero(a) { return }\n  let n = k\n  while n >= 9 {\n    bnMulSmall(a, 1000000000)\n    n = n - 9\n  }\n  if n > 0 { bnMulSmall(a, pow10i64(n)) }\n}\n\n// `a <<= bits`, in place. The sub-limb shift runs first so the whole-limb move\n// only ever relocates finished limbs.\nfunction bnShlInto(a: i64[], bits: i32) {\n  if bnIsZero(a) { return }\n  const whole = bits / 32\n  const rem = bits % 32\n  if rem > 0 {\n    let carry: i64 = 0\n    let i = 0\n    while i < a.length {\n      const v = (a[i] << rem) | carry\n      a[i] = v & BN_MASK\n      carry = v >>> 32\n      i = i + 1\n    }\n    if carry != 0 { a.push(carry) }\n  }\n  if whole > 0 {\n    let j = 0\n    while j < whole {\n      a.push(0)\n      j = j + 1\n    }\n    let i = a.length - 1\n    while i >= whole {\n      a[i] = a[i - whole]\n      i = i - 1\n    }\n    let z = 0\n    while z < whole {\n      a[z] = 0\n      z = z + 1\n    }\n  }\n}\n\n// `a >>= 1`, in place.\nfunction bnShr1(a: i64[]) {\n  let i = a.length - 1\n  let carry: i64 = 0\n  while i >= 0 {\n    const v = a[i] | (carry << 32)\n    a[i] = v >>> 1\n    carry = v & 1\n    i = i - 1\n  }\n}\n\nfunction bnBitLen(a: i64[]): i32 {\n  const n = bnLen(a)\n  if n == 0 { return 0 }\n  return (n - 1) * 32 + ((64 - clz(a[n - 1])) as! i32)\n}\n\n// The big natural spelled by `d`, a list of decimal digit VALUES (0..=9).\n// Nine digits at a time, so the multiplier stays inside `bnMulSmall`'s range.\nfunction bnFromDigits(d: i32[]): i64[] {\n  const out = bnFromI64(0)\n  let i = 0\n  while i < d.length {\n    let chunk: i64 = 0\n    let c = 0\n    while c < 9 && i < d.length {\n      const dv: i64 = d[i]\n      chunk = chunk * 10 + dv\n      i = i + 1\n      c = c + 1\n    }\n    bnMulSmall(out, pow10i64(c))\n    bnAddInto(out, bnFromI64(chunk))\n  }\n  out\n}\n\n// floor(a / b), leaving the exact remainder in `a`. Shift-and-subtract from\n// the top, so the loop runs once per QUOTIENT bit rather than once per bit of\n// `a`; the caller arranges a quotient of at most ~55 bits, which is what makes\n// the i64 result and the loop bound safe.\nfunction bnDivMod(a: i64[], b: i64[]): i64 {\n  if bnCmp(a, b) < 0 { return 0 }\n  const shift = bnBitLen(a) - bnBitLen(b)\n  const d = bnCopy(b)\n  bnShlInto(d, shift)\n  let q: i64 = 0\n  let i = shift\n  while i >= 0 {\n    q = q << 1\n    if bnCmp(a, d) >= 0 {\n      bnSubInto(a, d)\n      q = q + 1\n    }\n    bnShr1(d)\n    i = i - 1\n  }\n  q\n}\n\n// ── f64 → text ──────────────────────────────────────────────────────────────\n\n// The shortest digit string that identifies a value, with the exponent that\n// places it: value = 0.d[0]d[1]… × 10^n.\ntype DecDigits = { d: i32[], n: i32 }\n\n// `r + mp` against `s`, with the comparison inclusive when the significand is\n// even (round-to-nearest-even hands an even significand its own boundaries).\nfunction upperTest(r: i64[], mp: i64[], s: i64[], inclusive: boolean): boolean {\n  const t = bnCopy(r)\n  bnAddInto(t, mp)\n  const c = bnCmp(t, s)\n  if inclusive { return c >= 0 }\n  c > 0\n}\n\n// Burger–Dybvig over exact rationals; `x` must be finite and strictly positive.\n// The value is held as R/S with the two half-ulp boundaries M+ and M−, all four\n// exact big integers, and digits are generated until the emitted prefix already\n// identifies the value uniquely within (v−M−, v+M+). Correctness is by\n// construction, not by table: no digit is emitted that the interval does not\n// force, and the loop cannot stop early because stopping IS the interval test.\n// Boundary inclusivity follows round-to-nearest-EVEN, so an even significand owns\n// its boundaries and an odd one does not.\n//\n// RYŪ WAS DECLINED: faster, but it needs a large power-of-five constant table and\n// a synthesised 128-bit multiply, and its correctness rests on bounds proven\n// elsewhere — a std module with no deprecation story should be re-derivable.\nfunction shortestDigits(x: f64): DecDigits {\n  const bits = f64bits(x)\n  const be = ((bits >>> 52) & 2047) as! i32\n  const frac = bits & 4503599627370495\n  let m = frac\n  let e = -1074\n  if be != 0 {\n    m = frac + 4503599627370496\n    e = be - 1075\n  }\n  const evenB = (m & 1) == 0\n  // The gap BELOW is half the gap above exactly when the significand sits at\n  // the bottom of a binade and there is a binade below it to fall into — so\n  // `frac == 0` and an exponent above the subnormal one. Get this wrong and\n  // powers of two render one digit too long.\n  const smaller = frac == 0 && be > 1\n\n  const r = bnFromI64(m)\n  const s = bnFromI64(1)\n  const mp = bnFromI64(1)\n  const mm = bnFromI64(1)\n  if e >= 0 {\n    if smaller {\n      bnShlInto(r, e + 2)\n      bnShlInto(s, 2)\n      bnShlInto(mp, e + 1)\n      bnShlInto(mm, e)\n    } else {\n      bnShlInto(r, e + 1)\n      bnShlInto(s, 1)\n      bnShlInto(mp, e)\n      bnShlInto(mm, e)\n    }\n  } else {\n    if smaller {\n      bnShlInto(r, 2)\n      bnShlInto(s, 2 - e)\n      bnShlInto(mp, 1)\n    } else {\n      bnShlInto(r, 1)\n      bnShlInto(s, 1 - e)\n    }\n  }\n\n  // `n` is the smallest integer with value + M+ ≤ 10^n. The float estimate is\n  // deliberately biased LOW (log10(2) times the binary magnitude, minus one),\n  // so the fixup below only ever climbs — which makes the result independent\n  // of how tight the estimate is, and stops at the first n that qualifies, so\n  // it is the minimal one.\n  const bl = 64 - (clz(m) as! i32)\n  let k = ((floor(((bl + e - 1) as! f64) * 0.3010299956639812)) as! i32) - 1\n  if k >= 0 {\n    bnMulPow10(s, k)\n  } else {\n    bnMulPow10(r, 0 - k)\n    bnMulPow10(mp, 0 - k)\n    bnMulPow10(mm, 0 - k)\n  }\n  while upperTest(r, mp, s, evenB) {\n    bnMulSmall(s, 10)\n    k = k + 1\n  }\n\n  // One digit per turn: scale by ten, take the quotient by repeated\n  // subtraction (it is 0..=9 by construction, so at most nine of them), then\n  // ask whether the interval still needs another digit. `low` means the\n  // remainder is already inside the lower boundary, `high` that adding one to\n  // this digit lands inside the upper one; either alone terminates, and both\n  // together take the closer of the two with the spec's even tie-break.\n  //\n  // The 25-digit bound is a floor, not a policy: a double never needs more\n  // than 17, and a hypothetical 25th digit would still name the right value —\n  // just not the shortest one.\n  const digits: i32[] = []\n  let done = false\n  while !done && digits.length < 25 {\n    bnMulSmall(r, 10)\n    bnMulSmall(mp, 10)\n    bnMulSmall(mm, 10)\n    let d = 0\n    while bnCmp(r, s) >= 0 {\n      bnSubInto(r, s)\n      d = d + 1\n    }\n    const cLow = bnCmp(r, mm)\n    let low = cLow < 0\n    if evenB { low = cLow <= 0 }\n    const high = upperTest(r, mp, s, evenB)\n    if low && high {\n      const t = bnCopy(r)\n      bnMulSmall(t, 2)\n      const c = bnCmp(t, s)\n      if c > 0 { d = d + 1 }\n      else if c == 0 && (d % 2) != 0 { d = d + 1 }\n      digits.push(d)\n      done = true\n    } else if low {\n      digits.push(d)\n      done = true\n    } else if high {\n      digits.push(d + 1)\n      done = true\n    } else {\n      digits.push(d)\n    }\n  }\n\n  // A terminating `d + 1` can carry out of 9. The scaling above is chosen so\n  // this should not be reachable, and it is handled anyway because the failure\n  // mode if it ever were would be a silently wrong digit rather than a crash.\n  let ci = digits.length - 1\n  let carrying = true\n  while carrying && ci >= 0 {\n    if digits[ci] != 10 {\n      carrying = false\n    } else {\n      digits[ci] = 0\n      if ci == 0 {\n        digits[0] = 1\n        k = k + 1\n        carrying = false\n      } else {\n        digits[ci - 1] = digits[ci - 1] + 1\n        ci = ci - 1\n      }\n    }\n  }\n  while digits.length > 1 && digits[digits.length - 1] == 0 { digits.pop() }\n\n  { d: digits, n: k }\n}\n\n// The four-way layout of ECMA-262 `Number::toString` step 5, over a digit list\n// and its exponent. With `s` the SHORTEST digit string (k digits, no radix point)\n// and `n` the exponent such that value = 0.s × 10^n:\n//\n//     k ≤ n ≤ 21   → the digits, then n−k zeros            (\"100\")\n//     0 < n ≤ 21   → a radix point n digits in             (\"1.5\")\n//     −6 < n ≤ 0   → \"0.\" then −n zeros then the digits    (\"0.000001\")\n//     otherwise    → exponential, exponent always signed   (\"1e+21\", \"1e-7\")\n//\n// The specials belong to `renderF64`. Among equally short digit strings the spec\n// takes the one closest to the value, and on an exact tie the one whose last digit\n// is EVEN; `shortestDigits` is what enforces both.\nfunction layoutDec(d: i32[], n: i32): string {\n  const k = d.length\n  const buf: i32[] = []\n  if k <= n && n <= 21 {\n    let i = 0\n    while i < k {\n      buf.push(48 + d[i])\n      i = i + 1\n    }\n    let z = 0\n    while z < n - k {\n      buf.push(48)\n      z = z + 1\n    }\n    return fromCodePoints(buf)\n  }\n  if n > 0 && n <= 21 {\n    let i = 0\n    while i < n {\n      buf.push(48 + d[i])\n      i = i + 1\n    }\n    buf.push(46)\n    while i < k {\n      buf.push(48 + d[i])\n      i = i + 1\n    }\n    return fromCodePoints(buf)\n  }\n  if n > -6 && n <= 0 {\n    buf.push(48)\n    buf.push(46)\n    let z = 0\n    while z < 0 - n {\n      buf.push(48)\n      z = z + 1\n    }\n    let i = 0\n    while i < k {\n      buf.push(48 + d[i])\n      i = i + 1\n    }\n    return fromCodePoints(buf)\n  }\n  buf.push(48 + d[0])\n  if k > 1 {\n    buf.push(46)\n    let i = 1\n    while i < k {\n      buf.push(48 + d[i])\n      i = i + 1\n    }\n  }\n  const ex = n - 1\n  if ex >= 0 {\n    const up: i64 = ex\n    return fromCodePoints(buf) + \"e+\" + renderI64(up)\n  }\n  const down: i64 = 0 - ex\n  fromCodePoints(buf) + \"e-\" + renderI64(down)\n}\n\n// `toString`'s f64 arm. The sign is read off the BIT PATTERN rather than by\n// comparing with zero, because `-0.0 < 0.0` is false and the exponent/fraction\n// split is already in hand. Specials: NaN → \"NaN\", ±∞ → \"Infinity\"/\"-Infinity\",\n// both zeros → \"0\".\n//\n// ROUND TRIP: `parseF64(x.toString())` is bit-identical to `x` for every finite\n// f64 EXCEPT −0, and answers a NaN for NaN. Both exceptions are the STYLE's, not\n// the algorithm's — the spec renders −0 as `\"0\"`, so the sign is gone before the\n// parser sees it, and `\"NaN\"` carries no payload. THE RUST HOST'S `print`\n// DISAGREES AT EXACT DECIMAL TIES, rounding away from even where the spec rounds\n// to even; this file follows the spec and the V8 host, and\n// `tests/vl_std_float_text_test.ts` pins the divergence so it flips when it moves.\nfunction renderF64(x: f64): string {\n  const bits = f64bits(x)\n  const be = ((bits >>> 52) & 2047) as! i32\n  const frac = bits & 4503599627370495\n  if be == 2047 {\n    if frac != 0 { return \"NaN\" }\n    if bits < 0 { return \"-Infinity\" }\n    return \"Infinity\"\n  }\n  // Both zeros render \"0\" — the spec's rule, and the reason -0 does not\n  // survive a round trip through text.\n  if be == 0 && frac == 0 { return \"0\" }\n  const dd = shortestDigits(abs(x))\n  const body = layoutDec(dd.d, dd.n)\n  if bits < 0 { return \"-\" + body }\n  body\n}\n\n// ── text → f64 ──────────────────────────────────────────────────────────────\n\nconst ONE64: i64 = 1\n// 0x8000_0000_0000_0000. Spelled as a shift because i64 min has no decimal\n// literal: its magnitude overflows a positive i64 before any minus applies.\nconst SIGN_BIT: i64 = ONE64 << 63\nconst BITS_INF: i64 = 9218868437227405312\nconst BITS_NAN: i64 = 9221120237041090560\nconst TWO53: i64 = 9007199254740992\nconst MAX_SIG_DIGITS = 800\n\nfunction withSign(v: f64, neg: boolean): f64 {\n  if neg { return f64fromBits(f64bits(v) | SIGN_BIT) }\n  v\n}\n\nfunction isDigitByte(c: i32): boolean { c >= 48 && c <= 57 }\n\n// 10^e, exactly, for e in 0..=22 — the range over which a power of ten is\n// representable as an f64 (10^22 = 2^22 · 5^22 and 5^22 < 2^53). Each step is\n// a product of two exactly representable values whose result is exactly\n// representable, so IEEE rounding is a no-op. Callers must not exceed 22.\nfunction pow10f(e: i32): f64 {\n  let p = 1.0\n  let i = 0\n  while i < e {\n    p = p * 10.0\n    i = i + 1\n  }\n  p\n}\n\n// The f64 nearest to the number `self` spells, or `null` when `self` is not a\n// number in this grammar: `\"-\"? ( \"Infinity\" | digits (\".\" digits)? ([eE][+-]?\n// digits)? )` or `\"NaN\"` — JSON's number grammar plus the two specials, NOT VL's\n// literal grammar. Digit separators are legal VL and REFUSED here (a separator is\n// a source affordance; this reads DATA), as are a leading \"+\", whitespace, a bare\n// `\"1.\"` or `\".5\"`, `\"0x10\"` and `\"-NaN\"`. Leading zeros are accepted.\n//\n// `f64 | null` IS THE CHANNEL: nothing would go in an error struct, since the\n// parse consumes the WHOLE string or fails, so no position is honest. OUT OF RANGE\n// IS NOT A PARSE FAILURE — overflow answers ±Infinity, underflow ±0, as `strtod`\n// and `Number()` do; `null` is the SYNTAX channel and nothing else. Correctly\n// rounded for EVERY accepted input, halfway cases included.\nexport function parseF64(self: string): f64 | null {\n  const n = self.length\n  if n == 0 { return null }\n  let i = 0\n  let neg = false\n  if self[0] == 45 {\n    neg = true\n    i = 1\n  }\n  if i >= n { return null }\n  const c0 = self[i]\n  if c0 == 73 {\n    if self.slice(i, n) != \"Infinity\" { return null }\n    return withSign(f64fromBits(BITS_INF), neg)\n  }\n  if c0 == 78 {\n    // \"NaN\" only, unsigned: the renderer never produces a sign on it and VL\n    // has no such literal, so \"-NaN\" would be a spelling nothing else uses.\n    if neg { return null }\n    if self != \"NaN\" { return null }\n    return f64fromBits(BITS_NAN)\n  }\n\n  // `digs` collects SIGNIFICANT digits (leading zeros contribute only to the\n  // exponent) and `exp10` is the power of ten the digit string is multiplied\n  // by. Digits past the cap move `exp10` when they are integer places and set\n  // `truncated` when they are non-zero — see `MAX_SIG_DIGITS`'s block above.\n  const digs: i32[] = []\n  let exp10 = 0\n  let truncated = false\n  const istart = i\n  while i < n && isDigitByte(self[i]) {\n    const d = self[i] - 48\n    // A LEADING zero of the integer part contributes nothing at all — not a\n    // significant digit, and not a place either, so `\"007\"` is `7` with the\n    // exponent untouched.\n    if digs.length > 0 || d != 0 {\n      if digs.length < MAX_SIG_DIGITS {\n        digs.push(d)\n      } else {\n        // Past the cap an integer digit is still a PLACE, so it moves the\n        // exponent; only a non-zero one moves the value.\n        exp10 = exp10 + 1\n        if d != 0 { truncated = true }\n      }\n    }\n    i = i + 1\n  }\n  if i == istart { return null }\n  if i < n && self[i] == 46 {\n    i = i + 1\n    const fstart = i\n    while i < n && isDigitByte(self[i]) {\n      const d = self[i] - 48\n      // Every fraction digit is a place, INCLUDING the leading zeros of\n      // `\"0.0012\"` — they move the exponent without becoming significant.\n      // Past the cap the exponent must NOT move (the place is already accounted\n      // for by the digits that were kept), so only truncation is recorded.\n      //\n      // SIGNIFICANT DIGITS ARE CAPPED, with a `truncated` flag. The bound is the\n      // classic one — enough digits to separate any decimal from a double's\n      // rounding boundary — plus slack: beyond it, dropped digits cannot move the\n      // comparison EXCEPT by turning an exact tie into a value strictly above it,\n      // which is exactly what the flag records. Without a cap a megabyte of digits\n      // would be a megabyte of big integer, a denial-of-service surface for the\n      // JSON reader this half is built for.\n      if digs.length >= MAX_SIG_DIGITS {\n        if d != 0 { truncated = true }\n      } else {\n        if digs.length > 0 || d != 0 { digs.push(d) }\n        exp10 = exp10 - 1\n      }\n      i = i + 1\n    }\n    if i == fstart { return null }\n  }\n  if i < n && (self[i] == 101 || self[i] == 69) {\n    i = i + 1\n    let es = 1\n    if i < n && self[i] == 43 {\n      i = i + 1\n    } else if i < n && self[i] == 45 {\n      es = -1\n      i = i + 1\n    }\n    const estart = i\n    let ev = 0\n    while i < n && isDigitByte(self[i]) {\n      // Saturating: any exponent past a million is already decided by the\n      // range gate below, and letting it run would overflow the i32.\n      if ev < 1000000 { ev = ev * 10 + (self[i] - 48) }\n      i = i + 1\n    }\n    if i == estart { return null }\n    exp10 = exp10 + es * ev\n  }\n  // Trailing anything — a unit, a stray digit separator, whitespace — is a\n  // rejection rather than a partial parse.\n  if i != n { return null }\n\n  if digs.length == 0 { return withSign(0.0, neg) }\n  // The magnitude gate, before any big integer exists: the value lies in\n  // [10^(dmag-1), 10^dmag), the largest f64 is under 10^309 and anything below\n  // 10^-350 is far under half the smallest subnormal.\n  const dmag = exp10 + digs.length\n  if dmag > 310 { return withSign(f64fromBits(BITS_INF), neg) }\n  if dmag < -350 { return withSign(0.0, neg) }\n\n  // Clinger's fast path: both operands exact, one rounding. With at most fifteen\n  // significant digits and a decimal exponent inside ±22, the significand and the\n  // power of ten are each exactly representable, so a single IEEE multiply or\n  // divide is a single correctly rounded rounding — Clinger's theorem. It covers\n  // `\"0.1\"` and most human-written numbers; everything else falls to the exact\n  // path below, which is integer arithmetic with no rounding until the last step.\n  if digs.length <= 15 && exp10 >= -22 && exp10 <= 22 {\n    let acc: i64 = 0\n    let j = 0\n    while j < digs.length {\n      const dv: i64 = digs[j]\n      acc = acc * 10 + dv\n      j = j + 1\n    }\n    let v = acc as! f64\n    if exp10 > 0 { v = v * pow10f(exp10) }\n    if exp10 < 0 { v = v / pow10f(0 - exp10) }\n    return withSign(v, neg)\n  }\n\n  // The exact path. value = num / den, both integers, no rounding yet.\n  const num = bnFromDigits(digs)\n  const den = bnFromI64(1)\n  if exp10 > 0 { bnMulPow10(num, exp10) }\n  if exp10 < 0 { bnMulPow10(den, 0 - exp10) }\n\n  // Choose the binary exponent so the quotient has 53 bits. The bit-length\n  // difference brackets log2(num/den) within one, so the quotient lands in\n  // [2^52, 2^54) and at most a couple of corrections are needed; -1074 is the\n  // floor because no double has a smaller exponent, and a quotient under 2^52\n  // there is exactly what a subnormal is.\n  let e2 = bnBitLen(num) - bnBitLen(den) - 53\n  if e2 < -1074 { e2 = -1074 }\n  let q: i64 = 0\n  let rem = bnFromI64(0)\n  let dn = bnFromI64(0)\n  let settled = false\n  while !settled {\n    if e2 + 1075 >= 2047 { return withSign(f64fromBits(BITS_INF), neg) }\n    rem = bnCopy(num)\n    dn = bnCopy(den)\n    if e2 > 0 { bnShlInto(dn, e2) }\n    if e2 < 0 { bnShlInto(rem, 0 - e2) }\n    q = bnDivMod(rem, dn)\n    if q >= TWO53 { e2 = e2 + 1 } else { settled = true }\n  }\n\n  // Round to nearest, ties to even — except that a truncated tail means the\n  // true value is strictly above the tie, so it rounds up.\n  const t = bnCopy(rem)\n  bnMulSmall(t, 2)\n  const c = bnCmp(t, dn)\n  let up = false\n  if c > 0 {\n    up = true\n  } else if c == 0 {\n    if truncated { up = true }\n    else if (q & 1) != 0 { up = true }\n  }\n  if up { q = q + 1 }\n  if q >= TWO53 {\n    q = q / 2\n    e2 = e2 + 1\n  }\n  if e2 + 1075 >= 2047 { return withSign(f64fromBits(BITS_INF), neg) }\n  // One expression for both classes: with q in [2^52, 2^53) the carry out of\n  // the significand IS the exponent field's low bit, and with e2 pinned at\n  // -1074 the term vanishes and q lands in the fraction field, which is the\n  // subnormal encoding.\n  const be2: i64 = e2 + 1074\n  return withSign(f64fromBits((be2 << 52) + q), neg)\n}\n",
  "std:fs": "// `std:fs` — the filesystem, and VL's first FALLIBLE std module.\n//\n// A missing file is not a BUG, so this module cannot trap the way `std:fmt` / `std:array` /\n// `std:buffer` do; `docs/error-handling-design.md` says how VL spells the alternative:\n// **errors are values, carried in the return type as a union**. There is no `throw` and no\n// `try`, and `__trap__` appears in this file zero times. `T | IoError` is reasoned failure on\n// every read/list/stat surface; `T | null` is expected absence, never an I/O failure — only\n// \"it succeeded and has nothing to report\" (`writeFile` returns `IoError | null`).\n//\n// `IoError = { code: i32, msg: string }` is the ruled shape: `code` is the WASI errno as a\n// POSITIVE number (the constants below name the ones worth testing), `msg` a human sentence\n// naming the operation and the path. It is meant to EXTEND the design doc's floor shape\n// `{ msg: string }` but does not at this compiler head: a `{code, msg}` value does not satisfy\n// a `{msg}` parameter, and `x is Err` over an `IoError` arm is a hard type error. So a caller\n// handles `IoError` BY NAME and \"any error\" has to spell the union. The `as` trio works over\n// these unions; the bodies keep `if e is IoError { return e }` — the boilerplate this measures.\n//\n// TWO DELIBERATE BREAKS WITH std HOUSE STYLE, justified here as `std-api-review.md` requires.\n// (1) NOT `self`-FIRST, so these are free functions and not UFCS methods: `self` is the UFCS\n// SWITCH, matched on the literal parameter name, so calling the first parameter `path` makes\n// `\"hello\".readTextFile()` unspellable by construction — the thing operated on is the FILE,\n// not the string naming it. (2) NOUN-FIRST for the two questions, `pathKind`/`pathExists` not\n// `kind`/`exists`: VL has no namespace import, so every export lands in the importer's flat\n// top-level scope where a bare `exists` collides with every other existence check. And\n// `pathKind` is not `stat`, which would promise the size, mtime and mode this cannot report.\n//\n// WHAT CROSSES THE FLOOR. The intrinsics take and return `u8[]` — packed GC byte arrays, no\n// linear memory, no pointers, no capacities. Paths cross as UTF-8 bytes because that is what\n// POSIX stores; CONTENT crosses as bytes because a file is bytes and a PNG or a zip must\n// survive a round trip. Text is a DECODING on top, which is why `readFile`/`readTextFile` are\n// two functions and not one with a flag; `std:utf8` owns the conversion and the policy.\n//\n// WHAT THIS MODULE DOES NOT DO. No path manipulation (a future `std:fs/path`; until then\n// `dir + \"/\" + name` is the join). No open handles, seeking, streaming or partial reads:\n// every read is whole-file, so a file larger than memory is not readable here. No metadata\n// beyond file-or-directory, no mkdir, remove, rename or symlink inspection — each is a floor\n// intrinsic that does not exist yet, and a std wrapper for a syscall VL cannot make is a name\n// that fails at emit. And nothing here is atomic against another process, which is why\n// nothing pre-checks for the caller: `readFile` does not stat first for a prettier error, it\n// reads and reports what the host said — a pre-check costs a syscall and buys a race.\n\nimport { Utf8Error, decodeUtf8, decodeUtf8At, encodeUtf8 } from \"std:utf8\"\n// `toString` is `std:fmt`'s export as of 2026-09-01, not the ambient builtin it was\n// (owner ruling, DECISIONS.md). Two errno/offset renderings here need it. `std:utf8`\n// above already pulls `std:fmt` in for the same reason, so this import adds a NAME and\n// no bytes; the price and why a private renderer was refused are in `std:utf8`'s header.\nimport { toString } from \"std:fmt\"\n\n// The blessed I/O error shape (`docs/error-handling-design.md` O3). `code` is\n// the WASI errno as a POSITIVE number — the floor reports `-errno` and this\n// module negates once, at the boundary, so a caller never sees a sign\n// convention.\nexport type IoError = { code: i32, msg: string }\n\n// The result of an operation that has NOTHING to report when it succeeds: a reason, or `null`\n// for \"it worked\". This is the `T | null` layer doing exactly what it is for — a successful\n// whole-file write has no value to hand back, and inventing one (a byte count the floor never\n// reported, a boolean that is only ever `true`) would be fabricating information.\n//\n// Spelled as a NAMED alias rather than inline as `IoError | null` in each signature. That WAS\n// a constraint and is now a preference: a struct appearing both in an inline `S | null` and in\n// another union of the same module used to fail at emit with `ref valtype with no interned\n// shape`, because only the declaration route interned the shape. Both routes intern it now,\n// the inline spelling lowering as the `nulvariant` niche. The alias stays because it names the\n// concept once and reads better at every call site.\nexport type IoResult = IoError | null\n\n// What a path names. A literal union rather than a struct or an i32: it is one\n// closed question with two answers today, `match` dispatches it exhaustively,\n// and a third answer (`\"symlink\"`) is a one-word edit that makes every existing\n// `match` fail loudly instead of silently falling through.\nexport type FileKind = \"file\" | \"dir\"\n\n// The errno numbers worth naming, in WASI preview1's numbering (which is what\n// the host reports and what `docs/error-handling-design.md` already uses when it\n// writes `{ code: 44, msg: \"no such file\" }`). These are the codes a program\n// actually branches on; the rest are rendered by number.\nexport const EACCES = 2\nexport const EILSEQ = 25\nexport const EINVAL = 28\nexport const EIO = 29\nexport const EISDIR = 31\nexport const ENOENT = 44\nexport const ENOSPC = 51\nexport const ENOTDIR = 54\nexport const EPERM = 63\n\n// The errno as a short name, or `\"errno N\"` for everything else. Deliberately\n// not a 76-arm table: these are the ones a caller can do something about, and a\n// number is a perfectly good rendering of a code nobody branches on.\nfunction errName(code: i32) {\n  if code == EACCES { return \"EACCES (permission denied)\" }\n  if code == EILSEQ { return \"EILSEQ (invalid byte sequence)\" }\n  if code == EINVAL { return \"EINVAL (invalid argument)\" }\n  if code == EIO { return \"EIO (i/o error)\" }\n  if code == EISDIR { return \"EISDIR (is a directory)\" }\n  if code == ENOENT { return \"ENOENT (no such file or directory)\" }\n  if code == ENOSPC { return \"ENOSPC (no space left on device)\" }\n  if code == ENOTDIR { return \"ENOTDIR (not a directory)\" }\n  if code == EPERM { return \"EPERM (operation not permitted)\" }\n  \"errno \" + toString(code)\n}\n\n// The one message shape, so every error out of this module reads the same and a\n// grep for one of them finds all of them. The operation is named because the\n// path alone does not say whether the read or the decode failed.\nfunction failed(op: string, path: string, code: i32) {\n  \"fs.\" + op + \" \" + path + \": \" + errName(code)\n}\n\n// The errno for a floor call that answered EMPTY.\n//\n// The module's one piece of GLOBAL STATE, a DEVIATION knowingly taken:\n// `docs/internals/std-api-review.md` §2 flags ambient state and requires the constraint that\n// forced it be named. Neither in-band shape lowered, so the reason travels out of band through\n// `__fs_errno__()` — read it IMMEDIATELY after the failed call, never otherwise. That\n// constraint has since lifted (`u8[] | i32` lowers and runs); this wrapper keeps the swap cheap.\n//\n// RETURNS 0 WHEN THE LAST CALL DID NOT FAIL, and that zero is load-bearing: the floor signals\n// failure with an EMPTY `u8[]`, which an empty FILE and an empty DIRECTORY also produce, so\n// the errno is what tells them apart. A negative errno is folded, so `-ENOENT` and `ENOENT`\n// from two floors are the same to every caller.\nfunction lastErrno(): i32 {\n  const e = __fs_errno__()\n  if e < 0 { return 0 - e }\n  e\n}\n\n// Whether an EMPTY result from a `u8[]`-returning intrinsic is a failure, and if\n// so which. Returns 0 for \"not a failure — the file or directory really is\n// empty\". One home for the empty-plus-errno protocol, so the three call sites\n// cannot drift, and so the swap to an in-band `u8[] | i32` floor (now expressible\n// — see #1806) is a change to this function rather than to every caller.\nfunction emptyErrno(): i32 { lastErrno() }\n\n// The message for an empty path, which every entry point rejects before it reaches the floor.\n// This is the ONLY policy this module applies ahead of the syscall, and it earns its place\n// twice: `\"\"` names nothing on any host (POSIX `openat` answers ENOENT, other hosts vary),\n// and answering identically everywhere is worth one comparison.\n//\n// Only the MESSAGE is factored out, not the error value, and that is a constraint rather than\n// a preference: a struct produced by a CALL and flowing into a union position does not lower\n// — `return someHelper()` from a function returning `T | IoError` fails at emit with `ref\n// valtype with no interned shape`. Every `IoError` in this file is therefore an object\n// LITERAL written at the site that returns it; factoring them into a constructor is the\n// obvious tidy-up and it does not compile.\nfunction emptyPathMsg(op: string) { \"fs.\" + op + \": the path is empty\" }\n\n// `readFile(path)` — the whole file as bytes, or why not.\n//\n// BYTES, not text: this is the function that reads a PNG. Whole-file only —\n// there is no handle, no offset and no way to read part of one, so the result is\n// as large as the file and a file that does not fit in memory is not readable\n// here.\nexport function readFile(path: string): u8[] | IoError {\n  if path.length == 0 { return { code: EINVAL, msg: emptyPathMsg(\"readFile\") } }\n  const r = __fs_read__(encodeUtf8(path))\n  // EMPTY is the floor's failure signal AND a legitimate empty file, so the\n  // errno is the disambiguator — see `emptyErrno`.\n  if r.length == 0 {\n    const e = emptyErrno()\n    if e != 0 { return { code: e, msg: failed(\"readFile\", path, e) } }\n  }\n  r\n}\n\n// `readTextFile(path)` — the whole file, decoded as UTF-8.\n//\n// Two failures, one type: the read can fail (any errno the host reports) and the\n// DECODE can fail (`EILSEQ`, with the byte offset in the message). The second is\n// the honest answer to \"this file is not text\" — see `std:utf8` for why the\n// strict decode is the default and `decodeUtf8Lossy` is the opt-out. A caller\n// who wants the lossy behaviour reads bytes and decodes them itself; that is two\n// lines and it is not this function's decision to make.\nexport function readTextFile(path: string): string | IoError {\n  // Guarded here as well as in `readFile`, so the message names the function the\n  // caller actually called. Every OTHER error below is forwarded verbatim from\n  // the call that produced it, and keeps that call's operation name — which is\n  // where the failure really happened, and is more useful than a re-wrap.\n  if path.length == 0 {\n    return { code: EINVAL, msg: emptyPathMsg(\"readTextFile\") }\n  }\n  const bytes = readFile(path)\n  if bytes is IoError { return bytes }\n  const text = decodeUtf8(bytes)\n  if text is Utf8Error {\n    return { code: EILSEQ, msg: \"fs.readTextFile \" + path + \": \" + text.msg }\n  }\n  text\n}\n\n// `writeFile(path, data)` — replace the file's contents with `data`.\n//\n// Returns `IoResult` — `null` IS the success case, because a successful write\n// has nothing to report; no partial-write count exists at this floor, so\n// returning one would be a fabrication. The call site reads\n// `if e != null { … }`.\n//\n// Whether the file is created, truncated or replaced atomically is the HOST's\n// policy, not this module's, and it is documented where the intrinsic is.\nexport function writeFile(path: string, data: u8[]): IoResult {\n  if path.length == 0 {\n    return { code: EINVAL, msg: emptyPathMsg(\"writeFile\") }\n  }\n  const rc = __fs_write__(encodeUtf8(path), data)\n  if rc == 0 { return null }\n  // Negative is `-errno`. A POSITIVE non-zero is a floor protocol violation —\n  // reported as EIO rather than trapped, because a std module has no business\n  // killing the instance over a host that answered out of contract.\n  let code = EIO\n  if rc < 0 { code = 0 - rc }\n  { code: code, msg: failed(\"writeFile\", path, code) }\n}\n\n// `writeTextFile(path, text)` — the same, encoding `text` as UTF-8 first.\n// Encoding cannot fail (`std:utf8`'s header), so this adds no failure mode.\nexport function writeTextFile(path: string, text: string): IoResult {\n  if path.length == 0 {\n    return { code: EINVAL, msg: emptyPathMsg(\"writeTextFile\") }\n  }\n  writeFile(path, encodeUtf8(text))\n}\n\n// `listDir(path)` — the entries of a directory, as NAMES.\n//\n// Names, not paths: that is what the syscall reports, it is what you print, and re-attaching\n// the directory is one `+` (`dir + \"/\" + name`) which the caller can skip when it is about to\n// match on the name. Returning joined paths would be a lossy convenience — you cannot recover\n// the name from a path without a path parser, and `std:fs/path` does not exist yet. `\".\"` and\n// `\"..\"` are NOT included (the host filters them); the order is the host's and is not sorted.\n//\n// A single entry that is not valid UTF-8 fails the WHOLE call with `EILSEQ`. That is\n// deliberate: the alternative is silently dropping a file that exists, which turns a listing\n// into a wrong answer instead of a loud one. The message carries the byte offset within the\n// block so the entry is identifiable.\nexport function listDir(path: string): string[] | IoError {\n  if path.length == 0 { return { code: EINVAL, msg: emptyPathMsg(\"listDir\") } }\n  const block = __fs_list__(encodeUtf8(path))\n  // An EMPTY block is a failure or an empty directory; the errno separates them.\n  if block.length == 0 {\n    const e = emptyErrno()\n    if e != 0 { return { code: e, msg: failed(\"listDir\", path, e) } }\n  }\n  const out: string[] = []\n  let start = 0\n  let i = 0\n  // `i` runs one PAST the end so the final entry — which has no separator after\n  // it — is emitted by the same block as every other. `atSep` is computed in two\n  // steps rather than folded into one `||`, so nothing indexes the array at\n  // `length`.\n  while i <= block.length {\n    let atSep = i == block.length\n    if !atSep { atSep = block[i] == 0x00 }\n    if atSep {\n      // Empty runs are skipped rather than yielded, which makes this agnostic\n      // to whether the host treats 0x00 as a SEPARATOR or a TERMINATOR — a\n      // filename is never empty, so a zero-length run carries no information.\n      if i > start {\n        const name = decodeUtf8At(block, start, i - start)\n        if name is Utf8Error {\n          return {\n            code: EILSEQ,\n            msg: \"fs.listDir \" +\n              path +\n              \": entry at byte \" +\n              toString(start + name.at) +\n              \" is not UTF-8\",\n          }\n        }\n        out.push(name)\n      }\n      start = i + 1\n    }\n    i = i + 1\n  }\n  out\n}\n\n// `pathKind(path)` — what `path` names, or why the question could not be answered.\n//\n// A missing path is an ERROR here (`ENOENT`), not a third `FileKind`: \"there is\n// nothing here\" is not a kind of thing, and folding it into the success arm is\n// what makes callers forget that `EACCES` is also possible. `pathExists` is the\n// function that turns ENOENT into a boolean, and it is separate precisely so\n// that decision is made once and visibly.\nexport function pathKind(path: string): FileKind | IoError {\n  if path.length == 0 { return { code: EINVAL, msg: emptyPathMsg(\"pathKind\") } }\n  const k = __fs_stat__(encodeUtf8(path))\n  if k == 0 { return \"file\" }\n  if k == 1 { return \"dir\" }\n  let code = EIO\n  if k < 0 { code = 0 - k }\n  { code: code, msg: failed(\"pathKind\", path, code) }\n}\n\n// `pathExists(path)` — whether `path` names anything, or why that is unanswerable.\n//\n// `boolean | IoError`, NOT `boolean`, and that is the whole reason the function is worth\n// writing down. \"Does not exist\" and \"you are not allowed to look\" are different facts, and a\n// `boolean` return has to lie about one of them. `Path::exists()` in Rust and `os.path.exists`\n// in Python both answer `false` for a permission error, and both ship a documented footgun\n// where a program creates a file it was told was absent, or reports a config missing when the\n// truth is that the directory is unreadable.\n//\n// So exactly two errnos become `false`, and both mean \"nothing is there\": ENOENT, and ENOTDIR\n// (a component of the path is not a directory, so nothing can be at the end of it). Everything\n// else — EACCES, EPERM, EIO, a loop, a name too long — propagates with its reason intact.\nexport function pathExists(path: string): boolean | IoError {\n  const k = pathKind(path)\n  if k is IoError {\n    if k.code == ENOENT { return false }\n    if k.code == ENOTDIR { return false }\n    return k\n  }\n  true\n}\n",
  "std:json": "// `std:json` — RFC 8259 JSON as a VL value tree, with an I-JSON (RFC 7493)\n// parser and a compact renderer. Text in, `Json` out, and back;\n// `docs/json-design.md` is the specification. THE WHOLE SURFACE IS FOUR NAMES:\n// `Json`, `JsonError`, `parseJson`, `toJson` — see `JsonError` for how a failure\n// is located and which `kind`s each direction produces, `MAX_DEPTH` for the\n// nesting cap and what a cycle does, and `toJson` for what the renderer emits.\n//\n// THE PROFILE IS I-JSON (RFC 7493) MINUS TWO CLAUSES: §2.1's NONCHARACTER half is\n// not enforced (a noncharacter is an ordinary scalar a VL string already holds,\n// where a lone surrogate has no UTF-8 encoding at all — that half IS enforced),\n// and §2.2's precision half is the `f64` rounding below rather than a refusal.\n// Beyond RFC 8259's grammar the parser refuses DUPLICATE MEMBER NAMES (at the\n// second key's opening quote — last-wins hides a producer bug), LONE SURROGATES,\n// a NUMBER OUTSIDE f64 RANGE (so every tree `parseJson` returns, `toJson`\n// renders), RAW CONTROL CHARACTERS and a LEADING BOM; trailing content and an\n// empty body each get their own `syntax` message. `parseF64` IS NOT THE JSON\n// NUMBER GRAMMAR — it takes `01`, `NaN` and `Infinity` and rejects `.5` — so the\n// lexer scans RFC 8259 §6 itself and calls `parseF64` for the CONVERSION alone.\n//\n// TWO SILENTLY LOSSY BEHAVIOURS, both chosen deviations from `std-api-review.md`\n// §2. NUMBERS ARE `f64`, so past the interoperable integer range precision is\n// lost with no error and a 64-bit id does not survive this tree; the exact path\n// is stage 3's `fromJson<T>` reading the lexeme straight to `i64`, and since the\n// lexer already scans the lexeme a `precision` kind stays addable. AND THE TWO\n// STRING ROUTES DISAGREE ON MALFORMED UTF-8: an escape-free literal is one\n// byte-exact `slice`, one with any escape goes through `for cp in …`, which\n// substitutes U+FFFD. Run untrusted bytes through `decodeUtf8` first — it is the\n// one strict decoder, and why v1 takes `string` and not `u8[]`.\n//\n// NOT HERE, EACH WAITING ON A CONSUMER OR A RULING, named so nothing else takes\n// the spelling: `toJsonPretty` (the mode-switch `toJson(v, pretty)` is refused\n// outright, and the indent PARAMETER is deliberately NOT fixed — an `i32` would\n// foreclose tabs forever in a std with no deprecation story), `jsonKind`,\n// `jsonPointer`, `jsonEquals` (absent rather than deferred: `==` over refs is\n// already structural, so compare by rendering until `==` over a struct union\n// lowers), and stage 3's `fromJson<T>` / generic `toJson<T>`, which at `T = Json`\n// IS this `toJson` and so generalises in place. TWO COMPILER GAPS REACH THE\n// CALLER: D1030 — the pair does not compose, read `parseJson`'s note first — and\n// D1050, why `kind` is an INLINE literal set with no alias. The rest shape only\n// the body (D1112/D1161 at `Rend`, D1029, D1009, D1025, D1032, D1034).\n\nimport { parseF64, toString } from \"std:fmt\"\n\n// The value tree: the six JSON types, arms spelled structurally.\n//\n// Objects are VL maps and arrays are VL lists, so `m.has(k)` sits beside\n// `m[k]` and MISSING stays distinguishable from a stored `null` on the tree\n// itself — a distinction any flattening accessor would have to give up.\n//\n// The arms are NOT named (`type JsonObject = { [string]: Json }`), which is\n// what a reader wants and what the compiler refuses today: as a member of the\n// recursive union the checker rejects it, and declared after the tree\n// `let o: JsonObject = Map()` refuses at emit (D1022). An alias is transparent,\n// so adding the two names later changes no program's meaning.\nexport type Json = null | boolean | f64 | string | Json[] | { [string]: Json }\n\n// Why a parse or a render stopped, where, and in which of the four ways.\n//\n// `at` is a byte offset into the parsed text and is `0` on render. `path` is an RFC\n// 6901 pointer (`~` as `~0`, `/` as `~1`) in BOTH directions but not with one meaning:\n// on PARSE it names the CONTAINER being read when the failure fired (`\"/users/3\"`, and\n// `\"\"` before any container opens), on RENDER the OFFENDING VALUE itself. `at` IS IN\n// `[0, length]` INCLUSIVE, so BOUNDS-CHECK before rendering `self[e.at]` or a truncated\n// document traps the error handler. `msg` is prose and is NOT the contract: branch on\n// `kind`, locate with `at` and `path`. `parseJson` produces all four kinds, `toJson`\n// only `depth` and `nonfinite`, so an exhaustive branch sees arms one direction can\n// never return (the `IoError` precedent). `kind` IS A LITERAL UNION, not an `i32` code,\n// so `match` sees the arms; `path` keeps this structurally DISTINCT from `Base64Error`.\nexport type JsonError = {\n  at: i32,\n  kind: \"syntax\" | \"duplicate\" | \"depth\" | \"nonfinite\",\n  path: string,\n  msg: string,\n}\n\n// Container nesting cap, both directions: the parser's input and the renderer's\n// tree. VL is the only surveyed implementation that caps BOTH. This is a STACK\n// BUDGET, not a taste — a parser-shaped frame on this host runs out of stack\n// around a thousand levels and recursive descent spends about two frames per\n// level, so the cap sits well inside the budget and a trap (which no program can\n// handle) becomes an error a caller can read. Re-take the measurement with the\n// real frame before moving it; a limit can be RAISED later and never lowered.\n//\n// A CYCLE IN A PROGRAM-BUILT TREE SURFACES AS `kind: \"depth\"` — the tree can hold\n// one and a naive walk over it traps, so this is what converts that into an\n// error. A PARSED tree cannot contain a cycle. The cap protects `parseJson` and\n// `toJson` and NOTHING A CONSUMER WRITES: a walker over a cyclic tree still traps.\nconst MAX_DEPTH = 128\n\nfunction jsonErr(\n  at: i32,\n  kind: \"syntax\" | \"duplicate\" | \"depth\" | \"nonfinite\",\n  path: string,\n  msg: string,\n): JsonError {\n  { at: at, kind: kind, path: path, msg: msg }\n}\n\n// One RFC 6901 pointer segment. The two escapes are ordered: `~` first, or the\n// `~1` produced from a `/` would itself be re-escaped into `~01`.\nfunction ptrSeg(k: string): string {\n  const out: i32[] = []\n  for cp in k {\n    if cp == 126 {\n      out.push(126)\n      out.push(48)\n    } else {\n      if cp == 47 {\n        out.push(126)\n        out.push(49)\n      } else {\n        out.push(cp)\n      }\n    }\n  }\n  fromCodePoints(out)\n}\n\n// ── the renderer ───────────────────────────────────────────────────────────\n\n// Whether `x` has a JSON spelling. NaN fails its own equality; the infinities\n// are the only finite-comparison failures left once NaN is gone.\nfunction isFiniteF64(x: f64): boolean {\n  if x != x { return false }\n  if x > 1.7976931348623157e308 { return false }\n  if x < -1.7976931348623157e308 { return false }\n  true\n}\n\n// `toString` is ECMA-262 `Number::toString` and is right for every f64 except\n// negative zero, which it prints as `0`. The sign is KEPT: RFC 8259 admits `-0`,\n// Go, serde and Python all round-trip it, and JS alone loses it — `toJson`'s block\n// states the exception, this is why it exists.\nfunction numText(x: f64): string {\n  if x == 0.0 && 1.0 / x < 0.0 { return \"-0\" }\n  toString(x)\n}\n\nfunction hexDigit(v: i32): i32 {\n  if v < 10 { return 48 + v }\n  97 + (v - 10)\n}\n\n// The character that follows the backslash for the five control characters\n// RFC 8259 gives a named escape, or 0 for every other code point. A ladder\n// rather than a lookup because it inverts exactly — `simpleEscape` reads the\n// same five pairs in the parse direction — and two tables that must agree is\n// one more thing to get wrong (`std/base64.vl`'s `b64Char`/`b64Val` rule).\n//\n// `\"` and `\\` are NOT here: they escape to themselves, so the caller writes\n// them without a table.\nfunction namedEscape(cp: i32): i32 {\n  if cp == 8 { return 98 }\n  if cp == 9 { return 116 }\n  if cp == 10 { return 110 }\n  if cp == 12 { return 102 }\n  if cp == 13 { return 114 }\n  0\n}\n\n// `s` as a JSON string literal, quotes included, pushed onto `buf` as code\n// points. `for cp in s` is what makes non-ASCII pass through raw and correct:\n// the code point goes in whole and `fromCodePoints` re-encodes it.\nfunction pushQuoted(buf: i32[], s: string) {\n  buf.push(34)\n  for cp in s {\n    const named = namedEscape(cp)\n    if cp == 34 || cp == 92 {\n      buf.push(92)\n      buf.push(cp)\n    } else {\n      if named != 0 {\n        buf.push(92)\n        buf.push(named)\n      } else {\n        // Everything else below U+0020 has no named escape and takes the\n        // six-character form. Lowercase hex, consistently (RFC 8259 §7 allows\n        // either case).\n        if cp < 32 {\n          buf.push(92)\n          buf.push(117)\n          buf.push(48)\n          buf.push(48)\n          buf.push(hexDigit(cp >> 4))\n          buf.push(hexDigit(cp & 15))\n        } else {\n          buf.push(cp)\n        }\n      }\n    }\n  }\n  buf.push(34)\n}\n\nfunction pushText(buf: i32[], s: string) {\n  for cp in s { buf.push(cp) }\n}\n\n// The walk's failure, carried beside the buffer so `renderInto` can answer a\n// plain `boolean` and every level can prepend its own pointer segment on the way\n// out. It is ONE `JsonError | null`; `at` is not carried separately because a\n// render error's `at` is always 0.\n//\n// ── EVERY READ OF `err` NARROWS IT IN PLACE (`if r.err != null { … r.err … }`)\n// AND NEVER THROUGH A REBIND, here and in `Scan`. Neither rebind spelling runs at\n// every position this module needs (D1112, D1161), and the compiler ACTIVELY\n// suggests the refused one with a `redundant type annotation` hint — so this is\n// not a safe cleanup. ── DO NOT MAKE `renderInto` VOID: it was once, and an\n// `if`/`else` with ONE EMPTY BRANCH in a void function is check-clean and TRAPS\n// (D1034). Two facts keep it away — it is not void, and no branch here is empty.\ntype Rend = { err: JsonError | null }\n\nfunction rendFail(\n  r: Rend,\n  kind: \"syntax\" | \"duplicate\" | \"depth\" | \"nonfinite\",\n  msg: string,\n) {\n  // First failure wins, and a render error's `at` is always 0.\n  if r.err == null { r.err = jsonErr(0, kind, \"\", msg) }\n}\n\n// Re-point a propagating render error one level up. On render `path` names the\n// VALUE, so EVERY level prepends its own segment — which costs nothing on the\n// success path and O(depth) once, on the way out of a failure.\nfunction underSeg(r: Rend, seg: string) {\n  // D1112/D1161: `err` is narrowed IN PLACE here and everywhere else in this\n  // module. Neither rebind spelling runs at both of the positions this module\n  // needs — see the note at `Rend`.\n  if r.err != null { r.err.path = \"/\" + seg + r.err.path }\n}\n\n// Walk `v` into `buf`. Answers whether it was written; `r` carries WHY when it\n// was not. `depth` is the number of containers already open, so the cap is\n// checked as a container is ENTERED.\n//\n// THE `boolean` RESULT IS LOAD-BEARING, and not only for control flow: this\n// function was VOID first and TRAPPED on `unreachable` (D1034, and the note at\n// `Rend`). It also lets every arm exit with a value, which D1032 makes the\n// simpler spelling than a bare `return` in a function whose result type is\n// inferred.\nfunction renderInto(v: Json, buf: i32[], depth: i32, r: Rend): boolean {\n  if v is null {\n    pushText(buf, \"null\")\n    return true\n  }\n  if v is boolean {\n    if v { pushText(buf, \"true\") } else { pushText(buf, \"false\") }\n    return true\n  }\n  if v is f64 {\n    if !isFiniteF64(v) {\n      rendFail(r, \"nonfinite\", \"no JSON spelling for this number\")\n      return false\n    }\n    pushText(buf, numText(v))\n    return true\n  }\n  if v is string {\n    pushQuoted(buf, v)\n    return true\n  }\n  if v is Json[] {\n    if depth + 1 > MAX_DEPTH {\n      rendFail(r, \"depth\", \"nesting exceeds the depth cap\")\n      return false\n    }\n    buf.push(91)\n    let i = 0\n    while i < v.length {\n      if i > 0 { buf.push(44) }\n      if !renderInto(v[i], buf, depth + 1, r) {\n        underSeg(r, toString(i))\n        return false\n      }\n      i = i + 1\n    }\n    buf.push(93)\n    return true\n  }\n  if v is { [string]: Json } {\n    // D1029: an `is`-narrowed MAP arm still carries the union's box at every\n    // delivery position; re-binding it at the arm's OWN type is what unwraps\n    // it. Six of eight positions are check-clean INVALID WASM without this\n    // line, so it is load-bearing and not a style choice.\n    const o: { [string]: Json } = v\n    if depth + 1 > MAX_DEPTH {\n      rendFail(r, \"depth\", \"nesting exceeds the depth cap\")\n      return false\n    }\n    buf.push(123)\n    let first = true\n    let bad = \"\"\n    for k in o {\n      if r.err == null {\n        if !first { buf.push(44) }\n        first = false\n        pushQuoted(buf, k)\n        buf.push(58)\n        // D1009/D1025: the read is hoisted, and it is `Json | null` rather\n        // than `Json`. A key reached by iteration is always present, so the\n        // `null` face is a stored JSON null and renders as one.\n        const mv = o[k]\n        if mv == null {\n          pushText(buf, \"null\")\n        } else {\n          if !renderInto(mv, buf, depth + 1, r) { bad = k }\n        }\n      }\n    }\n    if r.err != null {\n      underSeg(r, ptrSeg(bad))\n      return false\n    }\n    buf.push(125)\n    return true\n  }\n  // Unreachable while `Json` has six arms and all six are above. It is a\n  // FAILURE and not a silent success on purpose: a seventh arm added without a\n  // branch here would otherwise write nothing and let `toJson` return a\n  // document with a value missing, which is the silent-truncation shape this\n  // module exists to avoid. Loud and wrong beats quiet and wrong.\n  rendFail(r, \"nonfinite\", \"no lowering for this Json arm\")\n  false\n}\n\n// `self` as compact RFC 8259 text, or the reason it has none. The two ways it\n// can fail are a number with no JSON spelling (`NaN`, `±Infinity`) and a tree\n// deeper than the cap — which is also how a cycle arrives. Nothing partial is\n// ever returned: the buffer is discarded on failure.\n//\n// NO WHITESPACE AT ALL; pretty printing is a second FUNCTION, never a parameter.\n// Objects render in INSERTION ORDER, because VL maps are, so parse→render is an\n// identity on key order. Numbers go through `toString` (ECMA-262 shortest\n// round-trip) with ONE exception: `-0` keeps its sign. Escapes are the RFC\n// minimum with LOWERCASE hex, `/` is not escaped, and NON-ASCII — U+2028/U+2029\n// included — is emitted RAW as UTF-8, which is safe because a lone surrogate\n// cannot be in a VL string, so the raw path can never emit one.\nexport function toJson(self: Json): string | JsonError {\n  const buf: i32[] = []\n  const r: Rend = { err: null }\n  if !renderInto(self, buf, 0, r) {\n    // D1112/D1161: narrowed in place — see the note at `Rend`.\n    if r.err != null { return r.err }\n    // Unreachable while every `false` from `renderInto` has raised first, and\n    // it carries the same `kind` the pre-D1031 flat carrier's initial values\n    // produced here. It is a failure rather than a partial document on\n    // purpose, and it is a `JsonError` rather than `__trap__` because this\n    // module's whole contract is that neither direction traps — the same\n    // argument the depth cap is built on. `msg` says what happened rather than\n    // being empty, matching `renderInto`'s own seventh-arm floor twenty lines\n    // up; `kind` is the least wrong of four and is not evidence about a cause\n    // nothing here knows.\n    return jsonErr(0, \"nonfinite\", \"\", \"the renderer stopped without raising\")\n  }\n  fromCodePoints(buf)\n}\n\n// ── the parser ─────────────────────────────────────────────────────────────\n\n// Scanner state. The error rides HERE rather than in every return type so the\n// value functions can answer a plain `Json`: a `Json | JsonError` result cannot\n// be narrowed back to a `Json` for a `push` or a map store, because the residue\n// of removing the error arm is the FLATTENED member list and not the registered\n// name (D1030). This is a private carrier, not a second error channel — the\n// surface is `Json | JsonError` in both directions.\n//\n// THE ERROR IS ONE `JsonError | null`, and `parseJson` hands that same object\n// straight back to the caller. Reads of `err` narrow IN PLACE and never through\n// a rebind; the note at `Rend` has the reason (D1112, D1161). `sealed` is how\n// `path` is computed without paying for it on the success path (see `sealErr`);\n// it stays a flat field because it is SCANNER bookkeeping, not part of the error.\ntype Scan = {\n  s: string,\n  i: i32,\n  err: JsonError | null,\n  sealed: boolean,\n}\n\n// The byte at `i`, or -1 at end of input. Every read goes through this: an\n// unguarded `s[i]` past the end TRAPS, and a parser must never trap.\nfunction byteAt(p: Scan, i: i32): i32 {\n  if i < 0 || i >= p.s.length { return -1 }\n  p.s[i]\n}\n\n// Raise from a SCALAR position: the enclosing container owns the pointer, so\n// the error is left unsealed for it to claim. First error wins — a parse stops\n// at the first fault and later positions are not meaningful.\nfunction raise(\n  p: Scan,\n  at: i32,\n  kind: \"syntax\" | \"duplicate\" | \"depth\" | \"nonfinite\",\n  msg: string,\n) {\n  if p.err == null {\n    p.err = jsonErr(at, kind, \"\", msg)\n    p.sealed = false\n  }\n}\n\n// Raise from a CONTAINER's own token stream (a missing `:`, an unterminated\n// array). This container is the one being read, so it claims the pointer here\n// and no ancestor prepends anything below it.\nfunction raiseHere(\n  p: Scan,\n  at: i32,\n  kind: \"syntax\" | \"duplicate\" | \"depth\" | \"nonfinite\",\n  msg: string,\n) {\n  raise(p, at, kind, msg)\n  p.sealed = true\n}\n\n// Called by a container when a CHILD failed. The first container the error\n// passes through IS the container being read when it fired, so it claims the\n// pointer and contributes no segment; every container above it prepends the\n// segment of the child it was parsing. That builds `path` in O(depth) on the\n// failure path and costs nothing on the success path.\nfunction sealErr(p: Scan, seg: string) {\n  // D1112/D1161: narrowed in place — see the note at `Rend`.\n  if p.err != null {\n    if p.sealed { p.err.path = \"/\" + seg + p.err.path } else { p.sealed = true }\n  }\n}\n\nfunction isWs(c: i32): boolean { c == 32 || c == 9 || c == 10 || c == 13 }\n\nfunction skipWs(p: Scan) {\n  while p.i < p.s.length && isWs(p.s[p.i]) { p.i = p.i + 1 }\n}\n\nfunction isDigit(c: i32): boolean { c >= 48 && c <= 57 }\n\nfunction hexVal(c: i32): i32 {\n  if c >= 48 && c <= 57 { return c - 48 }\n  if c >= 97 && c <= 102 { return c - 97 + 10 }\n  if c >= 65 && c <= 70 { return c - 65 + 10 }\n  -1\n}\n\n// The four hex digits of a `\\uXXXX` at `p.i`, or -1. Does not advance.\nfunction hex4(p: Scan): i32 {\n  let v = 0\n  let k = 0\n  while k < 4 {\n    const d = hexVal(byteAt(p, p.i + k))\n    if d < 0 { return -1 }\n    v = v * 16 + d\n    k = k + 1\n  }\n  v\n}\n\n// The code point a one-character escape names, or -1 if it names none. `/` is\n// escapable on input even though the renderer never escapes it — RFC 8259\n// allows `\\/` and every producer that HTML-escapes emits it. The five control\n// escapes here are the same five `namedEscape` writes in the render direction,\n// read backwards.\nfunction simpleEscape(e: i32): i32 {\n  if e == 34 { return 34 }\n  if e == 92 { return 92 }\n  if e == 47 { return 47 }\n  if e == 98 { return 8 }\n  if e == 102 { return 12 }\n  if e == 110 { return 10 }\n  if e == 114 { return 13 }\n  if e == 116 { return 9 }\n  -1\n}\n\n// A `\\uXXXX` escape whose backslash is at `esc` and whose `u` has just been\n// consumed. Pushes one code point, combining a surrogate PAIR into the single\n// character it names. Answers whether it succeeded.\nfunction pUnicodeEscape(p: Scan, buf: i32[], esc: i32): boolean {\n  const hi = hex4(p)\n  if hi < 0 {\n    raise(p, esc, \"syntax\", \"\\\\u needs four hex digits\")\n    return false\n  }\n  p.i = p.i + 4\n  if hi >= 55296 && hi <= 56319 {\n    // A high surrogate is text only as the first half of a pair, and the\n    // second half has to be spelled as its own escape.\n    if byteAt(p, p.i) != 92 || byteAt(p, p.i + 1) != 117 {\n      raise(p, esc, \"syntax\", \"lone high surrogate escape\")\n      return false\n    }\n    p.i = p.i + 2\n    const lo = hex4(p)\n    if lo < 0 {\n      raise(p, esc, \"syntax\", \"\\\\u needs four hex digits\")\n      return false\n    }\n    if lo < 56320 || lo > 57343 {\n      raise(p, esc, \"syntax\", \"high surrogate not followed by a low surrogate\")\n      return false\n    }\n    p.i = p.i + 4\n    buf.push(65536 + ((hi - 55296) * 1024) + (lo - 56320))\n    return true\n  }\n  if hi >= 56320 && hi <= 57343 {\n    raise(p, esc, \"syntax\", \"lone low surrogate escape\")\n    return false\n  }\n  buf.push(hi)\n  true\n}\n\n// A JSON string literal starting at the opening quote. Returns the decoded\n// value; on failure sets the scanner's error and returns `\"\"`.\n//\n// TWO ROUTES, and the header says why: with NO escape the value is one\n// byte-exact `slice`; the first escape switches it onto a code-point buffer,\n// which is exact for well-formed UTF-8 and substitutes U+FFFD for a malformed\n// byte the slice route would have passed through. That disagreement is real,\n// documented at the top of this file, and is the price of not carrying a second\n// UTF-8 decoder.\nfunction pString(p: Scan): string {\n  p.i = p.i + 1\n  const start = p.i\n  const buf: i32[] = []\n  let escaped = false\n  let runStart = start\n  let out = \"\"\n  let done = false\n  while !done {\n    const c = byteAt(p, p.i)\n    if c < 0 {\n      raise(p, p.s.length, \"syntax\", \"unterminated string\")\n      return \"\"\n    }\n    if c < 32 {\n      raise(p, p.i, \"syntax\", \"raw control character in a string\")\n      return \"\"\n    }\n    if c == 34 {\n      // With no escape anywhere, the value IS the input's bytes and one slice\n      // delivers them; nothing is decoded and nothing is re-encoded.\n      if escaped {\n        for cp in p.s.slice(runStart, p.i) { buf.push(cp) }\n        out = fromCodePoints(buf)\n      } else {\n        out = p.s.slice(start, p.i)\n      }\n      p.i = p.i + 1\n      done = true\n    } else {\n      if c == 92 {\n        // The first escape switches this literal onto the buffer route; the\n        // raw run before it is carried across as code points.\n        escaped = true\n        for cp in p.s.slice(runStart, p.i) { buf.push(cp) }\n        const esc = p.i\n        p.i = p.i + 1\n        const e = byteAt(p, p.i)\n        const simple = simpleEscape(e)\n        if simple >= 0 {\n          buf.push(simple)\n          p.i = p.i + 1\n        } else {\n          if e != 117 {\n            raise(p, esc, \"syntax\", \"unknown escape\")\n            return \"\"\n          }\n          p.i = p.i + 1\n          if !pUnicodeEscape(p, buf, esc) { return \"\" }\n        }\n        runStart = p.i\n      } else {\n        p.i = p.i + 1\n      }\n    }\n  }\n  out\n}\n\n// A number lexeme validated against RFC 8259 §6 BY HAND, then converted.\n// `parseF64` is the conversion and never the gate — it accepts `01`, `NaN` and\n// `Infinity`, which JSON does not.\nfunction pNumber(p: Scan): Json {\n  const start = p.i\n  if byteAt(p, p.i) == 45 { p.i = p.i + 1 }\n  const intStart = p.i\n  if byteAt(p, p.i) == 48 {\n    p.i = p.i + 1\n    if isDigit(byteAt(p, p.i)) {\n      raise(p, intStart, \"syntax\", \"a number may not have a leading zero\")\n      return null\n    }\n  } else {\n    if !isDigit(byteAt(p, p.i)) {\n      raise(p, p.i, \"syntax\", \"a number needs a digit\")\n      return null\n    }\n    while isDigit(byteAt(p, p.i)) { p.i = p.i + 1 }\n  }\n  if byteAt(p, p.i) == 46 {\n    p.i = p.i + 1\n    if !isDigit(byteAt(p, p.i)) {\n      raise(p, p.i, \"syntax\", \"a fraction needs a digit after the point\")\n      return null\n    }\n    while isDigit(byteAt(p, p.i)) { p.i = p.i + 1 }\n  }\n  const e = byteAt(p, p.i)\n  if e == 101 || e == 69 {\n    p.i = p.i + 1\n    const sign = byteAt(p, p.i)\n    if sign == 43 || sign == 45 { p.i = p.i + 1 }\n    if !isDigit(byteAt(p, p.i)) {\n      raise(p, p.i, \"syntax\", \"an exponent needs a digit\")\n      return null\n    }\n    while isDigit(byteAt(p, p.i)) { p.i = p.i + 1 }\n  }\n  const lex = p.s.slice(start, p.i)\n  const v = parseF64(lex)\n  if v == null {\n    // Defensive: the scan above accepts a subset of what `parseF64` does.\n    raise(p, start, \"syntax\", \"not a number\")\n    return null\n  }\n  if !isFiniteF64(v) {\n    raise(p, start, \"nonfinite\", \"number out of range for a double\")\n    return null\n  }\n  v\n}\n\n// `word` at `p.i`, consumed. The three JSON literals are the only keywords.\nfunction eatWord(p: Scan, word: string): boolean {\n  let k = 0\n  while k < word.length {\n    if byteAt(p, p.i + k) != word[k] { return false }\n    k = k + 1\n  }\n  p.i = p.i + word.length\n  true\n}\n\nfunction pArray(p: Scan, depth: i32): Json {\n  if depth + 1 > MAX_DEPTH {\n    raiseHere(p, p.i, \"depth\", \"nesting exceeds the depth cap\")\n    return null\n  }\n  p.i = p.i + 1\n  const a: Json[] = []\n  skipWs(p)\n  if byteAt(p, p.i) == 93 {\n    p.i = p.i + 1\n    return a\n  }\n  while true {\n    skipWs(p)\n    const v = pValue(p, depth + 1)\n    if p.err != null {\n      sealErr(p, toString(a.length))\n      return null\n    }\n    a.push(v)\n    skipWs(p)\n    const c = byteAt(p, p.i)\n    if c == 44 {\n      p.i = p.i + 1\n      skipWs(p)\n      if byteAt(p, p.i) == 93 {\n        raiseHere(p, p.i, \"syntax\", \"trailing comma in an array\")\n        return null\n      }\n    } else {\n      if c == 93 {\n        p.i = p.i + 1\n        return a\n      }\n      if c < 0 {\n        raiseHere(p, p.s.length, \"syntax\", \"unexpected end of input\")\n        return null\n      }\n      raiseHere(p, p.i, \"syntax\", \"expected ',' or ']' in an array\")\n      return null\n    }\n  }\n  null\n}\n\nfunction pObject(p: Scan, depth: i32): Json {\n  if depth + 1 > MAX_DEPTH {\n    raiseHere(p, p.i, \"depth\", \"nesting exceeds the depth cap\")\n    return null\n  }\n  p.i = p.i + 1\n  const o: { [string]: Json } = Map()\n  skipWs(p)\n  if byteAt(p, p.i) == 125 {\n    p.i = p.i + 1\n    return o\n  }\n  while true {\n    skipWs(p)\n    const keyAt = p.i\n    if byteAt(p, p.i) != 34 {\n      raiseHere(p, p.i, \"syntax\", \"expected a '\\\"'-quoted member name\")\n      return null\n    }\n    const k = pString(p)\n    if p.err != null {\n      sealErr(p, \"\")\n      return null\n    }\n    // I-JSON (RFC 7493 §2.3) and serde ruling A: a repeat is refused, and `at`\n    // points at the SECOND occurrence.\n    if o.has(k) {\n      raiseHere(p, keyAt, \"duplicate\", \"duplicate member name\")\n      return null\n    }\n    skipWs(p)\n    if byteAt(p, p.i) != 58 {\n      raiseHere(p, p.i, \"syntax\", \"expected ':' after a member name\")\n      return null\n    }\n    p.i = p.i + 1\n    skipWs(p)\n    const v = pValue(p, depth + 1)\n    if p.err != null {\n      sealErr(p, ptrSeg(k))\n      return null\n    }\n    o[k] = v\n    skipWs(p)\n    const c = byteAt(p, p.i)\n    if c == 44 {\n      p.i = p.i + 1\n      skipWs(p)\n      if byteAt(p, p.i) == 125 {\n        raiseHere(p, p.i, \"syntax\", \"trailing comma in an object\")\n        return null\n      }\n    } else {\n      if c == 125 {\n        p.i = p.i + 1\n        return o\n      }\n      if c < 0 {\n        raiseHere(p, p.s.length, \"syntax\", \"unexpected end of input\")\n        return null\n      }\n      raiseHere(p, p.i, \"syntax\", \"expected ',' or '}' in an object\")\n      return null\n    }\n  }\n  null\n}\n\nfunction pValue(p: Scan, depth: i32): Json {\n  const c = byteAt(p, p.i)\n  if c < 0 {\n    raise(p, p.s.length, \"syntax\", \"unexpected end of input\")\n    return null\n  }\n  if c == 123 { return pObject(p, depth) }\n  if c == 91 { return pArray(p, depth) }\n  if c == 34 { return pString(p) }\n  if c == 45 || isDigit(c) { return pNumber(p) }\n  if c == 116 {\n    if eatWord(p, \"true\") { return true }\n    raise(p, p.i, \"syntax\", \"expected 'true'\")\n    return null\n  }\n  if c == 102 {\n    if eatWord(p, \"false\") { return false }\n    raise(p, p.i, \"syntax\", \"expected 'false'\")\n    return null\n  }\n  if c == 110 {\n    if eatWord(p, \"null\") { return null }\n    raise(p, p.i, \"syntax\", \"expected 'null'\")\n    return null\n  }\n  raise(p, p.i, \"syntax\", \"unexpected byte where a value was expected\")\n  null\n}\n\n// A parsed `Json` re-delivered as `Json | JsonError`. The whole ladder exists\n// because the alias is not a member of its own composition: `return v` for a\n// `v: Json` is `expected Json | JsonError, got Json`, so each arm is handed\n// over at its own spelling. The map arm additionally needs the D1029 re-bind —\n// without it this function is check-clean INVALID WASM.\nfunction asResult(v: Json): Json | JsonError {\n  if v is boolean { return v }\n  if v is f64 { return v }\n  if v is string { return v }\n  if v is Json[] { return v }\n  if v is { [string]: Json } {\n    const o: { [string]: Json } = v\n    return o\n  }\n  null\n}\n\n// The `Json` `self` holds, or why it is not JSON. See the module header for the\n// profile. A parse NEVER TRAPS and never returns a partial tree.\n//\n// ── READ THIS BEFORE WRITING A CONSUMER: THE RESULT DOES NOT FLOW BACK INTO\n// `toJson` YET (D1030). Narrowing away `JsonError` leaves the FLATTENED member\n// list rather than the name `Json`, so `toJson(r)`, `r.toJson()` and\n// `const v: Json = r` are all refused at CHECK — loud, but none of them compiles.\n// Narrow to the ONE arm you want instead (re-binding a map arm at its own type,\n// D1029), or re-deliver each arm at its own spelling, the ladder `asResult` uses.\n// AND ONE A WALKER TRIPS ON (D1033): a string INDEX handed straight to a\n// value-union parameter — `k[i].toString()` — is check-clean INVALID WASM when\n// `k` was narrowed out of `Json`; hoist it as `const b: i32 = k[i]` first.\nexport function parseJson(self: string): Json | JsonError {\n  // The BOM is the one input where the byte the user sees and the byte the\n  // parser sees differ, so it is named rather than reported as a stray byte.\n  if self.length >= 3 && self[0] == 239 && self[1] == 187 && self[2] == 191 {\n    return jsonErr(0, \"syntax\", \"\", \"leading byte-order mark\")\n  }\n  const p: Scan = { s: self, i: 0, err: null, sealed: false }\n  skipWs(p)\n  if p.i >= self.length {\n    return jsonErr(self.length, \"syntax\", \"\", \"unexpected end of input\")\n  }\n  const v = pValue(p, 0)\n  // D1112/D1161: narrowed in place — see the note at `Rend`. Since D1031 closed\n  // this is the SAME object the scanner raised, not a copy of its fields.\n  if p.err != null { return p.err }\n  skipWs(p)\n  if p.i < self.length {\n    return jsonErr(\n      p.i,\n      \"syntax\",\n      \"\",\n      \"trailing content after the top-level value\",\n    )\n  }\n  asResult(v)\n}\n",
  "std:seed": "// `std:seed` — a trivial module whose only job is to prove the `std:`\n// resolution plumbing end to end (both resolvers, the Rust host's std-dir\n// mapping, the CLI's fsRead wrap, the LSP's embedded map). Real std content\n// (`std:fmt`, `std:test`, collections) lands in later slices\n// (docs/std-design.md D4); this file can be retired once any of them exists.\nexport function stdSmoke() { return 7 }\n",
  "std:str": "// `std:str` — the string method surface VL's core does not have.\n//\n// The core has `slice`, `indexOf`, `includes`, `charCodeAt` and `fromCodePoint`, plus `+`,\n// `==`, `.length`, `s[i]` and `for cp in s`; splitting, trimming, replacing and the ends-with\n// questions are missing (`docs/guide/strings-design.md` §Methods, step 1). All of it is\n// expressible over those primitives, so none needs the emitter, an intrinsic or a rep change.\n// SELF-FIRST, so every export is a UFCS METHOD (`self` is the switch, B14); `join` alone takes\n// a `string[]` receiver, which is the shape of the operation and what `std:fmt` spelled.\n//\n// EVERY BUILDER HERE FILLS A CODE-POINT BUFFER — READ THIS BEFORE EDITING. `let s = \"\"` then\n// `s = s + piece` in a loop is QUADRATIC on this compiler: no accumulation fusion in the\n// native emitter, and `tests/cases/strings/accum-*.vl` asserts only the RESULT, so it is blind\n// to the cost class. An `i32[]` GROWS (amortized push); a `string` does not, since `s + c`\n// copies the whole left operand — two `+`s splicing ONE result (`replace`) are fine, O(n) once\n// and not O(n) per element. The second half of the rule is the UNIT: what enters the buffer is\n// a CODE POINT, by `for cp in s` and NEVER by `s[i]` — `fromCodePoints` reads code points (its\n// name is its contract) while `s[i]` is a BYTE, so a byte pushed in comes back out as a\n// different character. `pushStr` enforces it file-wide (`docs/internals/str-byte-semantics.md`).\n//\n// ASCII IS IN THE NAME WHERE ASCII IS THE BEHAVIOUR: an unqualified `toUpper` that silently\n// leaves `é` alone is the quiet-lie class VL rejects, and full case mapping needs Unicode\n// tables (a future `std:unicode`). `trim` is ASCII-only and NOT named for it — an OPEN RULING,\n// since JS, Python, Rust and Go all strip U+00A0 (§R3 of that audit has both arguments).\n//\n// THE DEGENERATE INPUTS ARE RULED, NOT LEFT TO FALL OUT, and the rule is FOLLOW THE UNANIMOUS\n// PRECEDENT — `DECISIONS.md` already put the core's string methods in the JS camp, and a std\n// module disagreeing with its own core would be the seam this language avoids. Every export\n// documents its own edges below and is pinned by a fixture. THE ONE LAW is\n// `s.replaceAll(f, t) == s.split(f).join(t)` for a NON-EMPTY `f`, which is why the two share\n// `findFrom` and consume matches left to right without overlap; for an empty `f` it cannot hold.\n//\n// WHAT THIS MODULE DOES NOT DO. No regex or pattern argument (`std:regex` is its own module),\n// and no `splitN`/`rsplit`/`trimPrefix`/`replaceFrom(i)`: `docs/internals/std-design.md` D2's\n// admission principle is that nothing lands without a caller in this tree. No `contains`,\n// `indexOf` or `slice` either — core builtins, and with no namespace import a program\n// importing both names takes a hard duplicate-binding parse error, which is also why `std:fmt`\n// re-exports `split`/`join`/`repeat` from here and calls `padStart` for its `padLeft`, leaving\n// one implementation of each. And NO UNIT CONVERSION — every index is the core's index unit,\n// produced by `indexOf`/`length` and consumed by `slice`/`matchAt`, so they cancel; the unit\n// is NAMED in two places, both ruled CODE POINTS: the builder buffer and `len` (§R1).\n\n// ── the shared cores ───────────────────────────────────────────────────────\n\n// Whether `needle` occurs at index `at`. The one comparison primitive: every\n// search in this file (`findFrom`, `lastIndexOf`, `startsWith`, `endsWith`)\n// is a policy about WHICH `at` to try, and none of them re-spells the compare.\n//\n// It reads element by element rather than `self.slice(at, at + needle.length)\n// == needle` because the slice ALLOCATES — an allocation per candidate position\n// turns every search in the module into garbage pressure proportional to the\n// haystack. An out-of-range `at` (negative, or a needle that would run off the\n// end) is `false`, not a trap, so callers may hand it an unchecked offset;\n// `endsWith` relies on that for a suffix longer than the string.\nfunction matchAt(self: string, needle: string, at: i32): boolean {\n  if at < 0 { return false }\n  if at + needle.length > self.length { return false }\n  let i = 0\n  while i < needle.length {\n    if self[i + at] != needle[i] { return false }\n    i = i + 1\n  }\n  true\n}\n\n// The index of the first occurrence of `needle` at or after `from`, or -1.\n//\n// The core's `indexOf` takes no start offset (checked: `typecheck.vl` types it\n// at exactly one argument), which is the reason this exists — a scan that\n// resumes is what `split` and `replaceAll` are made of.\n//\n// An EMPTY needle is found immediately at `from`, matching the core's\n// `indexOf(\"\") == 0`; `from` past the end yields -1 for a non-empty needle and\n// `from` itself for an empty one, which is what makes the empty case terminate\n// in callers that advance by `needle.length` — they must, and do, special-case\n// it instead.\nfunction findFrom(self: string, needle: string, from: i32): i32 {\n  let i = from\n  if i < 0 { i = 0 }\n  const last = self.length - needle.length\n  while i <= last {\n    if matchAt(self, needle, i) { return i }\n    i = i + 1\n  }\n  -1\n}\n\n// Append every code point of `s` to `buf`. The single copy primitive of this module — see the\n// header: `buf` GROWS (amortized push), a string would be COPIED WHOLE per append.\n//\n// IT ITERATES RATHER THAN INDEXES, AND THAT IS LOAD-BEARING, NOT STYLE. `buf` is drained by\n// `fromCodePoints`, whose contract is fixed by its name: each `i32` is a CODE POINT. `for cp\n// in s` yields code points too, so producer and consumer are a matched pair whose meanings\n// move together. `buf.push(s[i])` would not be: `s[i]` is a BYTE, so pushing the two bytes of\n// `é` into a code-point buffer re-encodes them as two separate characters, and every builder\n// in this file (`join`, `replaceAll`, `repeat`, `padFill`, `mapAsciiCase`) would ship\n// mojibake. See `docs/internals/str-byte-semantics.md` §Builders.\nfunction pushStr(buf: i32[], s: string) {\n  for cp in s { buf.push(cp) }\n}\n\n// Append `s[lo..hi)` to `buf`. `lo` is clamped up to 0 and `hi` down to the\n// end, so a caller may pass an empty or inverted range.\n//\n// The clamp on `lo` is EXPLICIT and not delegated to `slice`, because VL's\n// `slice` reads a negative index as JS does — from the END (`\"abc\".slice(-1, 3)`\n// is `\"c\"`, checked) — which is the opposite of the \"clamp to the start\" this\n// helper promises. `hi` needs no such care: an over-long `hi` clamps the same\n// way in both.\nfunction pushRange(buf: i32[], s: string, lo: i32, hi: i32) {\n  let start = lo\n  if start < 0 { start = 0 }\n  pushStr(buf, s.slice(start, hi))\n}\n\n// The six ASCII whitespace characters — space, tab, newline, vertical tab, form\n// feed, carriage return.\n//\n// Whether the set SHOULD stop at ASCII is an open owner ruling: the header\n// records the correction (all four of JS, Python, Rust and Go strip Unicode\n// spaces such as NBSP; Go's six are a fast path, not its definition) and\n// `docs/internals/str-byte-semantics.md` §R3 has the options. It is\n// rep-INDEPENDENT — a byte test for a value below 0x80 stays exactly correct\n// after the UTF-8 swap, because no byte of a multi-byte sequence is ever that\n// low — so nothing about the migration forces the question either way.\nfunction isSpace(c: i32): boolean {\n  c == ' ' || c == '\\t' || c == '\\n' || c == '\\v' || c == '\\f' || c == '\\r'\n}\n\n// The index of the first non-whitespace character, or `self.length` when there\n// is none (an all-blank string, which includes the empty one).\nfunction spanStart(self: string): i32 {\n  let i = 0\n  while i < self.length {\n    if !isSpace(self[i]) { return i }\n    i = i + 1\n  }\n  self.length\n}\n\n// One PAST the index of the last non-whitespace character, or 0 when there is\n// none. Paired with `spanStart` these bound the trimmed span as a half-open\n// `[a, b)` — and on an all-blank string they cross (`a == length`, `b == 0`),\n// which the callers handle explicitly rather than leaning on `slice`'s clamp.\nfunction spanEnd(self: string): i32 {\n  let i = self.length\n  while i > 0 {\n    if !isSpace(self[i - 1]) { return i }\n    i = i - 1\n  }\n  0\n}\n\n// ── searching ──────────────────────────────────────────────────────────────\n\n// Whether `self` begins with `prefix`. An empty prefix is always present\n// (every string begins with nothing), a prefix longer than `self` never is.\nexport function startsWith(self: string, prefix: string): boolean {\n  matchAt(self, prefix, 0)\n}\n\n// Whether `self` ends with `suffix`. An empty suffix is always present; a\n// suffix longer than `self` computes a NEGATIVE offset, which `matchAt` refuses\n// rather than trapping — that is the reason for its `at < 0` guard.\nexport function endsWith(self: string, suffix: string): boolean {\n  matchAt(self, suffix, self.length - suffix.length)\n}\n\n// The index of the LAST occurrence of `needle`, or -1 when absent — the missing\n// counterpart to the core's `indexOf`, and it keeps `indexOf`'s -1 convention\n// rather than inventing a `i32 | null` the core would disagree with.\n//\n// Scanning DOWN from the last position a match could start at means the first\n// hit is the answer, so no candidate is examined twice. An empty needle\n// returns `self.length` (it occurs at the boundary after the last character,\n// which is the last of the `length + 1` places it occurs) — the mirror of\n// `indexOf(\"\") == 0`, and what JS, Python, Rust and Go all report.\n// Occurrences may overlap here, unlike in `split`/`replaceAll`, because a\n// single position is being reported rather than a sequence consumed:\n// `\"aaa\".lastIndexOf(\"aa\")` is 1.\nexport function lastIndexOf(self: string, needle: string): i32 {\n  let i = self.length - needle.length\n  while i >= 0 {\n    if matchAt(self, needle, i) { return i }\n    i = i - 1\n  }\n  -1\n}\n\n// ── splitting and joining ──────────────────────────────────────────────────\n\n// The pieces of `self` between each occurrence of `sep`, left to right.\n//\n// The result ALWAYS has one more element than `sep` has occurrences, and every edge follows:\n// a separator at the very START gives a leading empty piece, at the very END a trailing one,\n// ADJACENT separators an empty piece between them, a separator that never occurs the whole\n// string as one piece, and an empty input therefore one empty piece (`\"\".split(\",\")` is\n// `[\"\"]`). Matches do not OVERLAP: consumed left to right, `\"aaa\".split(\"aa\")` is `[\"\", \"a\"]`.\n//\n// An EMPTY separator is the one case outside that rule: it splits into single CODE POINTS, so\n// `\"abc\".split(\"\")` is `[\"a\",\"b\",\"c\"]` and `\"\".split(\"\")` is `[]`, an EMPTY list. The loop\n// iterates rather than indexes so `\"é\".split(\"\")` stays one piece, as Go and the rest agree;\n// the byte-boundary reading is an OPEN RULING in `docs/internals/str-byte-semantics.md` §R2.\nexport function split(self: string, sep: string): string[] {\n  const out: string[] = []\n  if sep.length == 0 {\n    for cp in self { out.push(fromCodePoint(cp)) }\n    return out\n  }\n  let start = 0\n  let at = findFrom(self, sep, 0)\n  while at >= 0 {\n    out.push(self.slice(start, at))\n    start = at + sep.length\n    at = findFrom(self, sep, start)\n  }\n  out.push(self.slice(start, self.length))\n  out\n}\n\n// The elements of `self` concatenated with `sep` between each adjacent pair — `split`'s\n// inverse, with a `string[]` receiver because that is what the operation is ON.\n//\n// An empty list joins to `\"\"` and a one-element list to that element, both without touching\n// `sep` — so `[\"\"].join(\",\")` is `\"\"` and `[\"\", \"\"].join(\"-\")` is `\"-\"`, one separator for the\n// one gap. There is never a trailing separator.\n//\n// ONE BUFFER, ONE `fromCodePoints`: the `out = out + parts[i]` spelling of this function is\n// the exact loop that went quadratic and blew the compiler's non-freeing heap (see\n// `compiler/fmt_util.vl`'s `joinLinesRange`), so the two spellings are complexity classes\n// apart rather than a tuning difference. The zero- and one-element early returns are not\n// micro-optimization either: they make joining a one-piece list allocation-free.\nexport function join(self: string[], sep: string): string {\n  if self.length == 0 { return \"\" }\n  if self.length == 1 { return self[0] }\n  const buf: i32[] = []\n  let i = 0\n  while i < self.length {\n    if i > 0 { pushStr(buf, sep) }\n    pushStr(buf, self[i])\n    i = i + 1\n  }\n  fromCodePoints(buf)\n}\n\n// ── replacing ──────────────────────────────────────────────────────────────\n\n// `self` with the FIRST occurrence of `from` replaced by `to`. When `from` does\n// not occur, `self` comes back unchanged and untouched — the same object, no\n// allocation.\n//\n// An EMPTY `from` occurs at index 0 (the core's own `indexOf(\"\") == 0` rule),\n// so `\"abc\".replace(\"\", \"-\")` is `\"-abc\"`: `to` is prepended. JS, Python and\n// Rust all produce that exact string.\n//\n// Two `+`s and no buffer, deliberately: this splices at ONE point, so it is a\n// pair of O(n) copies rather than the O(n)-per-element accumulator the header\n// warns about. `replaceAll` cannot say the same and does not try.\nexport function replace(self: string, from: string, to: string): string {\n  const at = findFrom(self, from, 0)\n  if at < 0 { return self }\n  self.slice(0, at) + to + self.slice(at + from.length, self.length)\n}\n\n// `self` with EVERY occurrence of `from` replaced by `to`. A `from` that never occurs returns\n// `self` unchanged with nothing allocated, checked BEFORE the buffer is built.\n//\n// Matches are consumed left to right and never overlap, because the scan resumes PAST the\n// match it just took: `\"aaa\".replaceAll(\"aa\", \"b\")` is `\"ba\"`. That is `split`'s consumption\n// rule, and it is what makes the header's law hold on exactly these awkward inputs. A `to`\n// that CONTAINS `from` is not rescanned, so `\"a\".replaceAll(\"a\", \"aa\")` terminates at `\"aa\"`.\n//\n// An EMPTY `from` matches at every CODE-POINT boundary — before the first character, between\n// each pair, after the last — so `\"abc\".replaceAll(\"\", \"-\")` is `\"-a-b-c-\"`. That is JS,\n// Python, Rust and Go verbatim, and the one input where the law does not hold; the loop\n// iterates, so `to` lands between CHARACTERS (`docs/internals/str-byte-semantics.md` §R2).\nexport function replaceAll(self: string, from: string, to: string): string {\n  const buf: i32[] = []\n  if from.length == 0 {\n    for cp in self {\n      pushStr(buf, to)\n      buf.push(cp)\n    }\n    pushStr(buf, to)\n    return fromCodePoints(buf)\n  }\n  let at = findFrom(self, from, 0)\n  if at < 0 { return self }\n  let start = 0\n  while at >= 0 {\n    pushRange(buf, self, start, at)\n    pushStr(buf, to)\n    start = at + from.length\n    at = findFrom(self, from, start)\n  }\n  pushRange(buf, self, start, self.length)\n  fromCodePoints(buf)\n}\n\n// ── trimming ───────────────────────────────────────────────────────────────\n\n// `self` without leading ASCII whitespace. An all-blank string trims to `\"\"`;\n// a string with nothing to remove comes back unchanged and unallocated.\nexport function trimStart(self: string): string {\n  const a = spanStart(self)\n  if a == 0 { return self }\n  if a == self.length { return \"\" }\n  return self.slice(a, self.length)\n}\n\n// `self` without trailing ASCII whitespace. All-blank trims to `\"\"`.\nexport function trimEnd(self: string): string {\n  const b = spanEnd(self)\n  if b == self.length { return self }\n  if b == 0 { return \"\" }\n  return self.slice(0, b)\n}\n\n// `self` without leading or trailing ASCII whitespace — interior whitespace is\n// UNTOUCHED (`\" a b \".trim()` is `\"a b\"`, not `\"ab\"`).\n//\n// This is not `trimStart(trimEnd(self))`: that spelling allocates an\n// intermediate string for the common case where both ends need work. One pass\n// for each bound, one slice. The all-blank case is checked FIRST because the\n// two bounds cross there (`spanStart` reports `length`, `spanEnd` reports 0),\n// and leaning on `slice`'s start >= end clamp to paper over it would be relying\n// on a clamp to express an intent.\nexport function trim(self: string): string {\n  const a = spanStart(self)\n  if a == self.length { return \"\" }\n  const b = spanEnd(self)\n  if a == 0 && b == self.length { return self }\n  return self.slice(a, b)\n}\n\n// ── building ───────────────────────────────────────────────────────────────\n\n// `self` concatenated `n` times. `n <= 0` yields `\"\"` — a negative count is\n// treated as zero rather than trapping, because \"repeat this negative-one\n// times\" is a computed count that came out empty, not a bug in the program.\n// (JS throws a RangeError here; Rust and Go's `strings.Repeat` panic. VL's\n// error-handling design reserves traps for bugs, and the useful reading of a\n// count that fell below zero is an empty result.)\nexport function repeat(self: string, n: i32): string {\n  if n <= 0 { return \"\" }\n  if n == 1 { return self }\n  if self.length == 0 { return \"\" }\n  const buf: i32[] = []\n  let i = 0\n  while i < n {\n    pushStr(buf, self)\n    i = i + 1\n  }\n  fromCodePoints(buf)\n}\n\n// Exactly `n` CODE POINTS of `pad`, tiled and truncated wherever the tiling lands —\n// `padFill(3, \"ab\")` is `\"aba\"`. `n <= 0` or an empty `pad` yields `\"\"`, which is what lets\n// both padders return their input untouched without special-casing the degenerate arguments\n// twice. Truncating mid-tile rather than refusing a multi-character pad is what JS does, and\n// it is what makes the result EXACTLY `len` wide — a column that is sometimes one unit wider\n// is not a column.\n//\n// THE UNIT IS CODE POINTS, RULED (§R1 of `docs/internals/str-byte-semantics.md`): no surveyed\n// language measures padding in bytes except C, and Go went out of its way to differ from C on\n// exactly this point. §API's \"one coordinate system\" does not reach here, because that is\n// about OFFSETS and `len` is a WIDTH. Tiling from a code-point vector also cannot cut a\n// multi-byte pad mid-character, which the old `slice` truncation could.\nfunction padFill(n: i32, pad: string): string {\n  if n <= 0 { return \"\" }\n  const tile: i32[] = []\n  for cp in pad { tile.push(cp) }\n  if tile.length == 0 { return \"\" }\n  const buf: i32[] = []\n  let i = 0\n  while i < n {\n    buf.push(tile[i % tile.length])\n    i = i + 1\n  }\n  fromCodePoints(buf)\n}\n\n// `self` padded on the LEFT with `pad` until it is `len` long.\n//\n// Returns `self` untouched when it is already `len` wide or wider — padding never TRUNCATES,\n// so `\"hello\".padStart(3, \"0\")` is `\"hello\"`, not `\"hel\"`. That is JS's rule and the only safe\n// one: a padder that shortened its input would silently destroy data in exactly the logging\n// and table-formatting code that calls it. An empty `pad` is likewise a no-op rather than an\n// infinite loop.\n//\n// `len` COUNTS CODE POINTS (§R1, ruled — see `padFill`), so the width is measured with\n// `cpLen()` and not `.length`. That is O(n), and naming it at the call site is §Codepoints'\n// own principle satisfied. Code points are still not DISPLAY width — a CJK character is two\n// columns — and grapheme- or width-correct padding belongs to `std:unicode`.\nexport function padStart(self: string, len: i32, pad: string): string {\n  const fill = padFill(len - self.cpLen(), pad)\n  if fill.length == 0 { return self }\n  fill + self\n}\n\n// `self` padded on the RIGHT with `pad` until it is `len` wide. Same rules as\n// `padStart`: never truncates, empty `pad` is a no-op, `len` counts CODE POINTS,\n// and the result is exactly `len` code points wide whenever padding happened.\nexport function padEnd(self: string, len: i32, pad: string): string {\n  const fill = padFill(len - self.cpLen(), pad)\n  if fill.length == 0 { return self }\n  self + fill\n}\n\n// ── ASCII case ─────────────────────────────────────────────────────────────\n\n// The distance from `c` to its ASCII case counterpart, or 0 when it has none — the one place\n// the alphabet is named, so `mapAsciiCase` carries no direction logic and neither exported\n// wrapper carries any at all.\n//\n// Every code point outside `a`–`z` / `A`–`Z` maps to 0 and therefore passes through UNCHANGED.\n// That includes every non-ASCII character, which is the promise the `Ascii` suffix makes.\nfunction caseShift(c: i32, up: boolean): i32 {\n  if up {\n    if c >= 'a' && c <= 'z' { return -32 }\n    return 0\n  }\n  if c >= 'A' && c <= 'Z' { return 32 }\n  0\n}\n\n// The one case walk, shared by both exported directions.\n//\n// It SCANS before it builds: a string with nothing to change — already-upper\n// text, a number, a punctuation run, anything non-ASCII — is returned as it\n// arrived, with no buffer and no allocation. That matters because the common\n// call is a normalizing comparison (`a.toLowerAscii() == b.toLowerAscii()`)\n// where one side is usually already lower-case.\nfunction mapAsciiCase(self: string, up: boolean): string {\n  let hit = false\n  for cp in self {\n    if caseShift(cp, up) != 0 {\n      hit = true\n      break\n    }\n  }\n  if !hit { return self }\n  const buf: i32[] = []\n  for cp in self { buf.push(cp + caseShift(cp, up)) }\n  fromCodePoints(buf)\n}\n\n// `self` with every ASCII lower-case letter upper-cased. NOTHING else changes —\n// `\"é\"`, `\"ß\"` and every other non-ASCII character pass through untouched, and\n// the name says so. Full Unicode case mapping is a future `std:unicode`; see\n// the header for why it cannot be this function under a shorter name.\nexport function toUpperAscii(self: string): string { mapAsciiCase(self, true) }\n\n// `self` with every ASCII upper-case letter lower-cased. Same promise, same\n// limit, same reason for the name.\nexport function toLowerAscii(self: string): string { mapAsciiCase(self, false) }\n",
  "std:test": "// `std:test` v2 — the in-language testing surface (docs/internals/std-design.md D5), in two\n// halves over the intrinsic floor:\n//   1. REGISTRATION — jest-shaped `describe`/`it`/`beforeEach`/`afterEach`. Calling\n//      them at a file's top level REGISTERS into the parallel arrays below and does\n//      nothing else; the wasm start function runs that top level at instantiation,\n//      after which the registry is complete (two-phase collection — `describe`\n//      bodies are REGISTRATION-ONLY, the Deno-steps lesson).\n//   2. ASSERTION — `expect(...)` matchers, read jest-shaped through STRUCT-RECEIVER\n//      UFCS: `.toEqual` is a free `self`-function resolved by self+arity, a RANGE of\n//      arities since the matchers grew a defaulted `caller` tail. A failed assertion\n//      records its message and calls `__trap__()`; a passing one is a no-op.\n//\n// The `vlt*` exports at the bottom are the RUNNER PROTOCOL: the host reads the\n// registry through them and drives one test per call, which is what buys per-test\n// trap isolation, output attribution and filtering (docs/internals/test-runner-design.md).\n// `vl test` appends the re-export line; under bare `vl run` green exits 0, red aborts.\n//\n// `expect` is GENERIC — `expect<T>(value: T)` builds an `Expectation<T>`, so ONE\n// entry point covers every `==`-comparable value rather than v1's enumerated\n// `i32 | i64 | f64 | boolean | string`. `.toEqual` compares with the SAME `==` the\n// operands get outside a test, with ONE class of exception: a union T holding a\n// NON-ATOM member is check-clean invalid wasm where v1 refused it loudly at check\n// (the D941 family, inventory D947). By design, a cross-variant pair\n// (`expect(4).toEqual(\"4\")`) is now a COMPILE-TIME refusal since no single T fits\n// both operands, a literal-union receiver keeps its own T and renders the\n// `<value>` sentinel, and a failure emits a SECOND LINE `  at <file>:<line>:<col>`.\n//\n// THE RECEIPT IS EAGER, and that deviation is chosen. The five atoms keep v1's\n// exact rendering; any other T renders the honest sentinel `\"<value>\"` until\n// reflection exists. Every T-dependent fact is computed ONCE inside `expect` from\n// the RAW parameter, because the LAZY spellings are the miscompiling ones (D941\n// re-forwards a generic param, D942 mis-answers `is` on the carrier field, D943\n// captures the generic value, D944 widens then narrows), so the render ladder lives\n// once in `vltShow<T>(value: T)` over a raw value. The private `VltAtomReps` alias\n// is the same family: an `is`-atom arm a union T cannot hold is dead but still\n// EMITS and needs an atom value box a module mints only for its own unions (D947).\n//\n// ONE VL RULE GOVERNS THIS FILE'S SHAPE: a function's result type is its TAIL\n// statement's and a test BODY is `() => void`, so every function a body can end\n// with must be void — hence `vltDone()` and matchers closing with a call, not an `if`.\n\n// ── WHERE THE FAILURE HAPPENED — `CallerLoc` and the one-hop rule ──────────────\n// A failed assertion names its own call site, through default arguments v1\n// (DECISIONS \"Default arguments v1\"): each MATCHER's trailing\n// `caller: CallerLoc = __callsite__` is filled by the compiler AT THE CALL, in\n// the caller's frame. THE MATCHER IS THE ANCHOR, NOT `expect` — `expect(x)` and\n// `not()` are setup and decide nothing, so `expect(x).not().toEqual(y)` anchors\n// on the FINAL matcher's token, which is where the assertion actually is. A\n// second hand-in point would need a precedence rule defaults v1 cannot express,\n// since a callee cannot tell a supplied argument from an omitted one. ONE HOP,\n// NEVER A CHAIN: a wrapper takes its own `caller: CallerLoc = __callsite__` and\n// forwards it EXPLICITLY; nothing here walks a parent link. `vltFail`'s `loc` is\n// REQUIRED, not defaulted, so a matcher added later cannot report without one.\n\n// A CALL SITE, as a value. `file` is the caller's module key — the same string\n// `vl test` prints as its file header, spelled exactly as the CLI target was;\n// `line`/`col` are 1-based and anchor on the CALLEE's own token, which is what\n// Swift's `#line` and Rust's `Location::caller()` name for the same call.\n//\n// THE NAME IS STD'S, THE SHAPE IS THE COMPILER'S: `__callsite__` is checked\n// STRUCTURALLY against exactly `{ file: string, line: i32, col: i32 }` (field\n// order free), so any identical alias satisfies it and growing `CallerLoc` is a\n// COMPILER change, not a std one. It is exported because a forwarding helper has\n// to name the type in its signature; it is not in `std:fmt` because this module's\n// dependency surface is deliberately ZERO, and not its own module because one\n// three-field alias does not earn a module key a version-locked std cannot undo.\nexport type CallerLoc = { file: string, line: i32, col: i32 }\n\n// ── the registry ────────────────────────────────────────────────────────────────\n// PARALLEL ARRAYS, the compiler driver's own idiom (`modKeys`/`modPending`/…): one\n// entry per registered test, index `i` is the protocol's test id.\nconst vltNames: string[] = []        // the test's full path (scope > … > name)\nconst vltBodies: (() => void)[] = [] // its body\nconst vltSkips: i32[] = []           // 1 = registered by `itSkip`\nconst vltScopes: string[] = []       // the enclosing `describe` path (hook matching)\n\n// The `describe` path currently being registered into (\"\" at file scope). Saved and\n// restored around each `describe` body, so nesting composes.\nlet vltScope = \"\"\n\n// Hooks, also parallel: each records the `describe` scope it was declared in, and\n// runs around every test at or beneath that scope.\nconst vltBeforeScopes: string[] = []\nconst vltBeforeFns: (() => void)[] = []\nconst vltAfterScopes: string[] = []\nconst vltAfterFns: (() => void)[] = []\n\n// The rendered message of the assertion that just aborted the running test. The\n// runner reads it AFTER catching the trap (`vltFailLen`/`vltFailAt`) — a trap\n// unwinds the call but leaves the instance readable — so a failure reports its\n// message structurally instead of being scraped out of print output.\nlet vltFailMsg = \"\"\n\n// A VOID no-op — the tail that makes a function whose real work ends in an\n// assignment or a `.push` still type as `() -> void`. See the rule above.\nfunction vltDone() {}\n\n// The same no-op, EXPORTED, for closing a test body whose last real statement\n// yields a value:\n//\n//   beforeEach(() => { hits = hits + 1  done() })\n//\n// Without it that body types as `() => i32` and the registration call rejects it\n// with `expected () -> void, got () -> i32`. A body ending in an `expect(…)`\n// matcher — the overwhelming majority — needs nothing. (The language-level fix is\n// void-return covariance on function values, which is not free: the array's\n// element type IS the interned `$fnsig`, so it needs a real coercion, not a\n// relaxed check. Filed in docs/internals/vl-test-design.md §Known gaps.)\nexport function done() {}\n\n// ── registration ────────────────────────────────────────────────────────────────\n\n// Group the tests registered by `body` under `name`. REGISTRATION ONLY: the body\n// runs at collect time, so it must do nothing but declare tests and hooks (any\n// real work would run once, at the wrong time, for every test in the file).\nexport function describe(name: string, body: () => void) {\n  const saved = vltScope\n  if vltScope.length > 0 {\n    vltScope = vltScope + \" > \" + name\n  } else {\n    vltScope = name\n  }\n  body()\n  vltScope = saved\n  vltDone()\n}\n\n// The shared registration path. `path` is the scope-qualified name the report and\n// the `-t` filter both match against.\nfunction vltRegister(name: string, body: () => void, skip: i32) {\n  let path = name\n  if vltScope.length > 0 { path = vltScope + \" > \" + name }\n  vltNames.push(path)\n  vltBodies.push(body)\n  vltSkips.push(skip)\n  vltScopes.push(vltScope)\n  vltDone()\n}\n\n// Register one test.\nexport function it(name: string, body: () => void) {\n  vltRegister(name, body, 0)\n}\n\n// Register one test as SKIPPED — it is collected, reported, and never run (the\n// `#[ignore]`/`@Disabled` analog; `.skip` is not spellable because VL has no\n// property access on a function value).\nexport function itSkip(name: string, body: () => void) {\n  vltRegister(name, body, 1)\n}\n\n// Run `body` before each test at or beneath the enclosing `describe` scope.\nexport function beforeEach(body: () => void) {\n  vltBeforeScopes.push(vltScope)\n  vltBeforeFns.push(body)\n  vltDone()\n}\n\n// Run `body` after each test at or beneath the enclosing `describe` scope.\n// Registration order is preserved; `vltRun` fires them in REVERSE, so hooks nest\n// like scopes do (outermost `before` first, outermost `after` last).\nexport function afterEach(body: () => void) {\n  vltAfterScopes.push(vltScope)\n  vltAfterFns.push(body)\n  vltDone()\n}\n\n// Does a hook declared at scope `hook` apply to a test whose scope is `test`? The\n// file scope (\"\") applies to everything; otherwise `test` must be `hook` itself or\n// one of its descendants — a PATH-SEGMENT prefix test, so a `describe(\"list\")`\n// hook does not leak into `describe(\"listener\")`.\nfunction vltInScope(hook: string, test: string) {\n  if hook.length == 0 { return 1 }\n  if hook == test { return 1 }\n  const sep = hook + \" > \"\n  if test.length >= sep.length {\n    const head = test.slice(0, sep.length)\n    if head == sep { return 1 }\n  }\n  0\n}\n\n// ── assertion ───────────────────────────────────────────────────────────────────\n\n// The RECEIPT (see the header): the value at its own type, plus every T-dependent\n// fact the matchers will need, computed once in `expect` from the raw parameter.\n//   shown    — the failure-message rendering (v1's atom forms; `\"<value>\"` otherwise)\n//   isBool / boolVal — `toBeTrue`/`toBeFalse` decide from these, so a non-boolean\n//              receiver keeps v1's semantics (compiles, fails at runtime)\n//   hasEcho / echo   — an f64's digits, printed on failure because the message\n//              renders f64 as `<f64>`: this module's dependency surface is zero\n//              by design, so it will not import `std:fmt` to render one\n//\n// The receipt carries NO location: the MATCHER owns it (the `CallerLoc` section\n// above), so it is the matcher's own parameter, filled at its own call, and reaches\n// `vltFail` straight from there without entering the receipt.\ntype Expectation<T> = {\n  actual: T,\n  negated: boolean,\n  shown: string,\n  isBool: boolean,\n  boolVal: boolean,\n  hasEcho: boolean,\n  echo: f64\n}\n\n// PRIVATE, and never named by a signature: its REGISTRATION is the point (the\n// header's union paragraph, inventory D947). Declaring this five-atom value\n// union mints the i32/i64/f64 value-box heap types and the string payload type\n// in every module that links std:test, so a generic `is` ladder instantiated\n// at a union T that lacks some atom still VALIDATES (the missing-atom arms are\n// dead at runtime; only their emitted casts need the types to exist). This is\n// the side effect v1's five-atom receiver union had by existing, kept as one\n// line. Remove only when D947 closes compiler-side.\ntype VltAtomReps = i32 | i64 | f64 | boolean | string\n\n// `expect(value)` — the receiver for the matchers. T is inferred from the\n// argument, so a call site reads exactly as it did under the v1 union. The\n// `is`-dispatch here is over the RAW parameter — the one placement today's\n// monomorphizer answers correctly for every T (see the header); the rendering\n// lives in `vltShow`, and the two arms kept here bank the receipt facts a\n// rendering cannot carry (which boolean; the f64 echo). Each non-atom\n// instantiation prunes the atom arms and keeps the defaults.\n//\n// `expect` takes no location. It is the SETUP — it decides nothing, so it\n// reports nothing — and the matcher that decides is the surface that asks\n// (the `CallerLoc` section above).\nexport function expect<T>(value: T): Expectation<T> {\n  let isBool = false\n  let boolVal = false\n  let hasEcho = false\n  let echo = 0.0\n  if value is boolean {\n    isBool = true\n    boolVal = value\n  }\n  if value is f64 {\n    hasEcho = true\n    echo = value\n  }\n  return {\n    actual: value,\n    negated: false,\n    shown: vltShow(value),\n    isBool: isBool,\n    boolVal: boolVal,\n    hasEcho: hasEcho,\n    echo: echo,\n  }\n}\n\n// Inverts the pass/fail sense: `expect(5).not().toEqual(6)` passes. Returns a\n// fresh `Expectation` (the receiver is a value; no aliasing) carrying the same\n// receipt.\n//\n// NO `caller` OF ITS OWN, and that is the matcher rule holding rather than an\n// omission: `not()` decides nothing either, and the matcher after it is the one\n// that reports. `expect(1).not().toEqual(1)` anchors on the `.toEqual` token,\n// the FINAL matcher and the position the ruling names. A `caller` here would be\n// a second location for one failure with no rule saying which wins.\nexport function not<T>(self: Expectation<T>): Expectation<T> {\n  return {\n    actual: self.actual,\n    negated: !self.negated,\n    shown: self.shown,\n    isBool: self.isBool,\n    boolVal: self.boolVal,\n    hasEcho: self.hasEcho,\n    echo: self.echo,\n  }\n}\n\n// Record the rendered message and abort the test. The runner catches the trap,\n// reads `vltFailMsg` back, and continues with the next test. Void: its tail is\n// `__trap__()`, which yields nothing (and never returns).\nfunction vltAbort(msg: string) {\n  vltFailMsg = msg\n  __trap__()\n}\n\n// One decimal digit as its character. i64 so both integer widths share the\n// renderer (i64 cannot narrow to i32, so a string-index lookup is not expressible\n// for the wide path). Mirrors `std:fmt`'s technique rather than importing it —\n// and the reason is INDEPENDENCE, not import inability (std modules do import\n// each other: `fmt` ← `str`, `utf8` ← `fmt`, measured): this is the assertion\n// surface that reports failures in everything else, `std:fmt` included. A defect\n// in fmt's renderer must not be able to corrupt the very message that reports\n// it, and the D941-family history around this module's receipt machinery says\n// keep its dependency surface at zero. The knowingly-kept copy is named in\n// `std:utf8`'s one-renderer ruling, and `tests/cases/std/renderers-agree.vl`\n// pins the two against each other at i64 min so they cannot drift silently.\nfunction vltDigit(d: i64) {\n  if d == 0 { return \"0\" }\n  if d == 1 { return \"1\" }\n  if d == 2 { return \"2\" }\n  if d == 3 { return \"3\" }\n  if d == 4 { return \"4\" }\n  if d == 5 { return \"5\" }\n  if d == 6 { return \"6\" }\n  if d == 7 { return \"7\" }\n  if d == 8 { return \"8\" }\n  \"9\"\n}\n\n// Decimal rendering of any i64, i64 min included: the accumulator works in the\n// NEGATIVE range (positive inputs are negated first) because the negative range\n// covers i64 min, whose magnitude overflows when negated.\nfunction vltI64Str(v: i64) {\n  if v == 0 { return \"0\" }\n  let n = v\n  let neg = false\n  if v > 0 { n = 0 - v } else { neg = true }\n  let out = \"\"\n  while n < 0 {\n    const d = 0 - (n % 10)\n    out = vltDigit(d) + out\n    n = n / 10\n  }\n  if neg { return \"-\" + out }\n  out\n}\n\n// THE render ladder — one home (the header): v1's exact atom forms, the\n// `\"<value>\"` sentinel for any other T. Generic over a RAW value, the one\n// placement today's monomorphizer answers correctly for every T measured, and\n// called from both `expect` (the receipt's `shown`) and `toEqual` (its\n// `expected` side). NO side effects: an f64 renders `<f64>` here and its\n// digits are echoed by the FAILURE paths alone, so the eager receipt call\n// cannot print.\nfunction vltShow<T>(value: T): string {\n  let shown = \"<value>\"\n  if value is string { shown = \"\\\"\" + value + \"\\\"\" }\n  if value is boolean {\n    if value { shown = \"true\" } else { shown = \"false\" }\n  }\n  if value is i32 { shown = vltI64Str(value as! i64) }\n  if value is i64 { shown = vltI64Str(value) }\n  if value is f64 { shown = \"<f64>\" }\n  shown\n}\n\n// `file:line:col`, or \"\" when the location cannot name a file. The empty case is\n// unreachable through this module — every consumer imports `std:test`, which is a\n// module table, and only a table-less single-source compile answers `\"\"` — but a\n// message reading `at :9:1` would be worse than one with no location at all, so\n// the guard is here rather than assumed away.\nfunction vltLocStr(loc: CallerLoc) {\n  if loc.file.length == 0 { return \"\" }\n  loc.file +\n    \":\" +\n    vltI64Str(loc.line as! i64) +\n    \":\" +\n    vltI64Str(loc.col as! i64)\n}\n\n// Assemble the failure message from ALREADY-RENDERED strings and abort. Reached\n// ONLY on failure. Non-generic on purpose: everything T-shaped was resolved by\n// the callers, so this is one shared body, not one per instantiation.\n// `kind`: 0 = toEqual, 1 = toBeTrue, 2 = toBeFalse.\n//\n// The location rides on its OWN LINE, `\"\\n  at <file>:<line>:<col>\"`, and it is\n// the LAST line. **THIS MODULE OWNS THE INVARIANT \"THE LOCATION LINE IS LAST\",\n// AND NOTHING MAY BE APPENDED AFTER IT** — a rendered operand is arbitrary user\n// text and can carry a perfectly anchored forgery, so the reader gets the right\n// line only because `lsp/src/testDiscovery.ts` takes the LAST match. A line\n// appended here silently re-anchors every failure in the editor; add it BEFORE\n// the location. A handed-in `CallerLoc` is the caller's CLAIM, not std's finding.\nfunction vltFail(\n  shownA: string,\n  negated: boolean,\n  kind: i32,\n  shownE: string,\n  loc: CallerLoc,\n) {\n  let tail = \"be true\"\n  if kind == 0 { tail = \"equal \" + shownE }\n  if kind == 2 { tail = \"be false\" }\n  let sense = \"to \"\n  if negated { sense = \"not to \" }\n  let msg = \"expected \" + shownA + \" \" + sense + tail\n  const at = vltLocStr(loc)\n  if at.length > 0 { msg = msg + \"\\n  at \" + at }\n  vltAbort(msg)\n}\n\n// `.toEqual` — equality at T's own `==`, jest semantics: value equality per\n// element/field wherever the language defines it. Both operands are T, so a\n// cross-variant pair (`expect(4).toEqual(\"4\")`) refuses at compile time — see the\n// header. `self.actual` binds to a local first: `==` requires binding operands,\n// not a raw field read. The failure path renders `expected` from the raw\n// parameter (never from a field — the header's placement rule) and echoes f64\n// operands in v1's order: actual first, expected second, message last.\n// `caller` is the ONE parameter a call site normally omits: the compiler fills\n// it with THIS call's own position, which on a UFCS spelling is the `.toEqual`\n// token (the `CallerLoc` section above). Pass it explicitly to forward a\n// wrapper's location — `expect(v).toEqual(1, caller)` inside a helper that took\n// `caller: CallerLoc = __callsite__`.\nexport function toEqual<T>(\n  self: Expectation<T>,\n  expected: T,\n  caller: CallerLoc = __callsite__,\n) {\n  const a = self.actual\n  const ok = a == expected\n  let bad = !ok\n  if self.negated { bad = ok }\n  if bad {\n    if self.hasEcho { print(self.echo) }\n    if expected is f64 { print(expected) }\n    vltFail(self.shown, self.negated, 0, vltShow(expected), caller)\n  }\n  vltDone()\n}\n\n// `.toBeTrue` — the receiver holds boolean `true`. A non-boolean receiver is\n// never true (its receipt has `isBool = false`), so `expect(5).toBeTrue()` still\n// compiles and still fails at runtime with `expected 5 to be true` — v1's\n// semantics, kept. IT STAYS GENERIC (`Expectation<T>`) rather than taking the\n// strict `Expectation<boolean>`: tightening would turn that documented runtime\n// failure into a compile-time break, which is a surface decision to make on its\n// own rather than a rider, so it is DEFERRED deliberately.\n//\n// Takes the same trailing `caller: CallerLoc = __callsite__` as `toEqual` (the\n// `CallerLoc` section above). Forwarding a wrapper's location is\n// `expect(v).toBeTrue(caller)`, where it is the ONLY argument.\nexport function toBeTrue<T>(\n  self: Expectation<T>,\n  caller: CallerLoc = __callsite__,\n) {\n  let ok = false\n  if self.isBool { ok = self.boolVal }\n  let bad = !ok\n  if self.negated { bad = ok }\n  if bad { vltFail(self.shown, self.negated, 1, self.shown, caller) }\n  vltDone()\n}\n\n// `.toBeFalse` — the receiver holds boolean `false`. Non-boolean receivers fail\n// at runtime, as in `toBeTrue`. Same trailing\n// `caller: CallerLoc = __callsite__`, forwarded as `expect(v).toBeFalse(caller)`.\nexport function toBeFalse<T>(\n  self: Expectation<T>,\n  caller: CallerLoc = __callsite__,\n) {\n  let ok = false\n  if self.isBool { ok = !self.boolVal }\n  let bad = !ok\n  if self.negated { bad = ok }\n  if bad { vltFail(self.shown, self.negated, 2, self.shown, caller) }\n  vltDone()\n}\n\n// Fail the running test outright with `msg` — the escape hatch for a condition no\n// matcher expresses (`if !reachedTheBranch { fail(\"unreachable\") }`). It takes NO\n// `CallerLoc` in this version: one surface at a time, and its argument is the\n// author's own sentence rather than a rendered assertion. The deferral is cheap by\n// the mechanism track-caller introduced — a trailing default is ADDITIVE, so\n// `fail(msg, caller: CallerLoc = __callsite__)` can land later without breaking a\n// caller. Until it does, `msg` is a wire format the author can WRITE: a hand-typed\n// `\"\\n  at /not/real.vl:1:1\"` reaches the editor as a location, and std does not\n// vouch for it there.\n// No `toBe`, `toThrow` or `toBeNull` yet: they wait on `===` (ROADMAP A15), the\n// error model and `null` handling (std-design OD6).\nexport function fail(msg: string) { vltAbort(msg) }\n\n// ── the runner protocol ─────────────────────────────────────────────────────────\n// Read by the host after instantiation (the start function has just registered\n// everything). Strings cross one code point at a time — the driver's\n// `modPendingCount`/`modPendingLen`/`modPendingAt` idiom, which the host already\n// speaks. `vl test` re-exports these into each `*.test.vl` module it compiles.\n\n// How many tests this file registered.\nexport function vltCount(): i32 { vltNames.length }\n\n// Code-point length of test `i`'s scope-qualified name.\nexport function vltNameLen(i: i32): i32 { vltNames[i].length }\n\n// Code point `j` of test `i`'s name.\nexport function vltNameAt(i: i32, j: i32): i32 { vltNames[i][j] }\n\n// 1 when test `i` was registered by `itSkip`.\nexport function vltSkipped(i: i32): i32 { vltSkips[i] }\n\n// Run test `i` with its hook chain. 0 = passed, 1 = skipped; a FAILURE does not\n// return — the assertion traps, and the host reads `vltFail*` for the message.\nexport function vltRun(i: i32): i32 {\n  vltFailMsg = \"\"\n  if vltSkips[i] != 0 { return 1 }\n  const scope = vltScopes[i]\n  let h = 0\n  while h < vltBeforeScopes.length {\n    if vltInScope(vltBeforeScopes[h], scope) != 0 {\n      const before = vltBeforeFns[h]\n      before()\n    }\n    h = h + 1\n  }\n  const body = vltBodies[i]\n  body()\n  let a = vltAfterScopes.length - 1\n  while a >= 0 {\n    if vltInScope(vltAfterScopes[a], scope) != 0 {\n      const after = vltAfterFns[a]\n      after()\n    }\n    a = a - 1\n  }\n  0\n}\n\n// Code-point length of the last failure message (0 = the trap carried none, e.g. a\n// raw `__trap__()` or an out-of-bounds index rather than a failed expectation).\nexport function vltFailLen(): i32 { vltFailMsg.length }\n\n// Code point `j` of the last failure message.\nexport function vltFailAt(j: i32): i32 { vltFailMsg[j] }\n",
  "std:utf8": "// `std:utf8` — the boundary between VL's strings and the byte world.\n//\n// A VL `string` IS its UTF-8 bytes: `s.length` is a byte count and `s[i]` is a byte\n// (`docs/guide/strings-design.md` §Storage/§API; code points live on `for cp in s` and\n// `s.cpAt(i)`). A `u8[]` is bytes too — `u8` is a STORAGE type, so an element reads out\n// widened to `i32` (0..255) and truncates on write. The two sides no longer differ in\n// STORAGE, so what is left here is the part that never was storage: VALIDATION, POSITIONED\n// ERROR REPORTING AND SANITIZATION. §Validity is deliberately Go-lean — the core does no\n// validation at the host boundary and lets malformed bytes read as U+FFFD — so nothing in\n// the core will ever do those three. The module's audit is `docs/internals/utf8-byte-ready.md`.\n//\n// It is its own module rather than private to `std:fs` because `std:fs` is merely the FIRST\n// consumer: every boundary VL grows (files, paths, argv, stdin) is bytes, and a private copy\n// is how a program ends up with two decoders holding two opinions about invalid input.\n//\n// THE INVALID-INPUT RULING, both directions, because it is the whole design:\n//\n//   ENCODE IS TOTAL, AND RAW. `encodeUtf8` cannot fail and never repairs: it hands back the\n//   storage bytes unexamined (§Wrap), so a string holding a partial sequence round-trips\n//   through `encodeUtf8`/`decodeUtf8` as itself. A caller who wants a well-formed result\n//   composes it — `decodeUtf8Lossy(s.bytes())` — and pays visibly. A non-scalar cannot reach\n//   here at all: the core substitutes U+FFFD in `fromCodePoints` (§NonScalar), so this\n//   module keeps no substitution branch that could drift from that one.\n//\n//   DECODE IS FALLIBLE, AND STRICT BY DEFAULT. `decodeUtf8` returns `string | Utf8Error` and\n//   rejects every ill-formed sequence: bad lead byte, bad continuation, overlong form,\n//   surrogate, beyond U+10FFFF, truncated tail. That is Rust's `from_utf8`, not\n//   `from_utf8_lossy`, and strict is the DEFAULT because a decode failure is information:\n//   those bytes are not text, and the program about to treat them as text is about to be\n//   wrong. Substituting silently would turn \"this is a PNG\" into question marks that compare\n//   unequal to everything and explain nothing. `decodeUtf8Lossy` is the deliberate opt-out\n//   for a caller who would rather render mojibake than stop — a log tailer, an editor — and\n//   substitutes one U+FFFD per maximal ill-formed subpart, which is the WHATWG rule.\n//\n// WHAT THIS MODULE DOES NOT DO. No UTF-16, no other encodings, no BOM handling (a leading\n// U+FEFF decodes to U+FEFF and stays in the string — stripping it is a policy for whoever\n// knows the format), no normalization, no grapheme or display-width analysis. Those are not\n// \"later here\"; they are a different module.\n\n// `toString` is `std:fmt`'s export, not the ambient compiler builtin it once was (owner\n// ruling, DECISIONS.md), so the two digit renderings in `decodeCore`'s error message make\n// `std:fmt` a module dependency of this one.\n//\n// A private decimal renderer here — and another in `std:fs`, and another in `std:args` — is\n// REFUSED for the reason `std:fmt`'s header gives about `split`: one implementation beats\n// smaller output, and three copies that must agree about i32 min is exactly the drift that\n// ruling protects against. VL has no cross-module dead-code elimination, so an unoptimized\n// module carries all of `std:str` and `std:fmt` for one i32 rendering; binaryen's DCE at\n// `-O3` removes almost all of it. ONE copy is knowingly kept: `std:test`'s `vltI64Str`, so\n// the assertion surface stays dependency-free and a fmt defect cannot corrupt its own\n// failure report; `tests/cases/std/renderers-agree.vl` pins the two at i64 min.\nimport { toString } from \"std:fmt\"\n\n// A decode failure, carrying the position AND the offending byte.\n//\n// `at` is a BYTE OFFSET — ruled, see `docs/internals/utf8-byte-ready.md` §at — and RELATIVE\n// to the `off` passed in, never an absolute index, so it stays meaningful to a caller\n// decoding a slice out of a larger array, exactly as Rust's `Utf8Error::valid_up_to()` is.\n// `s.slice(0, e.at)` is therefore the valid prefix with no converter, and — decode being a\n// byte identity — `at` is at the same time the byte length of that prefix\n// (`tests/cases/std/utf8-invariant.vl` §6). `byte` is the lead byte that failed to decode.\n//\n// `byte` ALSO KEEPS THIS TYPE DISTINCT: VL aliases are STRUCTURAL, so the `{ at, msg }` shape\n// `error-handling-design.md` §90 blesses as `ParseError` is literally this type, and a union\n// naming both would fail at emit with no recorded members.\nexport type Utf8Error = { at: i32, byte: i32, msg: string }\n\n// U+FFFD, substituted in both directions.\nconst REPLACEMENT = 0xFFFD\n\n// THE ENCODE SIDE'S NON-SCALAR RULING LIVES IN THE CORE, NOT HERE. A string can no longer\n// hold a lone surrogate or a value past U+10FFFF: `fromCodePoints` substitutes U+FFFD, and\n// `print` streams the stored replacement bytes rather than dropping them\n// (`docs/internals/utf8-byte-ready.md` §NonScalar). `scalar`/`utf8Width` were deleted rather\n// than kept as defensive documentation of that rule, because a second copy of a rule is a\n// thing that can disagree with the first, and dead code cannot be caught disagreeing.\n\n// `s.utf8Length()` — the exact length of `s.encodeUtf8()`. A string IS its UTF-8 bytes, so\n// this is `self.length` and O(1) (`docs/internals/utf8-byte-ready.md` §utf8Length).\n//\n// The collapse is sound only because §Wrap ruled `encodeUtf8` RAW: a string holding\n// malformed bytes — legal, since slicing off a character boundary is permitted (§Validity) —\n// keeps those bytes through `encodeUtf8`, so `.length` counts exactly what the encoder\n// emits. Decoding to code points and re-measuring each would instead answer 3 per\n// replacement character and disagree with this module's own encoder.\nexport function utf8Length(self: string) { self.length }\n\n// `s.encodeUtf8()` — `s` as UTF-8 bytes. A string is already its UTF-8 bytes, so this is\n// `self.bytes()`: one `array.copy`, at memcpy speed.\n//\n// RAW, not sanitized (`docs/internals/utf8-byte-ready.md` §Wrap): `bytes()` hands back the\n// storage bytes unexamined, so a string holding a partial sequence round-trips through\n// `encodeUtf8`/`decodeUtf8` as itself rather than being silently repaired. A caller who\n// wants the guarantee composes it — `decodeUtf8Lossy(s.bytes())` — and pays visibly.\n//\n// FRESH, not a view (§Ownership), so the contract is unchanged: `s.bytes()` COPIES, because\n// a `u8[]` wrapper has no `start` field and cannot express a view of a sliced string, and\n// because a `u8[]` is MUTABLE — an aliasing `bytes()` would hand out a writable pointer into\n// an immutable string's storage. The result is the fresh, growable array callers always got.\nexport function encodeUtf8(self: string): u8[] { return self.bytes() }\n\n// The one decode loop. The strict/lossy fork is a PARAMETER rather than two copies, so the\n// two public spellings cannot disagree about what \"ill-formed\" means.\n//\n// The validity table is the standard one; every row rejects a sequence a naive shift-and-or\n// would decode. Accepting one is the classic security bug — two byte strings decoding to one\n// string is how a path check that already ran gets walked past.\n//   C0 C1        overlong two-byte forms of ASCII\n//   E0 80..9F    overlong three-byte forms\n//   ED A0..BF    the surrogate block\n//   F0 80..8F    overlong four-byte forms\n//   F4 90..BF    beyond U+10FFFF\n//   F5..FF       no such lead byte\nfunction decodeCore(\n  self: u8[],\n  off: i32,\n  len: i32,\n  lossy: boolean,\n): string | Utf8Error {\n  const cps: i32[] = []\n  let i = 0\n  while i < len {\n    const b0 = self[off + i]\n    // The sequence length comes from the lead byte, together with the TIGHTENED\n    // bounds the FIRST continuation byte must satisfy (every later one is the\n    // plain 0x80..0xBF).\n    let size = 0\n    let cp = 0\n    let lo = 0x80\n    let hi = 0xBF\n    if b0 < 0x80 {\n      size = 1\n      cp = b0\n    } else if b0 >= 0xC2 && b0 <= 0xDF {\n      size = 2\n      cp = b0 & 0x1F\n    } else if b0 >= 0xE0 && b0 <= 0xEF {\n      size = 3\n      cp = b0 & 0x0F\n      if b0 == 0xE0 { lo = 0xA0 }\n      if b0 == 0xED { hi = 0x9F }\n    } else if b0 >= 0xF0 && b0 <= 0xF4 {\n      size = 4\n      cp = b0 & 0x07\n      if b0 == 0xF0 { lo = 0x90 }\n      if b0 == 0xF4 { hi = 0x8F }\n    }\n    // `good` counts the MAXIMAL VALID SUBPART — how far the sequence got before\n    // it went wrong, never less than 1. It is what the lossy path advances by,\n    // so a truncated 4-byte sequence at the end of the range yields ONE U+FFFD\n    // rather than one per leftover byte. That is the WHATWG rule, and it is also\n    // the only advance that cannot loop: `good >= 1` always.\n    let ok = size > 0\n    let good = 1\n    let k = 1\n    while ok && k < size {\n      if i + k >= len {\n        ok = false\n      } else {\n        const b = self[off + i + k]\n        let blo = 0x80\n        let bhi = 0xBF\n        if k == 1 {\n          blo = lo\n          bhi = hi\n        }\n        if b < blo || b > bhi {\n          ok = false\n        } else {\n          cp = (cp << 6) | (b & 0x3F)\n          good = good + 1\n        }\n      }\n      k = k + 1\n    }\n    if ok {\n      cps.push(cp)\n      i = i + size\n    } else if lossy {\n      cps.push(REPLACEMENT)\n      i = i + good\n    } else {\n      return {\n        at: i,\n        byte: b0,\n        msg: \"invalid UTF-8: byte \" + toString(b0) + \" at offset \" + toString(i),\n      }\n    }\n  }\n  fromCodePoints(cps)\n}\n\n// `b.decodeUtf8()` — the whole array as a string, or the position of the first\n// ill-formed sequence. STRICT; see the header for why strict is the default.\nexport function decodeUtf8(self: u8[]): string | Utf8Error {\n  decodeCore(self, 0, self.length, false)\n}\n\n// `b.decodeUtf8At(off, len)` — the same, over one range. The range form exists\n// because a consumer that splits a byte block into records (`std:fs`'s\n// directory listing, a line reader) must attribute a decode failure to the\n// RECORD, not to the block.\nexport function decodeUtf8At(\n  self: u8[],\n  off: i32,\n  len: i32,\n): string | Utf8Error {\n  decodeCore(self, off, len, false)\n}\n\n// `b.decodeUtf8Lossy()` — the whole array, with one U+FFFD per maximal ill-formed subpart.\n// Total: there is no input this rejects.\n//\n// IT IS A SANITIZER, NOT A DECODER, and that is why it does not collapse into the core's\n// lenient wrap. §Validity is Go-lean: a string is bytes that are *usually* UTF-8, so the core\n// will wrap ill-formed bytes and let them read as U+FFFD only when something iterates them —\n// and that wrap KEEPS THE ORIGINAL BYTES, which `s.bytes()` hands back unchanged and\n// `s.length` counts. This function REWRITES them: what comes out is guaranteed well-formed\n// UTF-8, whose bytes are EF BF BD where the bad bytes were, and the original is gone. Go\n// draws the same line between `string(b)` and `strings.ToValidUTF8`. A caller who wants\n// \"show me something\" wants the wrap; one who wants \"bytes I can hand onward as text\" wants\n// this.\nexport function decodeUtf8Lossy(self: u8[]) {\n  const r = decodeCore(self, 0, self.length, true)\n  // Unreachable: the lossy path substitutes rather than returning the error arm.\n  // The narrowing is what makes the `string` return type provable, and the trap\n  // is what makes a future edit that breaks the invariant loud instead of\n  // silent — VL has no way to say \"this arm cannot happen\" in a type.\n  if r is Utf8Error {\n    __trap__(\"std:utf8: lossy decode reported an error\")\n    return \"\"\n  }\n  r\n}\n",
};
